using System.Globalization;
using System.Text;

namespace Harborline.Foundation.RuleEngine;

/// <summary>
/// Canonical <see cref="double"/> → string formatting that is byte-identical to
/// ECMAScript <c>Number::toString</c> (ECMA-262 §6.1.6.1.20) — i.e. the TS tier's
/// <c>String(n)</c> (SPINE-1 cross-tier guarantee; finding F1). .NET's own shortest
/// round-trip ("R") yields the same significant digits as V8/JS (the shortest
/// representation of a double is unique) but lays them out differently: uppercase
/// <c>E</c>, a zero-padded signed exponent, and a different decimal-vs-exponential
/// threshold (e.g. .NET <c>"1E+16"</c> / <c>"1E-07"</c> vs JS
/// <c>"10000000000000000"</c> / <c>"1e-7"</c>). This routine reformats those shortest
/// digits per the ECMAScript algorithm so both engines serialize a given number to
/// the identical bytes.
/// </summary>
internal static class CanonicalNumber
{
    private const long JsMaxSafeInteger = 9007199254740991L; // 2^53 - 1

    /// <summary>The ECMAScript <c>Number::toString</c> of an integral value.</summary>
    public static string ToJsonString(long l)
        => l >= -JsMaxSafeInteger && l <= JsMaxSafeInteger
            ? l.ToString(CultureInfo.InvariantCulture)
            : ToJsonString((double)l); // beyond the JS safe range, JSON.parse would round to a double

    /// <summary>The ECMAScript <c>Number::toString</c> of a finite double.</summary>
    public static string ToJsonString(double d)
    {
        if (d == 0.0) return "0";                 // also -0 → "0" (ECMAScript String(-0) === "0")
        bool neg = d < 0;
        double abs = neg ? -d : d;

        // .NET Core's shortest round-trippable formatting — the same shortest decimal
        // digits ECMAScript uses (the shortest representation of a double is unique).
        string r = abs.ToString("R", CultureInfo.InvariantCulture);

        // Decompose `r` into significant digits `s` (k of them) and the ECMA exponent `n`,
        // where value = s × 10^(n - k).
        int ePos = r.IndexOfAny(new[] { 'E', 'e' });
        int exp = 0;
        string mant = r;
        if (ePos >= 0)
        {
            exp = int.Parse(r[(ePos + 1)..], CultureInfo.InvariantCulture);
            mant = r[..ePos];
        }
        int dot = mant.IndexOf('.');
        int pointPos;          // count of digits left of the decimal point within `mant`
        string allDigits;
        if (dot >= 0) { allDigits = mant.Remove(dot, 1); pointPos = dot; }
        else { allDigits = mant; pointPos = mant.Length; }
        int fracLen = allDigits.Length - pointPos;

        // Strip leading zeros (value-neutral), then trailing zeros (each adds one to the power).
        int lead = 0;
        while (lead < allDigits.Length - 1 && allDigits[lead] == '0') lead++;
        string sig = allDigits[lead..];
        int trail = 0;
        int sEnd = sig.Length;
        while (sEnd > 1 && sig[sEnd - 1] == '0') { sEnd--; trail++; }
        string s = sig[..sEnd];
        int k = s.Length;
        int n = k + trail + exp - fracLen;

        string body = Format(s, k, n);
        return neg ? "-" + body : body;
    }

    // ECMA-262 §6.1.6.1.20 — format the (positive) significant digits `s` (k of them)
    // and exponent `n` such that value = s × 10^(n - k).
    private static string Format(string s, int k, int n)
    {
        var sb = new StringBuilder();
        if (k <= n && n <= 21)
        {
            sb.Append(s);
            sb.Append('0', n - k);
        }
        else if (0 < n && n <= 21)
        {
            sb.Append(s, 0, n);
            sb.Append('.');
            sb.Append(s, n, k - n);
        }
        else if (-6 < n && n <= 0)
        {
            sb.Append("0.");
            sb.Append('0', -n);
            sb.Append(s);
        }
        else
        {
            sb.Append(s[0]);
            if (k > 1) { sb.Append('.'); sb.Append(s, 1, k - 1); }
            sb.Append('e');
            int e = n - 1;
            sb.Append(e >= 0 ? '+' : '-');
            sb.Append(Math.Abs(e).ToString(CultureInfo.InvariantCulture));
        }
        return sb.ToString();
    }
}

using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Model;


namespace Harborline.Foundation.RuleEngine.Compilation;

/// <summary>A reference extracted from a lowered rule AST (SPINE-1 design §2.1).</summary>
internal abstract record RuleRef;

/// <summary>A top-level field reference (<c>field.x</c>; <c>parent.f</c> and <c>section.id.f</c> lower here).</summary>
internal sealed record FieldRef(string Name) : RuleRef;

/// <summary>An expression-valued missing key.  This is not a field named <c>*</c>:</summary>
internal sealed record DynamicReadRef : RuleRef;

/// <summary>A same-row sibling-field reference (<c>row.y</c>) — valid only in a <see cref="RuleScope.Row"/> rule.</summary>
internal sealed record RowFieldRef(string Field) : RuleRef;

/// <summary>A table-aggregate reference (<c>agg(fn, section, col)</c>).</summary>
internal sealed record AggRef(string Section, string Fn, string Col) : RuleRef;

/// <summary>
/// A single rule lowered + analysed at publish-time (SPINE-1 design §2.2 step 1).
/// Immutable; carried alongside the definition version.
/// </summary>
internal sealed record CompiledRule
{
    public required RuleDefinition Source { get; init; }

    /// <summary>The lowered, normalized JsonLogic AST (canonical <c>field.</c>/<c>row.</c> vars + <c>agg</c>).</summary>
    public required JsonNode? Ast { get; init; }

    /// <summary>The output type this rule produces.</summary>
    public required OutputType OutputType { get; init; }

    /// <summary>References extracted statically from <see cref="Ast"/>.</summary>
    public required IReadOnlyList<RuleRef> References { get; init; }

    /// <summary>The static target cell for Field/Section/Schema/Table rules; null for Row rules (resolved per-row).</summary>
    public CellAddress? StaticTarget { get; init; }

    /// <summary>For a Row rule: the owning child-table section id.</summary>
    public string? RowSection { get; init; }

    /// <summary>For a Row rule: the targeted row field.</summary>
    public string? RowField { get; init; }
}

using System.Text.Json.Nodes;

namespace Harborline.Foundation.RuleEngine.Compilation;

/// <summary>Finite abstract result domain used by the only JsonLogic admission fence.</summary>
[Flags]
public enum CoreJsonType
{
    /// <summary>No possible result; the empty set.</summary>
    None = 0,
    /// <summary>JSON null.</summary>
    Null = 1,
    /// <summary>A JSON boolean.</summary>
    Boolean = 2,
    /// <summary>A JSON number.</summary>
    Number = 4,
    /// <summary>A JSON string, including dates and money, which travel as strings.</summary>
    String = 8,
    /// <summary>A JSON array.</summary>
    Array = 16,
    /// <summary>A JSON object.</summary>
    Object = 32,
    /// <summary>Any JSON value; the full set.</summary>
    AnyJson = Null | Boolean | Number | String | Array | Object,
}

/// <summary>
/// Derives every executable node's possible JSON result and possible runtime disposition.
/// It intentionally models the interpreter's coercions: arithmetic/date/money may still return a
/// coded runtime type error for dynamic scalar input; only a closed impossible container operand is
/// refused. Literal arrays and multi-key objects are data, never recursively executed.
/// </summary>
public static class CoreTypeDerivation
{
    /// <summary>What one expression node can produce at run time.</summary>
    /// <param name="Types">The set of JSON types the node may return.</param>
    /// <param name="CanError">True when evaluation may yield a coded runtime error instead of a value.</param>
    /// <param name="CanPending">True when evaluation may yield pending because an input is not yet resolved.</param>
    public sealed record Result(CoreJsonType Types, bool CanError = false, bool CanPending = false);

    /// <summary>
    /// Derives <paramref name="node"/>'s possible results, typing <c>var</c> reads through <paramref name="declaredInput"/> (any JSON when null).
    /// Throws the exception <paramref name="refusal"/> builds, or a <see cref="RuleEngineCodes.CompileInvalidExpression"/>
    /// <see cref="RuleCompilationException"/>, when an operator is given an operand type it can never coerce.
    /// </summary>
    public static Result Derive(JsonNode? node, string ruleId,
        Func<string, CoreJsonType>? declaredInput = null,
        Func<string, RuleCompilationException>? refusal = null)
    {
        Result Visit(JsonNode? value)
        {
            if (value is null) return new(CoreJsonType.Null);
            if (value is JsonArray) return new(CoreJsonType.Array);
            if (value is JsonValue scalar)
            {
                if (scalar.TryGetValue<bool>(out _)) return new(CoreJsonType.Boolean);
                if (scalar.TryGetValue<string>(out _)) return new(CoreJsonType.String);
                return new(CoreJsonType.Number);
            }
            if (value is not JsonObject expression || expression.Count != 1) return new(CoreJsonType.Object);
            var (op, rawArgs) = expression.First();
            var args = rawArgs is JsonArray array ? array.ToList() : new List<JsonNode?> { rawArgs };
            var children = args.Select(Visit).ToArray(); // Visit all executable operands, even short-circuited ones.
            Result Join(CoreJsonType types, bool error = false, bool pending = false)
                => new(types, error || children.Any(x => x.CanError), pending || children.Any(x => x.CanPending));
            void Require(string name, CoreJsonType accepted, params int[] positions)
            {
                foreach (var index in positions.Where(i => i < children.Length))
                {
                    var actual = children[index].Types;
                    if ((actual & accepted) == 0)
                        throw (refusal?.Invoke(name) ?? new RuleCompilationException(RuleEngineCodes.CompileInvalidExpression,
                            $"rule '{ruleId}': operator '{name}' cannot coerce a closed container operand.", ruleId));
                }
            }
            switch (op)
            {
                case "var":
                {
                    var path = args.Count == 0 ? "" : VarPath(args[0]);
                    var primary = declaredInput?.Invoke(path) ?? CoreJsonType.AnyJson;
                    // A statically known graph producer is always represented by its computed
                    // cell; an unresolved dynamic path may yield null.  Preserve that null only
                    // for the AnyJson (unproven) resolver contract.
                    var fallback = children.Length > 1 ? children[1].Types
                        : primary == CoreJsonType.AnyJson ? CoreJsonType.Null : CoreJsonType.None;
                    // A resolver may carry an upstream Error/Pending independently of its
                    // value's JSON kind.  The fallback is evaluated eagerly by the evaluator.
                    return Join(primary | fallback, error: true, pending: true);
                }
                case "missing": return Join(CoreJsonType.Array, error: true, pending: true);
                case "missing_some": return Join(CoreJsonType.Array, error: true, pending: true);
                case "==": case "!=": case "===": case "!==": case "!": case "!!":
                case ">": case ">=": case "<": case "<=": case "in": case "coding.is":
                    // Relational comparisons use numeric coercion; every comparison also
                    // evaluates children which can surface resolver failure.
                    return Join(CoreJsonType.Boolean, error: op is ">" or ">=" or "<" or "<=");
                case "and": case "or":
                    return Join(children.Length == 0
                        ? CoreJsonType.Boolean
                        : children.Aggregate(CoreJsonType.None, (set, child) => set | child.Types));
                case "if":
                {
                    var output = CoreJsonType.Null;
                    for (var i = 1; i < children.Length; i += 2) output |= children[i].Types;
                    if (children.Length % 2 == 1) output |= children[^1].Types;
                    return Join(output);
                }
                case "cat": return Join(CoreJsonType.String);
                case "+": case "-": case "*": case "/": case "%": case "min": case "max":
                    Require(op, CoreJsonType.Null | CoreJsonType.Boolean | CoreJsonType.Number | CoreJsonType.String, Enumerable.Range(0, children.Length).ToArray()); return Join(CoreJsonType.Number, error: true);
                case "money.add": case "money.sub": case "money.mul":
                    // Money and date are JSON strings at the evaluator boundary.  Do not add
                    // nominal JSON tags which would reject their valid scalar coercions.
                    Require(op, CoreJsonType.Number | CoreJsonType.String, Enumerable.Range(0, children.Length).ToArray()); return Join(CoreJsonType.String, error: true);
                case "date.add": case "date.diff":
                    Require(op, CoreJsonType.String, 0);
                    if (op == "date.add") { Require(op, CoreJsonType.Null | CoreJsonType.Boolean | CoreJsonType.Number | CoreJsonType.String, 1); Require(op, CoreJsonType.String, 2); }
                    else Require(op, CoreJsonType.String, 1);
                    return Join(op == "date.diff" ? CoreJsonType.Number : CoreJsonType.String, error: true);
                case "date.today": return new(CoreJsonType.String);
                case "agg": return Join(CoreJsonType.AnyJson, error: true, pending: true);
                default: return Join(CoreJsonType.AnyJson, error: true, pending: true);
            }
        }
        return Visit(node);
    }

    /// <summary>
    /// Maps an input's declared type name, case-insensitively, to its JSON types; null means <c>any</c>, and money, date,
    /// text and coding map to their wire types. An unknown name throws the exception <paramref name="refusal"/> builds.
    /// </summary>
    public static CoreJsonType ParseDeclaredType(string? type, string ruleId, Func<string, RuleCompilationException> refusal)
        => (type ?? "any").ToLowerInvariant() switch
        {
            "any" => CoreJsonType.AnyJson, "null" => CoreJsonType.Null, "boolean" => CoreJsonType.Boolean,
            "number" => CoreJsonType.Number, "string" or "text" or "money" or "date" => CoreJsonType.String,
            "array" => CoreJsonType.Array, "object" or "coding" => CoreJsonType.Object,
            _ => throw refusal($"input declares unknown type '{type}'"),
        };

    private static string VarPath(JsonNode? value) => value switch
    {
        JsonValue v when v.TryGetValue<string>(out var path) => path,
        JsonArray a when a.Count > 0 && a[0] is JsonValue v && v.TryGetValue<string>(out var path) => path,
        _ => "",
    };
}

using System.Numerics;
using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Context;
using Harborline.Foundation.RuleEngine.Model;

namespace Harborline.Foundation.RuleEngine.Compilation;

/// <summary>
/// Compiler-owned finite transfer proof for the closed evaluator.  It deliberately
/// shares <see cref="CoreTypeDerivation"/>'s executable/literal boundary; it is not
/// an evaluator, AST-count alias, or runtime fuel counter.  The graph combines these
/// transfers with its checked static DAG and bounded dynamic-demand scheduler.
/// </summary>
internal static class CoreWorkDerivation
{
    private static readonly BigInteger InputBytes = RuntimeInputEnvelope.MaxUtf8Bytes;
    private static readonly BigInteger InputNodes = RuntimeInputEnvelope.MaxNodes;
    private static readonly BigInteger MoneyDigits = 4_096;
    private static readonly BigInteger MoneyScale = 4_096;
    private static readonly BigInteger NumberBytes = 32;
    // Two 4096-digit parsed operands may be aligned by another 4096 zeroes, and
    // addition/subtraction may carry once.  Sign, point and JSON quotes complete
    // the serialized result transfer.
    private static readonly BigInteger MoneyAddResultBytes = MoneyDigits + MoneyScale + 1 + 4;
    private static readonly BigInteger MoneyMulResultBytes = MoneyDigits + 4;

    internal sealed record NodeProof(BigInteger Result, BigInteger Work, BigInteger Reads, BigInteger AggregateReads);

    internal static NodeProof Derive(JsonNode? node, string ruleId, BigInteger? dependencyResult = null,
        Func<string, BigInteger?>? staticReference = null, BigInteger? aggregateResult = null)
    {
        // Do not grow a second semantic walker: the established shared type walker
        // defines precisely which descendants execute and which are inert JSON data.
        _ = CoreTypeDerivation.Derive(node, ruleId);
        return Visit(node, dependencyResult ?? InputBytes, aggregateResult ?? InputBytes, staticReference);
    }

    internal static WorkProof DeriveGraph(IReadOnlyList<CompiledRule> rules, RuleEngineLimits limits)
    {
        // A table admitting no rows still folds to one value (an empty sum is 0): charge at least one fold result.
        var aggregateResult = Math.Max(1, limits.MaxTableRowsPerAggregate) * MoneyAddResultBytes;
        BigInteger dynamicResult = InputBytes;
        NodeProof[] proofs = [];
        var staticResults = new Dictionary<string, BigInteger>(StringComparer.Ordinal);
        // Static dependencies are already a checked DAG. Reach a fixed point of this
        // admitted program instead of iterating a separately configurable host depth.
        for (int pass = 0; pass <= rules.Count; pass++)
        {
            proofs = rules.Select(rule => Derive(rule.Ast, rule.Source.Id, InputBytes,
                path => staticResults.TryGetValue(path, out var result) ? result : null, aggregateResult)).ToArray();
            var next = new Dictionary<string, BigInteger>(staticResults, StringComparer.Ordinal);
            for (int index = 0; index < rules.Count; index++)
            {
                var rule = rules[index];
                if (rule.Source.Action != RuleActionKind.Compute) continue;
                if (rule.Source.Scope == RuleScope.Field) next["field." + rule.Source.ScopeTarget] = proofs[index].Result;
                if (rule.Source.Scope == RuleScope.Row)
                {
                    int slash = rule.Source.ScopeTarget.IndexOf('/');
                    if (slash >= 0)
                    {
                        var key = "row." + rule.Source.ScopeTarget[(slash + 1)..];
                        next[key] = next.TryGetValue(key, out var old) ? BigInteger.Max(old, proofs[index].Result) : proofs[index].Result;
                    }
                }
                if (rule.Source.Scope == RuleScope.Table && rule.StaticTarget is { } tableTarget)
                {
                    var key = tableTarget.Key;
                    next[key] = next.TryGetValue(key, out var old) ? BigInteger.Max(old, proofs[index].Result) : proofs[index].Result;
                }
            }
            dynamicResult = Max(BigInteger.Max(InputBytes, aggregateResult), proofs.Select(proof => proof.Result));
            bool unchanged = next.Count == staticResults.Count && next.All(pair => staticResults.TryGetValue(pair.Key, out var old) && old == pair.Value);
            staticResults = next;
            if (unchanged) break;
        }

        BigInteger potentialCells = 0;
        foreach (var rule in rules)
        {
            if (rule.Source.Action == RuleActionKind.Compute)
                potentialCells += rule.Source.Scope == RuleScope.Row ? Math.Max(0, limits.MaxGraphNodes) : 1;
            potentialCells += rule.References.Count(reference => reference is AggRef);
        }
        int demandCellBound = (int)BigInteger.Min(Math.Max(0, limits.MaxGraphNodes), potentialCells);

        // Result-carrying var chains are statically checked DAGs. Dynamic missing
        // reads only test presence and return key names, so they cannot copy a
        // demanded cell's value into this result. The inventory still bounds demand work.

        BigInteger localWork = 0, resolverReads = 0, aggregateReads = 0, maxCellWork = 1;
        for (int index = 0; index < rules.Count; index++)
        {
            var rule = rules[index];
            var proof = proofs[index];
            var rowExpansion = rule.Source.Scope == RuleScope.Row
                ? new BigInteger(Math.Max(0, limits.MaxTableRowsPerAggregate)) : BigInteger.One;
            // All rules evaluate into an outcome; a Compute also evaluates its value cell.
            var executions = rowExpansion * (rule.Source.Action == RuleActionKind.Compute ? 2 : 1);
            // Outcome/value projection owns copies after evaluator execution.
            localWork += executions * (proof.Work + proof.Result);
            resolverReads += executions * proof.Reads;
            aggregateReads += executions * proof.AggregateReads;
            maxCellWork = BigInteger.Max(maxCellWork, proof.Work);
        }

        if (rules.Any(rule => rule.References.OfType<DynamicReadRef>().Any()))
        {
            // A dynamically selected value can be converted, serialized and copied by
            // every executable operand position; use the same finite child factor as
            // result composition for one demanded cell's work transfer.
            var childFactor = 6 * new BigInteger(Math.Max(limits.MaxAstNodes, RuntimeInputEnvelope.MaxNodes));
            maxCellWork = BigInteger.Max(maxCellWork, childFactor * (dynamicResult + aggregateResult + InputBytes));
        }

        // Dynamic reads are actual scheduling work: a lookup and (at most) the accepted
        // active-chain demand.  Completed cells remain memoized only for this generation.
        var dynamicDemand = resolverReads * (BigInteger.One + demandCellBound * maxCellWork);
        // Each aggregate fold visits only the validated row envelope / configured row cap;
        // conversion and copying of a captured value are bounded by that input envelope.
        var foldWork = aggregateReads * Math.Max(0, limits.MaxTableRowsPerAggregate)
            * (BigInteger.Max(BigInteger.Max(dynamicResult, aggregateResult), InputBytes) + 1);
        return new WorkProof(dynamicResult, localWork + dynamicDemand + foldWork);
    }

    private static NodeProof Visit(JsonNode? node, BigInteger dependencyResult, BigInteger aggregateResult,
        Func<string, BigInteger?>? staticReference)
    {
        if (node is not JsonObject expression || expression.Count != 1)
        {
            var bytes = LiteralBytes(node);
            return new(bytes, 1 + bytes, 0, 0);
        }

        var (op, raw) = expression.First();
        var args = raw is JsonArray array ? array.ToList() : new List<JsonNode?> { raw };
        var children = args.Select(arg => Visit(arg, dependencyResult, aggregateResult, staticReference)).ToArray();
        var childWork = children.Aggregate(BigInteger.Zero, (total, child) => total + child.Work);
        var childReads = children.Aggregate(BigInteger.Zero, (total, child) => total + child.Reads);
        var aggregateReads = children.Aggregate(BigInteger.Zero, (total, child) => total + child.AggregateReads);
        var childBytes = children.Aggregate(BigInteger.Zero, (total, child) => total + child.Result);
        var childResult = Max(BigInteger.Zero, children.Select(child => child.Result));
        NodeProof Base(BigInteger result, BigInteger transfer, BigInteger? reads = null, BigInteger? aggs = null)
            => new(result, 1 + childWork + transfer, reads ?? childReads, aggs ?? aggregateReads);

        return op switch
        {
            // Both interpreters eagerly evaluate var's fallback; every resolver call has work.
            "var" => Var(raw, childResult, childWork, childBytes, childReads, aggregateReads, dependencyResult, staticReference),
            "missing" => Missing(args, children, childWork, childReads, aggregateReads, childResult),
            "missing_some" => MissingSome(children, childWork, childReads, aggregateReads, childBytes),
            // Object/array equality serializes complete operands in both tiers.
            "==" or "!=" or "===" or "!==" => Base(5, childBytes),
            "!" or "!!" or ">" or ">=" or "<" or "<=" => Base(5, childBytes),
            // Short circuit selects a subset at runtime; all executable children give the upper transfer.
            "and" or "or" or "if" => Base(BigInteger.Max(5, childResult), 0),
            "+" or "-" or "*" or "/" or "%" or "min" or "max" => Base(NumberBytes, childBytes),
            "in" => Base(5, InputNodes * (childBytes + 1)),
            "cat" => Cat(args.Count, children, childWork, childReads, aggregateReads),
            "agg" => Base(AggregateResult(raw, aggregateResult, staticReference), childBytes + 1, childReads + 1, aggregateReads + 1),
            // Parsing scans complete input before refusal; accepted decimal digit/scale and
            // alignment/multiplication retain the existing 4096 bound.
            "money.add" or "money.sub" => Base(MoneyDigits + MoneyScale + args.Count + 4,
                childBytes + args.Count * MoneyDigits * MoneyDigits + args.Count * (MoneyDigits + MoneyScale + args.Count + 4)),
            "money.mul" => Base(MoneyMulResultBytes,
                childBytes + args.Count * MoneyDigits * MoneyDigits + args.Count * MoneyMulResultBytes),
            "date.add" => Base(12, childBytes),
            "date.diff" => Base(NumberBytes, childBytes),
            "date.today" => Base(12, 0),
            "coding.is" => Base(5, InputNodes * (childBytes + 1)),
            // ValidateOperators closes this set first.  A new evaluator arm cannot silently
            // receive a generic bound: its transfer is a required admission decision.
            _ => throw new InvalidOperationException($"work proof has no transfer for '{op}'"),
        };
    }

    private static NodeProof Var(JsonNode? raw, BigInteger childResult, BigInteger childWork, BigInteger childBytes, BigInteger childReads,
        BigInteger aggregateReads, BigInteger dependencyResult, Func<string, BigInteger?>? staticReference)
    {
        string? path = raw switch
        {
            JsonValue value when value.TryGetValue<string>(out var text) => text,
            JsonArray array when array.Count > 0 && array[0] is JsonValue value && value.TryGetValue<string>(out var text) => text,
            _ => null,
        };
        var resolved = path is null ? dependencyResult : staticReference?.Invoke(path) ?? InputBytes;
        return new(BigInteger.Max(resolved, childResult), 1 + childWork + childBytes + 1, childReads + 1, aggregateReads);
    }

    private static BigInteger AggregateResult(JsonNode? raw, BigInteger foldResult, Func<string, BigInteger?>? staticReference)
    {
        if (raw is not JsonArray { Count: 3 } parts || parts.Any(part => part is not JsonValue value || !value.TryGetValue<string>(out _)))
            return foldResult;
        var key = CellAddress.TableAggregate(parts[1]!.GetValue<string>(), parts[0]!.GetValue<string>(), parts[2]!.GetValue<string>()).Key;
        return BigInteger.Max(foldResult, staticReference?.Invoke(key) ?? BigInteger.Zero);
    }

    private static NodeProof Missing(IReadOnlyList<JsonNode?> args, IReadOnlyList<NodeProof> children,
        BigInteger childWork, BigInteger childReads, BigInteger aggregateReads, BigInteger childResult)
    {
        var keyCount = args.Count == 1 ? InputNodes : new BigInteger(args.Count);
        var keyBytes = BigInteger.Max(childResult, BigInteger.One);
        var firstTwice = args.Count == 1 && children.Count > 0 ? children[0].Work : BigInteger.Zero;
        var repeatedAggregateReads = args.Count == 1 && children.Count > 0 ? children[0].AggregateReads : BigInteger.Zero;
        return new(2 + keyCount * (keyBytes + 1), 1 + childWork + firstTwice + keyCount * (keyBytes + 1),
            childReads + (args.Count == 1 && children.Count > 0 ? children[0].Reads : BigInteger.Zero) + keyCount,
            aggregateReads + repeatedAggregateReads);
    }

    private static NodeProof MissingSome(IReadOnlyList<NodeProof> children, BigInteger childWork,
        BigInteger childReads, BigInteger aggregateReads, BigInteger childBytes)
    {
        var keyBytes = BigInteger.Max(children.Count > 1 ? children[1].Result : BigInteger.Zero, BigInteger.One);
        return new(2 + InputNodes * (keyBytes + 1), 1 + childWork + childBytes + InputNodes * (keyBytes + 1),
            childReads + InputNodes, aggregateReads);
    }

    private static NodeProof Cat(int count, IReadOnlyList<NodeProof> children, BigInteger childWork,
        BigInteger childReads, BigInteger aggregateReads)
    {
        // An empty cat still returns the empty JSON string, whose serialized form is two quote bytes.
        var output = count == 0 ? 2 : children.Aggregate(BigInteger.Zero, (total, child) => total + 2 + 6 * child.Result);
        // Count × final length conservatively covers copying of all growing prefixes.
        return new(output, 1 + childWork + count * output, childReads, aggregateReads);
    }

    private static BigInteger LiteralBytes(JsonNode? node) => node switch
    {
        null => 4,
        JsonArray array => 2 + array.Aggregate(BigInteger.Zero, (total, child) => total + LiteralBytes(child)) + Math.Max(0, array.Count - 1),
        JsonObject obj when obj.Count != 1 => 2 + obj.Aggregate(BigInteger.Zero,
            (total, pair) => total + 2 + 6 * pair.Key.Length + 1 + LiteralBytes(pair.Value)) + Math.Max(0, obj.Count - 1),
        JsonObject obj => 2 + obj.Aggregate(BigInteger.Zero,
            (total, pair) => total + 2 + 6 * pair.Key.Length + 1 + LiteralBytes(pair.Value)),
        JsonValue value when value.TryGetValue<string>(out var text) => 2 + 6 * text.Length,
        JsonValue value when value.TryGetValue<bool>(out var boolean) => boolean ? 4 : 5,
        _ => NumberBytes,
    };

    private static BigInteger Max(BigInteger initial, IEnumerable<BigInteger> values)
        => values.Aggregate(initial, BigInteger.Max);

}

/// <summary>Non-persisted compiler proof; it never appears in canonical authored definitions.</summary>
public sealed record WorkProof(BigInteger MaximumResultBytes, BigInteger MaximumEvaluationWork);

namespace Harborline.Foundation.RuleEngine.Compilation;

/// <summary>
/// Thrown when a definition is rejected at publish (SPINE-1 design §2.3, §4) —
/// a cycle, an exceeded static bound, an unparseable expression, or an
/// unsupported tier. Fail-closed: a rejected definition never reaches an instance.
/// </summary>
public sealed class RuleCompilationException : Exception
{
    /// <summary>Stable diagnostic code (<see cref="RuleEngineCodes"/> <c>rule.compile.*</c>).</summary>
    public string Code { get; }

    /// <summary>The offending rule id, when attributable to a single rule.</summary>
    public string? RuleId { get; }

    /// <summary>For a cycle rejection, the cycle path (cell keys + the rules forming it).</summary>
    public IReadOnlyList<string>? CyclePath { get; }

    /// <summary>Stable string params (for <c>rule.compile.work_exceeded</c>: <c>proof</c> and <c>ceiling</c>); empty otherwise.</summary>
    public IReadOnlyDictionary<string, string> Params { get; } = new Dictionary<string, string>();

    /// <summary>A refusal with a stable <paramref name="code"/>, optionally attributed to one rule and, for a cycle, carrying its path.</summary>
    public RuleCompilationException(string code, string message, string? ruleId = null, IReadOnlyList<string>? cyclePath = null)
        : base(message)
    {
        Code = code;
        RuleId = ruleId;
        CyclePath = cyclePath;
    }

    /// <summary>A graph-level refusal (no single rule) carrying stable string params.</summary>
    public RuleCompilationException(string code, string message, IReadOnlyDictionary<string, string> @params)
        : this(code, message)
        => Params = new Dictionary<string, string>(@params);
}

using System.Globalization;
using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Functions;
using Harborline.Foundation.RuleEngine.Model;
using Harborline.Kernel.SchemaValidation;


namespace Harborline.Foundation.RuleEngine.Compilation;

/// <summary>The immutable compiled form of a definition's Tier-2 rules (SPINE-1 design §2.2 step 1).</summary>
public sealed class CompiledGraph
{
    internal CompiledGraph(IReadOnlyList<CompiledRule> rules, WorkProof workProof)
    {
        Rules = rules;
        WorkProof = workProof;
    }

    internal IReadOnlyList<CompiledRule> Rules { get; }

    /// <summary>Compiler-owned finite transfer proof; never serialized into an authored definition.</summary>
    public WorkProof WorkProof { get; }

    /// <summary>The number of Tier-2 rules compiled (Tier-1 rules are handled by the kernel JSON-Schema validator).</summary>
    public int RuleCount => Rules.Count;

    /// <summary>
    /// Each compiled rule's lowered AST in compile order, with references rewritten as the grammar
    /// defines them (e.g. <c>parent.z</c> to <c>field.z</c>). Returned as copies, so a caller cannot
    /// alter a compiled rule. The TypeScript engine exposes the same through <c>rules[].ast</c>.
    /// </summary>
    public IReadOnlyList<JsonNode?> LoweredAsts => [.. Rules.Select(rule => rule.Ast?.DeepClone())];
}

/// <summary>
/// Lowers + validates a definition's rules at publish-time (SPINE-1 design §2.2,
/// §2.3, §4): grammar-lowering, reference extraction, the static resource bounds,
/// and fail-closed cycle detection with a path diagnostic. A rejected definition
/// throws <see cref="RuleCompilationException"/> and never reaches an instance.
/// </summary>
public static class RuleCompiler
{
    /// <summary>Compiles a definition's rules; throws <see cref="RuleCompilationException"/> on rejection.</summary>
    public static CompiledGraph Compile(IReadOnlyList<RuleDefinition> rules, RuleEngineLimits? limits = null)
    {
        ArgumentNullException.ThrowIfNull(rules);
        var lim = limits ?? RuleEngineLimits.Default;
        var compiled = new List<CompiledRule>();

        foreach (var rule in rules)
        {
            if (rule.Tier == RuleTier.JsonSchema)
            {
                ValidateJsonSchema(rule);
                continue;
            }
            if (rule.Tier != RuleTier.JsonLogic)
            {
                throw new RuleCompilationException(
                    RuleEngineCodes.CompileUnsupportedTier,
                    $"rule '{rule.Id}': tier '{rule.Tier}' is unsupported by the v1 evaluator.",
                    rule.Id);
            }

            if (!Enum.IsDefined(rule.Action))
                throw new RuleCompilationException(RuleEngineCodes.CompileUnknownAction,
                    $"rule '{rule.Id}': unknown action '{rule.Action}'.", rule.Id);

            var (ctx, staticTarget, rowSection, rowField) = ResolveScope(rule);
            var ast = ScopeGrammar.Lower(rule.Expression, ctx, rule.Id);

            int nodes = ScopeGrammar.Measure(ast, lim, rule.Id);
            if (nodes > lim.MaxAstNodes)
            {
                throw new RuleCompilationException(
                    RuleEngineCodes.CompileAstTooLarge,
                    $"rule '{rule.Id}': AST node count {nodes} exceeds the bound {lim.MaxAstNodes}",
                    rule.Id);
            }

            ValidateOperators(ast, rule.Id);
            var refs = ScopeGrammar.ExtractRefs(ast, rule.Id);
            if (refs.Count > lim.MaxReferencesPerRule)
            {
                throw new RuleCompilationException(
                    RuleEngineCodes.CompileTooManyRefs,
                    $"rule '{rule.Id}': reference count {refs.Count} exceeds the bound {lim.MaxReferencesPerRule}",
                    rule.Id);
            }

            compiled.Add(new CompiledRule
            {
                Source = rule,
                Ast = ast,
                OutputType = ScopeGrammar.OutputTypeFor(rule.Action),
                References = refs,
                StaticTarget = staticTarget,
                RowSection = rowSection,
                RowField = rowField,
            });
        }

        // A value rule can feed another rule.  First derive producer result sets, then
        // iterate the finite six-tag domain into consumers instead of treating every var
        // as AnyJson.  Cycles are rejected below; the bounded loop is defensive.
        ValidateCoreTypes(compiled);
        DetectCyclesAndDepth(compiled, lim);
        // Admission proof after closed-operator and static-DAG validation.  It is
        // deliberately distinct from the runtime step/wall-clock backstops.
        var workProof = CoreWorkDerivation.DeriveGraph(compiled, lim);
        var workRefusal = StaticWorkRefusal(workProof, lim);
        if (workRefusal is not null) throw workRefusal;
        return new CompiledGraph(compiled, workProof);
    }

    /// <summary>
    /// T-818: the static work ceiling shared by compile and graph construction. Null when the proof fits;
    /// a proof equal to the ceiling is admitted. The refusal is graph-level (no rule id).
    /// </summary>
    internal static RuleCompilationException? StaticWorkRefusal(WorkProof proof, RuleEngineLimits limits)
    {
        var work = proof.MaximumEvaluationWork;
        var ceiling = limits.MaxStaticWork;
        if (work <= ceiling) return null;
        var invariant = CultureInfo.InvariantCulture;
        var factor = ceiling > 0 ? $" (more than {(work / ceiling).ToString(invariant)}x)" : "";
        return new RuleCompilationException(RuleEngineCodes.CompileWorkExceeded,
            $"graph work proof {work.ToString(invariant)} exceeds the static work ceiling {ceiling.ToString(invariant)}{factor}; "
            + "lower maxTableRowsPerAggregate or maxGraphNodes, or author fewer dynamic Row or missing reads and fewer aggregate references",
            new Dictionary<string, string> { ["proof"] = work.ToString(invariant), ["ceiling"] = ceiling.ToString(invariant) });
    }

    private static void ValidateJsonSchema(RuleDefinition rule)
    {
        try
        {
            new InMemorySchemaRegistry().RegisterAsync(rule.Expression).AsTask().GetAwaiter().GetResult();
        }
        catch (InvalidSchemaException exception)
        {
            throw new RuleCompilationException(
                RuleEngineCodes.CompileInvalidJsonSchema,
                $"rule '{rule.Id}': JSON Schema is malformed or invalid for draft 2020-12: {exception.Message}",
                rule.Id);
        }
    }

    private static void ValidateCoreTypes(IReadOnlyList<CompiledRule> rules)
    {
        var fields = new Dictionary<string, CoreJsonType>(StringComparer.Ordinal);
        foreach (var rule in rules.Where(rule => rule.Source.Action == RuleActionKind.Compute
            && rule.Source.Scope == RuleScope.Field))
            fields[rule.Source.ScopeTarget] = CoreTypeDerivation.Derive(rule.Ast, rule.Source.Id).Types;

        for (var pass = 0; pass <= rules.Count; pass++)
        {
            var next = new Dictionary<string, CoreJsonType>(fields, StringComparer.Ordinal);
            foreach (var rule in rules)
            {
                var result = CoreTypeDerivation.Derive(rule.Ast, rule.Source.Id,
                    path => path.StartsWith("field.", StringComparison.Ordinal)
                        && fields.TryGetValue(path["field.".Length..], out var known)
                        ? known : CoreJsonType.AnyJson);
                if (rule.Source.Action == RuleActionKind.Compute && rule.Source.Scope == RuleScope.Field)
                    next[rule.Source.ScopeTarget] = result.Types;
            }
            if (next.Count == fields.Count && next.All(pair => fields.TryGetValue(pair.Key, out var old) && old == pair.Value)) return;
            fields = next;
        }
    }

    private static void ValidateOperators(JsonNode? node, string ruleId)
    {
        // The evaluator executes only single-property objects. Arrays and multi-property
        // objects are literal data; their contents do not become executable declarations.
        if (node is not JsonObject expression || expression.Count != 1) return;
        var operation = expression.First();
        if (!BuiltInFunctionRegister.TryResolve(operation.Key, out var function))
            throw new RuleCompilationException(RuleEngineCodes.CompileInvalidExpression,
                $"rule '{ruleId}': unsupported operator '{operation.Key}'.", ruleId);

        var arguments = operation.Value is JsonArray array
            ? array.ToList()
            : new List<JsonNode?> { operation.Value };
        if (!function.Admits(arguments.Count))
            throw new RuleCompilationException(operation.Key == "agg" ? RuleEngineCodes.CompileBadGrammar : RuleEngineCodes.CompileInvalidExpression,
                $"rule '{ruleId}': operator '{operation.Key}' does not accept {arguments.Count} argument(s).", ruleId);

        foreach (var argument in arguments)
            ValidateOperators(argument, ruleId);
    }

    private static (LowerContext Ctx, CellAddress? Target, string? RowSection, string? RowField) ResolveScope(RuleDefinition rule)
    {
        switch (rule.Scope)
        {
            case RuleScope.Field:
                return (new LowerContext(rule.Scope, rule.ScopeTarget, null), CellAddress.Field(rule.ScopeTarget), null, null);
            case RuleScope.Section:
                return (new LowerContext(rule.Scope, rule.ScopeTarget, null), CellAddress.Section(rule.ScopeTarget), null, null);
            case RuleScope.Schema:
                return (new LowerContext(rule.Scope, "", null), CellAddress.Schema(), null, null);
            case RuleScope.Row:
            {
                var parts = rule.ScopeTarget.Split('/');
                if (parts.Length != 2 || parts[0].Length == 0 || parts[1].Length == 0)
                    throw new RuleCompilationException(RuleEngineCodes.CompileBadGrammar,
                        $"rule '{rule.Id}': Row ScopeTarget '{rule.ScopeTarget}' must be 'section/field'", rule.Id);
                return (new LowerContext(rule.Scope, rule.ScopeTarget, parts[0]), null, parts[0], parts[1]);
            }
            case RuleScope.Table:
            {
                var parts = rule.ScopeTarget.Split('/');
                if (parts.Length != 3 || parts.Any(p => p.Length == 0))
                    throw new RuleCompilationException(RuleEngineCodes.CompileBadGrammar,
                        $"rule '{rule.Id}': Table ScopeTarget '{rule.ScopeTarget}' must be 'section/fn/col'", rule.Id);
                return (new LowerContext(rule.Scope, rule.ScopeTarget, parts[0]),
                    CellAddress.TableAggregate(parts[0], parts[1], parts[2]), null, null);
            }
            default:
                throw new RuleCompilationException(RuleEngineCodes.CompileBadGrammar,
                    $"rule '{rule.Id}': unknown scope", rule.Id);
        }
    }

    // ── abstract dependency graph (cycle + depth) ─────────────────────────────

    private static void DetectCyclesAndDepth(IReadOnlyList<CompiledRule> rules, RuleEngineLimits lim)
    {
        // dependsOn[node] = set of nodes the node depends on. Abstract node keys:
        //   F:<field>  R:<section>/<field>  A:<section>/<fn>/<col>  S:<id>  SCHEMA
        var dependsOn = new Dictionary<string, HashSet<string>>();
        var ruleOfTarget = new Dictionary<string, string>();

        void Edge(string node, string dep)
        {
            if (!dependsOn.TryGetValue(node, out var set)) dependsOn[node] = set = new HashSet<string>();
            set.Add(dep);
            dependsOn.TryAdd(dep, new HashSet<string>());
        }

        // Only VALUE-producing nodes form the dependency graph: Compute-rule targets +
        // aggregate cells. Sink rules (Validate / Visibility / Presentation) read values but
        // do not define their target's value, so they create no edges (a Validate reading its
        // own field is not a cycle). This mirrors the runtime value graph exactly.
        foreach (var r in rules)
        {
            bool isValueRule = r.Source.Action == RuleActionKind.Compute;
            string? target = isValueRule ? AbstractTarget(r) : null;
            if (target is not null)
            {
                ruleOfTarget[target] = r.Source.Id;
                dependsOn.TryAdd(target, new HashSet<string>());
            }

            foreach (var rf in r.References)
            {
                switch (rf)
                {
                    case FieldRef f when target is not null:
                        Edge(target, "F:" + f.Name);
                        break;
                    case RowFieldRef rfld when target is not null && r.RowSection is not null:
                        Edge(target, "R:" + r.RowSection + "/" + rfld.Field);
                        break;
                    case AggRef a:
                        // Aggregate cells are value nodes regardless of the referencing rule's kind.
                        string aggNode = "A:" + a.Section + "/" + a.Fn + "/" + a.Col;
                        dependsOn.TryAdd(aggNode, new HashSet<string>());
                        Edge(aggNode, "R:" + a.Section + "/" + a.Col);
                        if (target is not null) Edge(target, aggNode);
                        break;
                }
            }
        }

        // Cycle detection (DFS coloring) with path reconstruction.
        var color = new Dictionary<string, int>(); // 0 white, 1 gray, 2 black
        var stack = new List<string>();

        foreach (var node in dependsOn.Keys)
        {
            if (color.GetValueOrDefault(node) == 0)
            {
                var cycle = Dfs(node, dependsOn, color, stack, 0, lim.MaxDependencyDepth);
                if (cycle is not null)
                {
                    var pathKeys = cycle.Select(k => ruleOfTarget.TryGetValue(k, out var rid) ? $"{k} (rule {rid})" : k).ToList();
                    throw new RuleCompilationException(
                        RuleEngineCodes.CompileCycle,
                        "cyclic rule definition: " + string.Join(" -> ", cycle),
                        cyclePath: pathKeys);
                }
            }
        }

        // Longest-path depth (acyclic now): depth(node) = 1 + max depth(dep).
        var depthMemo = new Dictionary<string, int>();
        int Depth(string node, int descent)
        {
            if (descent > lim.MaxDependencyDepth)
                throw new RuleCompilationException(RuleEngineCodes.CompileDepthExceeded,
                    $"dependency depth exceeds the bound {lim.MaxDependencyDepth}");
            if (depthMemo.TryGetValue(node, out var d)) return d;
            depthMemo[node] = 0; // guard (graph is acyclic here)
            int best = 0;
            foreach (var dep in dependsOn[node]) best = Math.Max(best, 1 + Depth(dep, descent + 1));
            return depthMemo[node] = best;
        }

        foreach (var node in dependsOn.Keys)
        {
            if (Depth(node, 0) > lim.MaxDependencyDepth)
            {
                throw new RuleCompilationException(
                    RuleEngineCodes.CompileDepthExceeded,
                    $"dependency depth at '{node}' exceeds the bound {lim.MaxDependencyDepth}");
            }
        }
    }

    private static List<string>? Dfs(string node, Dictionary<string, HashSet<string>> dependsOn,
        Dictionary<string, int> color, List<string> stack, int descent, int maxDepth)
    {
        // Bound recursion depth (finding F9): a chain deeper than the depth cap is itself a depth
        // violation (the longest-path check also rejects it), so throw before the recursion can run
        // to full graph depth — defensive ahead of packet-carried (untrusted) definitions.
        if (descent > maxDepth)
            throw new RuleCompilationException(RuleEngineCodes.CompileDepthExceeded,
                $"dependency depth exceeds the bound {maxDepth}");
        color[node] = 1;
        stack.Add(node);
        foreach (var dep in dependsOn[node])
        {
            int c = color.GetValueOrDefault(dep);
            if (c == 1)
            {
                int idx = stack.IndexOf(dep);
                var cycle = stack.GetRange(idx, stack.Count - idx);
                cycle.Add(dep);
                return cycle;
            }
            if (c == 0)
            {
                var found = Dfs(dep, dependsOn, color, stack, descent + 1, maxDepth);
                if (found is not null) return found;
            }
        }
        color[node] = 2;
        stack.RemoveAt(stack.Count - 1);
        return null;
    }

    private static string AbstractTarget(CompiledRule r) => r.Source.Scope switch
    {
        RuleScope.Field => "F:" + r.Source.ScopeTarget,
        RuleScope.Section => "S:" + r.Source.ScopeTarget,
        RuleScope.Schema => "SCHEMA",
        RuleScope.Row => "R:" + r.RowSection + "/" + r.RowField,
        RuleScope.Table => "A:" + r.StaticTarget!.Value.SectionId + "/" + r.StaticTarget!.Value.Name,
        _ => "?",
    };
}

using System.Text.Json;
using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Model;


namespace Harborline.Foundation.RuleEngine.Compilation;

/// <summary>
/// The neutral compiler's grammar-lowering half (SPINE-1 design §1.2). Lowers the
/// structured scope-grammar (<c>self</c> / <c>field.x</c> / <c>row.y</c> /
/// <c>table.agg(col)</c> / <c>parent.f</c> / <c>section.id.f</c>) carried inside a
/// rule's opaque JsonLogic expression into a canonical normalized AST (record
/// <c>field.</c> / <c>row.</c> vars, declared context prefixes, and the <c>agg</c>
/// operator). Performed ONCE so
/// both tiers consume the identical normalized AST — the corpus pins
/// <c>expectedAst</c> so a lowering divergence is caught, not just an eval divergence.
/// </summary>
internal sealed record LowerContext(RuleScope Scope, string ScopeTarget, string? SectionId);

internal static class ScopeGrammar
{
    public static OutputType OutputTypeFor(RuleActionKind action) => action switch
    {
        RuleActionKind.Compute => OutputType.Value,
        RuleActionKind.Validate => OutputType.Validity,
        RuleActionKind.Presentation => OutputType.Presentation,
        RuleActionKind.Options => OutputType.Options,
        _ => OutputType.Visibility, // Visibility | Required | ReadOnly
    };

    /// <summary>Parses + lowers the opaque expression text into a canonical AST.</summary>
    public static JsonNode? Lower(string expression, LowerContext ctx, string ruleId)
    {
        JsonNode? parsed;
        try
        {
            parsed = JsonNode.Parse(expression);
        }
        catch (JsonException ex)
        {
            throw new RuleCompilationException(
                RuleEngineCodes.CompileInvalidExpression,
                $"rule '{ruleId}': expression is not valid JSON: {ex.Message}",
                ruleId);
        }

        return Rewrite(parsed, ctx, ruleId);
    }

    private static JsonNode? Rewrite(JsonNode? node, LowerContext ctx, string ruleId)
    {
        switch (node)
        {
            case JsonObject obj when obj.Count == 1 && obj.ContainsKey("var"):
            {
                var pathNode = obj["var"];
                // {"var":[path, default]} or {"var":"path"}
                var arr = pathNode as JsonArray;
                JsonNode? def = arr is { Count: > 1 } ? arr[1]?.DeepClone() : null;
                // rules-ck-7 addresses named cells with static strings lowered here, once. A
                // numeric (array-index), computed, null or empty operand has no canonical cell;
                // it used to throw an untyped InvalidOperationException (the TS tier read field '').
                if ((arr is null ? pathNode : arr.Count > 0 ? arr[0] : null) is not JsonValue pathValue
                    || !pathValue.TryGetValue<string>(out var path) || path.Length == 0)
                {
                    throw Bad(ruleId, "a var path must be a non-empty string from the scope-addressing grammar");
                }

                // A table.fn(col) var lowers to the agg operator.
                if (path.StartsWith("table.", StringComparison.Ordinal) && path.Contains('('))
                {
                    return LowerAgg(path, ctx, ruleId);
                }

                string canonical = LowerVarPath(path, ctx, ruleId);
                if (def is not null)
                {
                    return new JsonObject { ["var"] = new JsonArray(JsonValue.Create(canonical), Rewrite(def, ctx, ruleId)) };
                }
                return new JsonObject { ["var"] = JsonValue.Create(canonical) };
            }
            case JsonObject obj:
            {
                // The evaluator executes exactly one-key objects. A multi-key object (and
                // every array reached as literal data) is opaque JSON, not a nested program.
                if (obj.Count != 1) return obj.DeepClone();
                var result = new JsonObject();
                foreach (var (k, v) in obj)
                    result[k] = v is JsonArray arguments
                        ? new JsonArray(arguments.Select(item => Rewrite(item, ctx, ruleId)).ToArray())
                        : Rewrite(v, ctx, ruleId);
                return result;
            }
            case JsonArray: return node.DeepClone();
            default:
                return node?.DeepClone();
        }
    }

    private static JsonNode LowerAgg(string path, LowerContext ctx, string ruleId)
    {
        // table.<fn>(<col>)  or  table.<fn>(<section>.<col>)
        int open = path.IndexOf('(');
        int close = path.IndexOf(')');
        if (close <= open)
        {
            throw Bad(ruleId, $"malformed table aggregate '{path}'");
        }
        string fn = path[6..open];
        string arg = path[(open + 1)..close];
        string section, col;
        int dot = arg.IndexOf('.');
        if (dot >= 0)
        {
            section = arg[..dot];
            col = arg[(dot + 1)..];
        }
        else
        {
            section = ctx.SectionId
                ?? throw Bad(ruleId, $"table aggregate '{path}' needs an explicit section (table.{fn}(section.{arg})) outside a row/table-scoped rule");
            col = arg;
        }
        if (fn.Length == 0 || section.Length == 0 || col.Length == 0)
        {
            throw Bad(ruleId, $"malformed table aggregate '{path}'");
        }
        return new JsonObject
        {
            ["agg"] = new JsonArray(JsonValue.Create(fn), JsonValue.Create(section), JsonValue.Create(col)),
        };
    }

    /// <summary>
    /// Scope roots a borrower may declare (Forms <c>forms-ck-13</c>, Documents <c>documents-ck-25</c>) that no
    /// R1 evaluator supplies. Lowering them as bare field names let a rule read a client-supplied candidate
    /// property in place of the authenticated principal, the evaluation instant or the record type, so the
    /// compiler refuses them (fail closed) until an evaluator binds them. A record field of the same name
    /// stays addressable as <c>field.&lt;name&gt;</c>.
    /// </summary>
    private static readonly HashSet<string> UnsuppliedRoots = new(StringComparer.Ordinal) { "caller", "clock", "record_type" };

    private static void RefuseUnsuppliedRoot(string path, string ruleId)
    {
        int dot = path.IndexOf('.');
        if (UnsuppliedRoots.Contains(dot < 0 ? path : path[..dot]))
            throw Bad(ruleId, $"'{path}' addresses a scope root no evaluator supplies; use field.{path} for a record field");
    }

    private static string LowerVarPath(string path, LowerContext ctx, string ruleId)
    {
        RefuseUnsuppliedRoot(path, ruleId);
        if (path == "self")
        {
            return ctx.Scope switch
            {
                RuleScope.Row => "row." + RowFieldOf(ctx, ruleId),
                RuleScope.Field => "field." + ctx.ScopeTarget,
                _ => throw Bad(ruleId, "'self' is only valid in a Field- or Row-scoped rule"),
            };
        }
        if (path.StartsWith("row.", StringComparison.Ordinal))
        {
            if (ctx.Scope != RuleScope.Row)
            {
                throw Bad(ruleId, $"'row.' reference '{path}' is only valid in a Row-scoped rule");
            }
            return path;
        }
        if (path.StartsWith("parent.", StringComparison.Ordinal))
        {
            // parent.<f> reaches the top-level instance — addresses the same cell as field.<f>.
            return "field." + path["parent.".Length..];
        }
        if (path.StartsWith("field.", StringComparison.Ordinal))
        {
            return path;
        }
        if (path.StartsWith("section.", StringComparison.Ordinal))
        {
            // section.<id>.<field> disambiguates authoring; resolves to the top-level field.
            var rest = path["section.".Length..];
            int lastDot = rest.IndexOf('.');
            if (lastDot < 0) throw Bad(ruleId, $"malformed section reference '{path}' (expected section.<id>.<field>)");
            return "field." + rest[(lastDot + 1)..];
        }
        // Declared context prefixes are preserved so borrower admission can distinguish them from
        // record fields. A workflow guard reads wf./timer. from its process bag, while Forms may
        // declare candidate. separately from field.; none of these is a field dependency.
        if (path.StartsWith("wf.", StringComparison.Ordinal)
            || path.StartsWith("timer.", StringComparison.Ordinal)
            || path.StartsWith("candidate.", StringComparison.Ordinal))
        {
            return path;
        }
        // bare name => top-level field (flat-form back-compat)
        return "field." + path;
    }

    private static string RowFieldOf(LowerContext ctx, string ruleId)
    {
        int slash = ctx.ScopeTarget.IndexOf('/');
        if (slash < 0) throw Bad(ruleId, $"Row rule ScopeTarget '{ctx.ScopeTarget}' must be 'section/field'");
        return ctx.ScopeTarget[(slash + 1)..];
    }

    private static RuleCompilationException Bad(string ruleId, string message)
        => new(RuleEngineCodes.CompileBadGrammar, $"rule '{ruleId}': {message}", ruleId);

    // ── reference extraction ──────────────────────────────────────────────────

    public static IReadOnlyList<RuleRef> ExtractRefs(JsonNode? ast, string ruleId = "")
    {
        var refs = new List<RuleRef>();
        Walk(ast, refs, ruleId);
        return refs;
    }

    private static void Walk(JsonNode? node, List<RuleRef> refs, string ruleId)
    {
        switch (node)
        {
            case JsonObject obj when obj.Count == 1 && (obj.ContainsKey("missing") || obj.ContainsKey("missing_some")):
            {
                var raw = obj.First().Value;
                var args = raw is JsonArray array ? array.ToList() : new List<JsonNode?> { raw };
                if (obj.ContainsKey("missing_some"))
                {
                    if (args.Count > 0) Walk(args[0], refs, ruleId); // numeric threshold is executable
                    if (args.Count > 1) CollectMissingKeys(args[1], refs, ruleId);
                }
                else foreach (var arg in args) CollectMissingKeys(arg, refs, ruleId);
                break;
            }
            case JsonObject obj when obj.Count == 1 && obj.ContainsKey("var"):
            {
                string path = VarPathOf(obj["var"]);
                if (path.StartsWith("field.", StringComparison.Ordinal))
                    refs.Add(new FieldRef(path["field.".Length..]));
                else if (path.StartsWith("row.", StringComparison.Ordinal))
                    refs.Add(new RowFieldRef(path["row.".Length..]));
                // var with a default array: also walk the default for nested vars
                if (obj["var"] is JsonArray a && a.Count > 1) Walk(a[1], refs, ruleId);
                break;
            }
            case JsonObject obj when obj.Count == 1 && obj.ContainsKey("agg"):
            {
                // Ticket 162 review (150-family direction): an agg node the graph cannot
                // statically register — wrong arity, or expression-valued/non-string args — used
                // to be SKIPPED (or to throw an untyped InvalidOperationException on a non-string
                // arg), leaving no fold cell and a per-keystroke runtime refusal with no
                // authoring-time signal. The compiler refuses it instead, identically to the TS tier.
                if (obj["agg"] is not JsonArray a || a.Count != 3 || a.Any(part => part is not JsonValue v || !v.TryGetValue<string>(out _)))
                {
                    throw Bad(ruleId, "a table aggregate must be a static [fn, section, col] string triple");
                }
                // rules-eng-16: a fold is one of the register's bounded folds over a named child
                // collection; anything else (a search, a query, a catalogue measure) is not a fold.
                if (!Functions.BuiltInFunctionRegister.AggregateFolds.Contains(a[0]!.GetValue<string>()))
                {
                    throw Bad(ruleId, $"'{a[0]!.GetValue<string>()}' is not a registered bounded fold");
                }
                refs.Add(new AggRef(
                    a[1]!.GetValue<string>(),
                    a[0]!.GetValue<string>(),
                    a[2]!.GetValue<string>()));
                break;
            }
            case JsonObject obj when obj.Count == 1:
            {
                var argument = obj.First().Value;
                if (argument is JsonArray arguments) foreach (var item in arguments) Walk(item, refs, ruleId);
                else Walk(argument, refs, ruleId);
                break;
            }
        }
    }

    private static string VarPathOf(JsonNode? varNode)
        => varNode is JsonArray a
            ? (a.Count > 0 ? a[0]?.GetValue<string>() ?? "" : "")
            : varNode?.GetValue<string>() ?? "";

    private static void CollectMissingKeys(JsonNode? value, List<RuleRef> refs, string ruleId)
    {
        switch (value)
        {
            case JsonArray list:
                foreach (var item in list) CollectMissingKeys(item, refs, ruleId);
                return;
            case JsonValue scalar when scalar.TryGetValue<string>(out var key) && key.Length > 0:
                RefuseUnsuppliedRoot(key, ruleId);
                if (key.StartsWith("row.", StringComparison.Ordinal)) refs.Add(new RowFieldRef(key["row.".Length..]));
                else refs.Add(new FieldRef(key.StartsWith("field.", StringComparison.Ordinal) ? key["field.".Length..] : key));
                return;
            case JsonObject expression when expression.Count == 1:
                // A dynamic key expression itself has ordinary executable reads. Its resolved
                // target is learned by graph-owned evaluation; do not overload a user field name.
                Walk(expression, refs, ruleId);
                refs.Add(new DynamicReadRef());
                return;
            default:
                refs.Add(new DynamicReadRef());
                return;
        }
    }

    // ── AST metrics (static bounds) ────────────────────────────────────────────

    /// <summary>Counts AST nodes + enforces the per-rule literal-length bound; throws on violation.</summary>
    public static int Measure(JsonNode? node, RuleEngineLimits limits, string ruleId)
    {
        int count = 1;
        switch (node)
        {
            case JsonObject obj:
                foreach (var (_, v) in obj) count += Measure(v, limits, ruleId);
                break;
            case JsonArray arr:
                foreach (var item in arr) count += Measure(item, limits, ruleId);
                break;
            case JsonValue v when v.TryGetValue<string>(out var s) && s.Length > limits.MaxLiteralLength:
                throw new RuleCompilationException(
                    RuleEngineCodes.CompileLiteralTooLong,
                    $"rule '{ruleId}': a string literal of length {s.Length} exceeds the bound {limits.MaxLiteralLength}",
                    ruleId);
        }
        return count;
    }
}

using System.Globalization;
using System.Text;
using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Model;

namespace Harborline.Foundation.RuleEngine.Conformance;

/// <summary>
/// Canonical (deterministic) JSON serialization of a <see cref="RuleOutcome"/> — the
/// cross-tier comparison surface (SPINE-1 design §6.1). Object keys are sorted;
/// integral numbers serialize without a decimal point; the byte form is identical
/// to the TS tier's <c>canonicalOutcome</c> so the conformance corpus can assert
/// <b>byte-identical</b> outcomes across both engines.
/// </summary>
public static class CanonicalJson
{
    /// <summary>Serializes a <see cref="RuleOutcome"/> to its canonical JSON string.</summary>
    public static string SerializeOutcome(RuleOutcome outcome)
    {
        var obj = new JsonObject
        {
            ["ruleId"] = outcome.RuleId,
            ["target"] = outcome.Target.Key,
            ["outputType"] = outcome.OutputType.ToString(),
        };
        switch (outcome.OutputType)
        {
            case OutputType.Value:
                obj["value"] = SerializeComputed(outcome.Value!);
                break;
            case OutputType.Validity:
                obj["validity"] = SerializeValidity(outcome.Validity!);
                break;
            case OutputType.Visibility:
                var vis = outcome.Visibility!;
                obj["visibility"] = new JsonObject
                {
                    ["visible"] = vis.Visible,
                    ["required"] = vis.Required,
                    ["readOnly"] = vis.ReadOnly,
                };
                break;
            case OutputType.Presentation:
                obj["presentation"] = SerializePresentation(outcome.Presentation!);
                break;
            case OutputType.Options:
                obj["options"] = SerializeOptions(outcome.Options!);
                break;
        }
        var sb = new StringBuilder();
        Write(obj, sb);
        return sb.ToString();
    }

    /// <summary>Serializes a bare <see cref="ComputedValue"/> canonically (the guard-value corpus lane; ticket 162).</summary>
    public static string SerializeComputedValue(ComputedValue cv)
    {
        var sb = new StringBuilder();
        Write(SerializeComputed(cv), sb);
        return sb.ToString();
    }

    private static JsonObject SerializeComputed(ComputedValue cv)
    {
        var o = new JsonObject { ["state"] = cv.State.ToString() };
        if (cv.State == ValueState.Resolved) o["value"] = cv.Value?.DeepClone();
        if (cv.State == ValueState.Error && cv.Error is not null) o["error"] = SerializeError(cv.Error);
        return o;
    }

    private static JsonObject SerializeValidity(Validity v)
    {
        var o = new JsonObject { ["ok"] = v.Ok };
        if (v.Error is not null) o["error"] = SerializeError(v.Error);
        return o;
    }

    private static JsonObject SerializeOptions(OptionsOutcome oo)
    {
        var o = new JsonObject { ["state"] = oo.State.ToString() };
        if (oo.State == ValueState.Resolved)
        {
            var arr = new JsonArray();
            foreach (var opt in oo.Options ?? Array.Empty<JsonNode?>()) arr.Add(opt?.DeepClone());
            o["options"] = arr;
        }
        if (oo.State == ValueState.Error && oo.Error is not null) o["error"] = SerializeError(oo.Error);
        return o;
    }

    private static JsonObject SerializeError(RuleError e)
    {
        var p = new JsonObject();
        foreach (var (k, val) in e.Params.OrderBy(kv => kv.Key, StringComparer.Ordinal)) p[k] = val;
        return new JsonObject { ["code"] = e.Code, ["params"] = p };
    }

    private static JsonObject SerializePresentation(PresentationOutcome p)
    {
        var o = new JsonObject
        {
            ["severity"] = p.Severity?.ToString().ToLowerInvariant(),
        };
        if (p.StyleToken is not null) o["styleToken"] = p.StyleToken;
        if (p.Badge is not null)
        {
            var badge = new JsonObject { ["defaultLocale"] = p.Badge.DefaultLocale };
            var values = new JsonObject();
            foreach (var (k, val) in p.Badge.Values.OrderBy(kv => kv.Key, StringComparer.Ordinal)) values[k] = val;
            badge["values"] = values;
            o["badge"] = badge;
        }
        return o;
    }

    /// <summary>Writes any <see cref="JsonNode"/> canonically (sorted keys, integral numbers without a point).</summary>
    public static void Write(JsonNode? node, StringBuilder sb)
    {
        switch (node)
        {
            case null:
                sb.Append("null");
                break;
            case JsonObject obj:
                sb.Append('{');
                bool first = true;
                foreach (var (k, v) in obj.OrderBy(kv => kv.Key, StringComparer.Ordinal))
                {
                    if (!first) sb.Append(',');
                    first = false;
                    WriteString(k, sb);
                    sb.Append(':');
                    Write(v, sb);
                }
                sb.Append('}');
                break;
            case JsonArray arr:
                sb.Append('[');
                for (int i = 0; i < arr.Count; i++)
                {
                    if (i > 0) sb.Append(',');
                    Write(arr[i], sb);
                }
                sb.Append(']');
                break;
            case JsonValue val:
                WriteValue(val, sb);
                break;
        }
    }

    private static void WriteValue(JsonValue val, StringBuilder sb)
    {
        if (val.TryGetValue<bool>(out var b)) { sb.Append(b ? "true" : "false"); return; }
        if (val.TryGetValue<string>(out var s)) { WriteString(s, sb); return; }
        if (val.TryGetValue<long>(out var l)) { sb.Append(CanonicalNumber.ToJsonString(l)); return; }
        if (val.TryGetValue<int>(out var iv)) { sb.Append(CanonicalNumber.ToJsonString((long)iv)); return; }
        if (val.TryGetValue<double>(out var d)) { sb.Append(CanonicalNumber.ToJsonString(d)); return; }
        // Fallback: round-trip raw JSON text.
        sb.Append(val.ToJsonString());
    }

    private static void WriteString(string s, StringBuilder sb)
    {
        sb.Append('"');
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }
}

using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Evaluation;
using Harborline.Foundation.RuleEngine.Graph;
