namespace Harborline.Foundation.RuleEngine.Context;

/// <summary>
/// The evaluation scope a resolver is produced for (ADR 0146 D3). Carries the optional
/// child-collection row — <c>section</c> + <c>row id</c> — that a rule's <c>row.</c>
/// references resolve against. A pillar with no repeating sub-collection (a flat event
/// payload, a single merge record) evaluates at <see cref="Root"/>; its resolver returns a
/// bad-reference for any <c>row.</c> path, exactly as the flat workflow guard bag does.
/// </summary>
public readonly record struct RuleEvalScope(string? RowSection = null, string? RowId = null)
{
    /// <summary>The top-level (non-row) scope.</summary>
    public static RuleEvalScope Root { get; } = new();
}

/// <summary>
/// The context-adapter seam (ADR 0146 D3, board F3). The contract a consumer pillar
/// implements to map its own data shape into the rule engine's scope grammar: given an
/// <see cref="RuleEvalScope"/>, produce the <see cref="IValueResolver"/> the interpreter
/// resolves a compiled rule's <c>var</c>/<c>agg</c> references against.
/// </summary>
/// <remarks>
/// The operator set + interpreter are sized ONCE (D3); each pillar adapts its data HERE
/// rather than growing per-pillar operators. This interface — the seam — is owned by
/// ADR 0146 Wave 1; the forms (<see cref="FormContextAdapter"/>) and workflow-guard
/// (<see cref="ContextBagAdapter"/>) contexts are its first (migrated) implementations. The
/// three concrete new adapters (document-merge, event-payload, dataset-row) land with their
/// pillar programs (#111/#112/#113) implementing this same contract — own the seam, scatter
/// the implementations.
/// </remarks>
public interface IContextAdapter
{
    /// <summary>Produces the resolver bound to this adapter's pillar data for <paramref name="scope"/>.</summary>
    IValueResolver CreateResolver(RuleEvalScope scope);
}

/// <summary>
/// The forms context as the first <see cref="IContextAdapter"/> implementation (ADR 0146 D3).
/// Maps a bound <see cref="RuleInstance"/> plus the graph's already-evaluated computed cells
/// into a <see cref="CellResolver"/> for the requested scope. Behaviour-neutral: the reactive
/// form graph obtains its per-cell / per-row resolvers through this seam instead of
/// constructing <see cref="CellResolver"/> inline. The computed-cell dictionary is held by
/// reference — it is filled live as the graph evaluates in topo order, so a resolver produced
/// mid-evaluation reads the up-to-date upstream cells, identical to the pre-seam construction.
/// </summary>
internal sealed class FormContextAdapter : IContextAdapter
{
    private readonly IReadOnlyDictionary<string, ComputedValue> _computed;
    private readonly RuleInstance _instance;

    public FormContextAdapter(IReadOnlyDictionary<string, ComputedValue> computed, RuleInstance instance)
    {
        _computed = computed;
        _instance = instance;
    }

    public IValueResolver CreateResolver(RuleEvalScope scope)
        => new CellResolver(_computed, _instance, scope.RowSection, scope.RowId);
}

/// <summary>
/// The workflow-guard context as an <see cref="IContextAdapter"/> (ADR 0146 D3): maps a flat
/// process / context bag into a <see cref="ContextBagResolver"/>. The bag has no repeating
/// sub-collection, so <see cref="RuleEvalScope.RowSection"/> is ignored (a <c>row.</c>
/// reference resolves to a bad-reference, as before).
/// </summary>
internal sealed class ContextBagAdapter : IContextAdapter
{
    private readonly IReadOnlyDictionary<string, JsonNode?> _bag;

    public ContextBagAdapter(IReadOnlyDictionary<string, JsonNode?> bag) => _bag = bag;

    public IValueResolver CreateResolver(RuleEvalScope scope) => new ContextBagResolver(_bag);
}

using System.Text.Json.Nodes;
using System.Text.Json;

using Harborline.Foundation.RuleEngine.Evaluation;
using Harborline.Foundation.RuleEngine.Graph;
using Harborline.Foundation.RuleEngine.Model;

namespace Harborline.Foundation.RuleEngine.Context;

/// <summary>
/// Runtime-owned inert values captured before pure rule evaluation. Host adapters and
/// dictionaries are deliberately not accepted by the evaluator entry point.
/// </summary>
public sealed class RuleContextSnapshot
{
    // Runtime input envelope, shared with the TS JSON-text capture boundary. These are
    // implementation limits for owned evaluation data, separate from authored AST limits.
    /// <summary>The largest captured context, in UTF-8 bytes of JSON text (256 KiB); larger input is rejected.</summary>
    public const int MaxUtf8Bytes = RuntimeInputEnvelope.MaxUtf8Bytes;
    /// <summary>The deepest JSON nesting a captured context may have.</summary>
    public const int MaxDepth = RuntimeInputEnvelope.MaxDepth;
    /// <summary>The most JSON values, containers and scalars alike, a captured context may hold.</summary>
    public const int MaxNodes = RuntimeInputEnvelope.MaxNodes;
    private readonly IReadOnlyDictionary<string, JsonNode?> _root;
    private readonly IReadOnlyDictionary<string, JsonNode?>? _row;

    private RuleContextSnapshot(IReadOnlyDictionary<string, JsonNode?> root, IReadOnlyDictionary<string, JsonNode?>? row)
    {
        _root = root;
        _row = row;
    }

    /// <summary>Captures JSON data by value outside the evaluator.</summary>
    public static RuleContextSnapshot Capture(
        IReadOnlyDictionary<string, JsonNode?> root,
        IReadOnlyDictionary<string, JsonNode?>? row = null)
    {
        ArgumentNullException.ThrowIfNull(root);
        // This is deliberate host capture: it may enumerate the caller's trusted dictionary,
        // but the evaluator receives only a fresh JSON parse with no caller-owned JsonNode alias.
        var envelope = new JsonObject { ["root"] = ToObject(root) };
        if (row is not null) envelope["row"] = ToObject(row);
        return FromJsonText(envelope.ToJsonString());
    }

    /// <summary>Admits one bounded JSON-text context into runtime-owned inert data.</summary>
    public static RuleContextSnapshot FromJsonText(string jsonText)
    {
        ArgumentNullException.ThrowIfNull(jsonText);
        JsonObject envelope;
        try
        {
            envelope = RuntimeInputEnvelope.Parse(jsonText, nameof(jsonText))?.AsObject()
                ?? throw new ArgumentException("Rule context must be a JSON object.", nameof(jsonText));
        }
        catch (JsonException exception)
        {
            throw new ArgumentException("Rule context is not valid bounded JSON.", nameof(jsonText), exception);
        }
        if (!envelope.TryGetPropertyValue("root", out var rootNode) || rootNode is not JsonObject root)
            throw new ArgumentException("Rule context must contain an object root.", nameof(jsonText));
        JsonObject? row = null;
        if (envelope.TryGetPropertyValue("row", out var rowNode) && rowNode is not null)
            row = rowNode as JsonObject ?? throw new ArgumentException("Rule context row must be an object.", nameof(jsonText));
        return new RuleContextSnapshot(CloneObject(root), row is null ? null : CloneObject(row));
    }

    internal IValueResolver CreateResolver(RuleEvalScope scope) => new SnapshotResolver(_root, _row, scope);

    private static IReadOnlyDictionary<string, JsonNode?> Clone(IReadOnlyDictionary<string, JsonNode?> source)
        => source.ToDictionary(pair => pair.Key, pair => pair.Value?.DeepClone(), StringComparer.Ordinal);

    private static JsonObject ToObject(IReadOnlyDictionary<string, JsonNode?> source)
    {
        var result = new JsonObject();
        foreach (var (key, value) in source) result[key] = value?.DeepClone();
        return result;
    }

    private static IReadOnlyDictionary<string, JsonNode?> CloneObject(JsonObject source)
        => source.ToDictionary(pair => pair.Key, pair => pair.Value?.DeepClone(), StringComparer.Ordinal);

}

internal sealed class SnapshotResolver(
    IReadOnlyDictionary<string, JsonNode?> root,
    IReadOnlyDictionary<string, JsonNode?>? row,
    RuleEvalScope scope) : IValueResolver
{
    public RefValue ResolveVar(string path)
    {
        if (path.StartsWith("row.", StringComparison.Ordinal))
        {
            if (row is null || scope.RowSection is null || scope.RowId is null)
                return RefValue.OfError(RuleError.Of(RuleEngineCodes.BadReference, "path", path));
            return Read(row, path["row.".Length..], path);
        }
        var name = path.StartsWith("field.", StringComparison.Ordinal) ? path["field.".Length..] : path;
        if (!path.StartsWith("field.", StringComparison.Ordinal) && row is not null && row.TryGetValue(name, out var local))
            return PendingSentinel.Is(local) ? RefValue.Pending : RefValue.Resolved(local);
        return root.TryGetValue(name, out var value)
            ? (PendingSentinel.Is(value) ? RefValue.Pending : RefValue.Resolved(value))
            : RefValue.Resolved(null);
    }

    public RefValue ResolveAgg(string fn, string section, string col) => RefValue.UnavailableAggregate(fn, section, col);

    private static RefValue Read(IReadOnlyDictionary<string, JsonNode?> values, string name, string path)
        => values.TryGetValue(name, out var value)
            ? (PendingSentinel.Is(value) ? RefValue.Pending : RefValue.Resolved(value))
            : RefValue.OfError(RuleError.Of(RuleEngineCodes.BadReference, "path", path));
}

using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;

namespace Harborline.Foundation.RuleEngine.Context;

/// <summary>
/// Finite JSON-text host-capture envelope for runtime-owned evaluation data. Limits
/// cover UTF-8 source bytes, JSON nesting, and every JSON value (containers and
/// scalars); authored-expression limits are separate.
/// </summary>
internal static class RuntimeInputEnvelope
{
    internal const int MaxUtf8Bytes = 262_144;
    internal const int MaxDepth = 64;
    internal const int MaxNodes = 5_000;

    internal static JsonNode? Parse(string jsonText, string parameterName)
    {
        ArgumentNullException.ThrowIfNull(jsonText);
        // UTF-8 never uses fewer bytes than UTF-16 code units. Reject this cheap
        // upper bound before scanning or allocating a byte buffer for hostile text.
        if (jsonText.Length > MaxUtf8Bytes)
            throw new ArgumentException("Rule context exceeds the UTF-8 byte envelope.", parameterName);
        if (Encoding.UTF8.GetByteCount(jsonText) > MaxUtf8Bytes)
            throw new ArgumentException("Rule context exceeds the UTF-8 byte envelope.", parameterName);
        var utf8 = Encoding.UTF8.GetBytes(jsonText);

        try
        {
            var reader = new Utf8JsonReader(utf8, new JsonReaderOptions { MaxDepth = MaxDepth });
            var nodes = 0;
            while (reader.Read())
            {
                if (reader.TokenType is JsonTokenType.StartObject or JsonTokenType.StartArray or JsonTokenType.String
                    or JsonTokenType.Number or JsonTokenType.True or JsonTokenType.False or JsonTokenType.Null)
                {
                    if (++nodes > MaxNodes)
                        throw new ArgumentException("Rule context exceeds the node envelope.", parameterName);
                }
            }

            // A JSON null is a valid captured scalar for reactive field updates.
            return JsonNode.Parse(utf8, documentOptions: new JsonDocumentOptions { MaxDepth = MaxDepth });
        }
        catch (JsonException exception)
        {
            throw new ArgumentException("Rule context is not valid bounded JSON.", parameterName, exception);
        }
    }

    internal static void ValidateMemberName(string value, string parameterName)
    {
        ArgumentNullException.ThrowIfNull(value);
        if (value.Length > MaxUtf8Bytes || Encoding.UTF8.GetByteCount(value) > MaxUtf8Bytes)
            throw new ArgumentException("Rule context member name exceeds the UTF-8 byte envelope.", parameterName);
    }
}

