/// <summary>The evaluation phases a borrower declaration marks applicable or inapplicable (ADR 0099 decision 8).</summary>
public enum EvaluationPhase
{
    /// <summary>Checking a definition while it is being authored.</summary>
    AuthoringValidation,
    /// <summary>Admitting a definition when it is published.</summary>
    PublishValidation,
    /// <summary>Presenting a form or view to a user.</summary>
    Render,
    /// <summary>Accepting a submitted form or record write.</summary>
    Submission,
    /// <summary>Executing a workflow, automation or report run.</summary>
    Run,
    /// <summary>Approving or signing off a completed record.</summary>
    SignOff,
}

/// <summary>
/// A borrowing member's typed expression environment (DES-0018 <c>rules-ck-28</c>, ADR 0099 decision 8).
/// The row lives in the borrower's own record; Rules only admits it. Every member is explicit: there is
/// no ambient default, and every phase is marked applicable or not.
/// </summary>
/// <param name="Borrower">The borrower's declaring item id, e.g. <c>forms-ck-13</c>.</param>
/// <param name="Grammar">Borrowed grammar and version, <c>harborline-jsonlogic/v1</c> in R1.</param>
/// <param name="Variables">Variable names and types; the scope tokens an expression may address are among them.</param>
/// <param name="Operations">Allowed functions and operators, by built-in key.</param>
/// <param name="Effects">Effect capability set; R1 admits only <c>field-read</c>.</param>
/// <param name="MissingValues">Null and missing-field semantics.</param>
/// <param name="TimeSource">The time source.</param>
/// <param name="TimeZone">The time-zone behaviour.</param>
/// <param name="Phases">Every phase, marked applicable (true) or inapplicable (false).</param>
/// <param name="Replay">The deterministic replay policy.</param>
public sealed record BorrowerEnvironmentDeclaration(
    string Borrower,
    string Grammar,
    IReadOnlyDictionary<string, string> Variables,
    IReadOnlyList<string> Operations,
    IReadOnlyList<string> Effects,
    string MissingValues,
    string TimeSource,
    string TimeZone,
    IReadOnlyDictionary<EvaluationPhase, bool> Phases,
    string Replay);

/// <summary>A refused admission or an evaluation outside the admitted environment, by stable code.</summary>
public sealed class BorrowerEnvironmentException(string code, string message) : Exception(message)
{
    /// <summary>The stable refusal code.</summary>
    public string Code { get; } = code;
}

/// <summary>
/// A declaration Rules has admitted. It has no public constructor: the only way to hold one is
/// <see cref="BorrowerEnvironmentAdmission.Admit"/>, so an evaluation entry point that requires it
/// requires evidence of admission (the <c>ValidatedRecordBody</c> precedent).
/// </summary>
public sealed class AdmittedEnvironment
{
    private readonly HashSet<string> _operations;
    private readonly HashSet<string> _variables;

    internal AdmittedEnvironment(BorrowerEnvironmentDeclaration declaration)
    {
        Declaration = declaration;
        _operations = new HashSet<string>(declaration.Operations, StringComparer.Ordinal);
        _variables = new HashSet<string>(declaration.Variables.Keys, StringComparer.Ordinal);
    }

    /// <summary>The admitted declaration.</summary>
    public BorrowerEnvironmentDeclaration Declaration { get; }

    /// <summary>Evidence for one evaluation phase; refuses a phase the declaration marks inapplicable.</summary>
    public EvaluationAdmission For(EvaluationPhase phase) => Declaration.Phases.TryGetValue(phase, out var applicable) && applicable
        ? new EvaluationAdmission(this, phase)
        : throw new BorrowerEnvironmentException(BorrowerEnvironmentAdmission.PhaseNotAdmitted,
            $"{Declaration.Borrower} does not admit evaluation in phase {phase}");

    internal string? Refusal(IEnumerable<JsonNode?> programs)
    {
        foreach (var program in programs)
            if (Walk(program) is { } refusal) return refusal;
        return null;
    }

    private string? Walk(JsonNode? node)
    {
        if (node is not JsonObject { Count: 1 } call) return null;
        var (op, raw) = (call.First().Key, call.First().Value);
        if (!_operations.Contains(op)) return BorrowerEnvironmentAdmission.OperationNotAdmitted;
        var args = raw is JsonArray array ? array.ToList() : [raw];
        if (op == "var" && args.FirstOrDefault() is JsonValue path && path.TryGetValue<string>(out var p) && !Addresses(p))
            return BorrowerEnvironmentAdmission.VariableNotAdmitted;
        if (op == "agg" && !_variables.Contains("row")) return BorrowerEnvironmentAdmission.VariableNotAdmitted;
        foreach (var arg in args)
            if (Walk(arg) is { } refusal) return refusal;
        return null;
    }

    private bool Addresses(string path)
    {
        int dot = path.IndexOf('.');
        return _variables.Contains(dot < 0 ? "field" : path[..dot]);
    }
}

/// <summary>An admitted environment bound to the phase one evaluation runs in.</summary>
public sealed class EvaluationAdmission
{
    internal EvaluationAdmission(AdmittedEnvironment environment, EvaluationPhase phase)
    {
        Environment = environment;
        Phase = phase;
    }

    /// <summary>The admitted environment.</summary>
    public AdmittedEnvironment Environment { get; }

    /// <summary>The phase this evaluation runs in.</summary>
    public EvaluationPhase Phase { get; }
}

/// <summary>
/// Rules' admission of borrower environments (DES-0018 <c>rules-eng-26</c>, ADR 0095 rulings 10 and 11)
/// and the runtime check every evaluation entry point makes.
/// </summary>
public static class BorrowerEnvironmentAdmission
{
    /// <summary>The only grammar R1 lends.</summary>
    public const string Grammar = "harborline-jsonlogic/v1";

    /// <summary>The only effect capability R1 admits.</summary>
    public const string FieldRead = "field-read";

    /// <summary>The declaration is malformed or asks for something Rules does not lend.</summary>
    public const string DeclarationRefused = "rule.environment.declaration_refused";

    /// <summary>An evaluation arrived without admission evidence.</summary>
    public const string NotAdmitted = "rule.environment.not_admitted";

    /// <summary>The phase is not one the declaration marks applicable.</summary>
    public const string PhaseNotAdmitted = "rule.environment.phase_not_admitted";

    /// <summary>The program calls a function the declaration does not admit.</summary>
    public const string OperationNotAdmitted = "rule.environment.operation_not_admitted";

    /// <summary>The program addresses a variable the declaration does not admit.</summary>
    public const string VariableNotAdmitted = "rule.environment.variable_not_admitted";

    /// <summary>Admits a declaration or refuses it by <see cref="DeclarationRefused"/>.</summary>
    public static AdmittedEnvironment Admit(BorrowerEnvironmentDeclaration declaration)
    {
        ArgumentNullException.ThrowIfNull(declaration);
        string? reason =
            Blank(declaration.Borrower) ? "borrower" :
            declaration.Grammar != Grammar ? "grammar" :
            declaration.Variables is null || declaration.Variables.Count == 0 || declaration.Variables.Any(v => Blank(v.Key) || Blank(v.Value)) ? "variables" :
            declaration.Operations is null || declaration.Operations.Any(op => !BuiltInFunctionRegister.TryResolve(op, out _)) ? "operations" :
            declaration.Effects is null || declaration.Effects.Any(effect => effect != FieldRead) ? "effects" :
            Blank(declaration.MissingValues) ? "missing-values" :
            Blank(declaration.TimeSource) || Blank(declaration.TimeZone) ? "time" :
            declaration.Phases is null || Enum.GetValues<EvaluationPhase>().Any(phase => !declaration.Phases.ContainsKey(phase)) ? "phases" :
            Blank(declaration.Replay) ? "replay" : null;
        return reason is null
            ? new AdmittedEnvironment(declaration)
            : throw new BorrowerEnvironmentException(DeclarationRefused, $"{declaration.Borrower}: {reason}");
    }

    /// <summary>
    /// The runtime check at an evaluation entry point: null when <paramref name="admission"/> admits every
    /// operation and variable the compiled program uses, otherwise the refusal code.
    /// </summary>
    internal static string? Check(EvaluationAdmission? admission, CompiledGraph compiled)
        => admission is null ? NotAdmitted : admission.Environment.Refusal(compiled.Rules.Select(rule => rule.Ast));

    /// <summary>
    /// Checks, without evaluating it, whether a compiled guard only addresses operations and variables the
    /// borrower's declaration admits for <paramref name="phase"/>. Returns <see langword="null"/> when it
    /// is admitted, otherwise the stable refusal code.
    /// </summary>
    public static string? CheckCompiledGuard(
        CompiledGraph compiled,
        BorrowerEnvironmentDeclaration declaration,
        EvaluationPhase phase)
    {
        ArgumentNullException.ThrowIfNull(compiled);
        return Admit(declaration).For(phase).Environment.Refusal(compiled.LoweredAsts);
    }

    /// <summary>Canonical JSON options shared with the TS tier's <c>JSON.stringify</c> (no HTML escaping).</summary>
    public static JsonSerializerOptions CanonicalOptions { get; } = new() { Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping };

    /// <summary>
    /// The canonical export of a declaration: sorted keys, every phase present with its applicability and
    /// every variable with its type, so scope narrowing and phase exclusions survive release byte for byte.
    /// </summary>
    public static string CanonicalJson(BorrowerEnvironmentDeclaration declaration)
    {
        ArgumentNullException.ThrowIfNull(declaration);
        return new JsonObject
        {
            ["borrower"] = declaration.Borrower,
            ["effects"] = new JsonArray([.. declaration.Effects.Select(effect => (JsonNode?)effect)]),
            ["grammar"] = declaration.Grammar,
            ["missingValues"] = declaration.MissingValues,
            ["operations"] = new JsonArray([.. declaration.Operations.Select(op => (JsonNode?)op)]),
            ["phases"] = new JsonObject(declaration.Phases.OrderBy(p => p.Key.ToString(), StringComparer.Ordinal)
                .Select(p => KeyValuePair.Create(p.Key.ToString(), (JsonNode?)p.Value))),
            ["replay"] = declaration.Replay,
            ["timeSource"] = declaration.TimeSource,
            ["timeZone"] = declaration.TimeZone,
            ["variables"] = new JsonObject(declaration.Variables.OrderBy(v => v.Key, StringComparer.Ordinal)
                .Select(v => KeyValuePair.Create(v.Key, (JsonNode?)v.Value))),
        }.ToJsonString(CanonicalOptions);
    }

    private static bool Blank(string? value) => string.IsNullOrWhiteSpace(value);
}

using System.Globalization;

namespace Harborline.Foundation.RuleEngine.Evaluation;

/// <summary>
/// Deterministic, timezone-free calendar arithmetic for the <c>date.*</c>
/// operators (SPINE-1 design §1.4). Dates are <c>YYYY-MM-DD</c> in the proleptic
/// Gregorian calendar (UTC, date-only — DST is structurally excluded). Uses
/// Howard Hinnant's days-from-civil algorithm so leap years are exact and the
/// result is <b>byte-identical</b> to the TS tier's port.
/// </summary>
internal static class DateMath
{
    /// <summary>Parses a <c>YYYY-MM-DD</c> date into (year, month, day); throws on malformed input.</summary>
    public static (int Y, int M, int D) Parse(string text)
    {
        if (text is null || text.Length < 8) throw new FormatException($"invalid date '{text}'");
        var parts = text.Split('-');
        // Support an optional time suffix by truncating at 'T'.
        if (parts.Length >= 3)
        {
            var dayPart = parts[2];
            int tIdx = dayPart.IndexOf('T');
            if (tIdx >= 0) dayPart = dayPart[..tIdx];
            if (int.TryParse(parts[0], NumberStyles.None, CultureInfo.InvariantCulture, out int y)
                && int.TryParse(parts[1], NumberStyles.None, CultureInfo.InvariantCulture, out int m)
                && int.TryParse(dayPart, NumberStyles.None, CultureInfo.InvariantCulture, out int d)
                && m is >= 1 and <= 12 && d is >= 1 and <= 31)
            {
                return (y, m, d);
            }
        }
        throw new FormatException($"invalid date '{text}'");
    }

    /// <summary>Howard Hinnant's days_from_civil: serial day number (1970-01-01 = 0).</summary>
    public static long EpochDay(int y, int m, int d)
    {
        long yy = m <= 2 ? y - 1 : y;
        long era = (yy >= 0 ? yy : yy - 399) / 400;
        long yoe = yy - era * 400;                                  // [0, 399]
        long doy = (153 * (m > 2 ? m - 3 : m + 9) + 2) / 5 + d - 1; // [0, 365]
        long doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;           // [0, 146096]
        return era * 146097 + doe - 719468;
    }

    /// <summary>Inverse of <see cref="EpochDay"/>: civil date from a serial day number.</summary>
    public static (int Y, int M, int D) FromEpochDay(long z)
    {
        z += 719468;
        long era = (z >= 0 ? z : z - 146096) / 146097;
        long doe = z - era * 146097;                                  // [0, 146096]
        long yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365; // [0, 399]
        long y = yoe + era * 400;
        long doy = doe - (365 * yoe + yoe / 4 - yoe / 100);           // [0, 365]
        long mp = (5 * doy + 2) / 153;                                 // [0, 11]
        long d = doy - (153 * mp + 2) / 5 + 1;                         // [1, 31]
        long m = mp < 10 ? mp + 3 : mp - 9;                            // [1, 12]
        return ((int)(m <= 2 ? y + 1 : y), (int)m, (int)d);
    }

    private static int DaysInMonth(int y, int m)
    {
        int[] lengths = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
        if (m == 2 && IsLeap(y)) return 29;
        return lengths[m - 1];
    }

    private static bool IsLeap(int y) => (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;

    private static string Format(int y, int m, int d)
        => $"{y:D4}-{m:D2}-{d:D2}";

    /// <summary>Today's UTC date (from an injected clock) as <c>YYYY-MM-DD</c>.</summary>
    public static string Today(DateTimeOffset nowUtc)
        => Format(nowUtc.UtcDateTime.Year, nowUtc.UtcDateTime.Month, nowUtc.UtcDateTime.Day);

    /// <summary>Adds <paramref name="n"/> of <paramref name="unit"/> (day|month|year) with day-clamping.</summary>
    public static string Add(string date, long n, string unit)
    {
        var (y, m, d) = Parse(date);
        switch (unit)
        {
            case "day":
                var (ny, nm, nd) = FromEpochDay(EpochDay(y, m, d) + n);
                return Format(ny, nm, nd);
            case "month":
            {
                long total = (long)y * 12 + (m - 1) + n;
                int yr = (int)Math.DivRem(total, 12, out long mo);
                if (mo < 0) { mo += 12; yr -= 1; }
                int month = (int)mo + 1;
                int day = Math.Min(d, DaysInMonth(yr, month));
                return Format(yr, month, day);
            }
            case "year":
            {
                int yr = y + (int)n;
                int day = Math.Min(d, DaysInMonth(yr, m));
                return Format(yr, m, day);
            }
            default:
                throw new FormatException($"unknown date unit '{unit}'");
        }
    }

    /// <summary>Difference <c>a - b</c> in whole days (v1 supports the <c>day</c> unit).</summary>
    public static long DiffDays(string a, string b)
    {
        var (ay, am, ad) = Parse(a);
        var (by, bm, bd) = Parse(b);
        return EpochDay(ay, am, ad) - EpochDay(by, bm, bd);
    }
}

using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Model;

namespace Harborline.Foundation.RuleEngine.Evaluation;

/// <summary>The resolution of a referenced cell handed to the evaluator. Public as the value
/// vocabulary an <see cref="Context.IContextAdapter"/> resolver speaks (ADR 0146 D3).</summary>
public readonly struct RefValue
{
    private RefValue(ValueState state, JsonNode? value, RuleError? error)
    {
        State = state;
        Value = value;
        Error = error;
    }

    /// <summary>Whether the reference resolved, errored, or is still pending.</summary>
    public ValueState State { get; }
    /// <summary>The resolved value; null when not resolved, and also a legitimate resolved JSON null.</summary>
    public JsonNode? Value { get; }
    /// <summary>The coded error when <see cref="State"/> is <see cref="ValueState.Error"/>; otherwise null.</summary>
    public RuleError? Error { get; }

    /// <summary>A resolved reference holding <paramref name="value"/>.</summary>
    public static RefValue Resolved(JsonNode? value) => new(ValueState.Resolved, value, null);
    /// <summary>A reference that failed with <paramref name="error"/>.</summary>
    public static RefValue OfError(RuleError error) => new(ValueState.Error, null, error);
    /// <summary>A reference whose value is not yet available; rules reading it evaluate to pending.</summary>
    public static RefValue Pending { get; } = new(ValueState.Pending, null, null);

    /// <summary>The ONE bad-aggregate refusal shape in this tier (ticket 162): an aggregate the
    /// evaluation context cannot provide refuses with <c>rule.bad_reference</c> carrying the
    /// address params <c>{agg: "section/fn/col"}</c>. Both resolvers (the form graph's
    /// CellResolver and the guard evaluator's ContextBagResolver) construct it HERE, so the
    /// param order cannot drift within the tier; the shared corpus pins the shape across tiers.</summary>
    public static RefValue UnavailableAggregate(string fn, string section, string col)
        => OfError(RuleError.Of(RuleEngineCodes.BadReference, "agg", section + "/" + fn + "/" + col));
}

/// <summary>
/// Resolves <c>var</c> / <c>agg</c> references for one rule evaluation against the
/// already-evaluated upstream cells + raw instance values (SPINE-1 design §2.2). Public as
/// the resolver an <see cref="Context.IContextAdapter"/> produces for its pillar data (ADR 0146 D3).
/// </summary>
public interface IValueResolver
{
    /// <summary>Resolves a canonical var path (<c>field.x</c> / <c>row.y</c> / <c>parent.f</c>).</summary>
    RefValue ResolveVar(string path);

    /// <summary>Resolves a table aggregate (<c>fn</c> over <c>section</c>.<c>col</c>).</summary>
    RefValue ResolveAgg(string fn, string section, string col);
}

/// <summary>
/// The shared step budget + wall-clock token for one whole-instance evaluation
/// (SPINE-1 design §4). One <see cref="EvalBudget"/> spans every cell + rule in the
/// instance so the 250k-op budget is a per-instance total, not per-rule.
/// </summary>
internal sealed class EvalBudget
{
    public EvalBudget(RuleEngineLimits limits, CancellationToken ct)
    {
        Limits = limits;
        CancellationToken = ct;
    }

    public RuleEngineLimits Limits { get; }
    public CancellationToken CancellationToken { get; }

    /// <summary>Steps consumed so far across the whole instance evaluation.</summary>
    public int Steps { get; private set; }

    /// <summary>Charges one step. The op-budget is the authoritative, outcome-affecting bound (fails
    /// closed with <see cref="RuleBudgetException"/>). The wall-clock / cancellation token is a
    /// non-authoritative liveness guard: it throws <see cref="RuleEngineTimeoutException"/>, which
    /// propagates as an infrastructure fault and NEVER becomes a divergent evaluation outcome
    /// (D1 ratification 2026-07-01).</summary>
    public void Charge()
    {
        if (CancellationToken.IsCancellationRequested) throw new RuleEngineTimeoutException();
        if (++Steps > Limits.StepBudget) throw new RuleBudgetException();
    }

    /// <summary>Charges <paramref name="size"/> steps proportional to a large operand's size — string
    /// concat and money arithmetic do O(size) … super-linear work for ONE AST node, so a single big
    /// operand must be charged proportionally rather than the flat one step (finding F4). Fails closed
    /// identically to <see cref="Charge"/>; the per-step add is clamped so it cannot overflow.</summary>
    public void ChargeSize(int size)
    {
        if (CancellationToken.IsCancellationRequested) throw new RuleEngineTimeoutException();
        Steps += size > Limits.StepBudget ? Limits.StepBudget + 1 : (size < 1 ? 1 : size);
        if (Steps > Limits.StepBudget) throw new RuleBudgetException();
    }
}

/// <summary>Per-cell evaluation state: the shared <see cref="EvalBudget"/> + this cell's resolver + clock.</summary>
internal sealed class EvalContext
{
    public EvalContext(IValueResolver resolver, DateTimeOffset now, EvalBudget budget)
    {
        Resolver = resolver;
        Now = now;
        Budget = budget;
    }

    public IValueResolver Resolver { get; }
    public DateTimeOffset Now { get; }
    public EvalBudget Budget { get; }

    /// <summary>Charges one step against the shared budget; fails closed on overflow/cancellation.</summary>
    public void Charge() => Budget.Charge();
}

/// <summary>A recoverable evaluation error that becomes a <c>ComputedValue.Error</c> / <c>Validity</c> failure.</summary>
internal sealed class RuleEvalException : Exception
{
    public RuleEvalException(RuleError error) => Error = error;
    public RuleError Error { get; }
}

/// <summary>Signals a referenced cell is <c>Pending</c> — the whole outcome becomes Pending.</summary>
internal sealed class RulePendingException : Exception;

/// <summary>Signals the per-instance step budget was exhausted — the authoritative, deterministic,
/// outcome-affecting bound (becomes a fail-closed <c>rule.budget_exceeded</c> result).</summary>
internal sealed class RuleBudgetException : Exception;

