namespace Harborline.Foundation.RuleEngine.Evaluation;

/// <summary>
/// The closed, versioned <c>harborline-jsonlogic/v1</c> operator interpreter
/// (SPINE-1 design §1.4). A self-contained bounded evaluator (NOT a third-party
/// JsonLogic library) so the operator semantics, the step budget, and the AST
/// node accounting are under SPINE-1's own control and are <b>byte-identical</b>
/// to the TS tier's port (Decision DI — built our own; rationale in README).
/// </summary>
/// <remarks>
/// <para><b>v1 operator set (the normative table — README §operators):</b>
/// data <c>var</c>/<c>missing</c>/<c>missing_some</c>; logic
/// <c>==</c>/<c>!=</c>/<c>===</c>/<c>!==</c>/<c>!</c>/<c>!!</c>/<c>and</c>/<c>or</c>/<c>if</c>;
/// compare <c>&gt;</c>/<c>&gt;=</c>/<c>&lt;</c>/<c>&lt;=</c>; arithmetic
/// <c>+</c>/<c>-</c>/<c>*</c>/<c>/</c>/<c>%</c>/<c>min</c>/<c>max</c>; membership
/// <c>in</c>/<c>cat</c>; earlier source <c>agg</c>/<c>money.add</c>/<c>money.sub</c>/<c>money.mul</c>/
/// <c>date.add</c>/<c>date.diff</c>/<c>date.today</c>/<c>coding.is</c>.</para>
/// <para><b>Deliberately excluded (v1):</b> any regex/pattern operator (ReDoS
/// structurally absent — Decision DG); <c>map</c>/<c>filter</c>/<c>reduce</c>/<c>merge</c>
/// (deferred — child-table folds use <c>agg</c>).</para>
/// </remarks>
internal static class HarborlineJsonLogic
{
    /// <summary>
    /// Evaluates a lowered AST node to a value. Throws <see cref="RuleEvalException"/>
    /// (becomes an <c>Error</c> outcome), <see cref="RulePendingException"/> (Pending),
    /// <see cref="RuleBudgetException"/> (authoritative fail-closed op-budget), or
    /// <see cref="RuleEngineTimeoutException"/> (non-authoritative liveness fault — propagates,
    /// never an outcome; D1 ratification 2026-07-01).
    /// </summary>
    public static JsonNode? Evaluate(JsonNode? node, EvalContext ctx)
    {
        ctx.Charge();

        // Literals (anything that is not a single-key operator object) evaluate to themselves.
        if (node is not JsonObject obj || obj.Count != 1)
        {
            return node?.DeepClone();
        }

        var (op, argNode) = (obj.First().Key, obj.First().Value);
        var args = AsArgList(argNode);

        // The R1 register is the only dispatch table (rules-eng-27); an unregistered key refuses.
        return BuiltInFunctionRegister.TryResolve(op, out var function)
            ? function.Invoke(args, ctx)
            : throw new RuleEvalException(RuleError.Of(RuleEngineCodes.UnknownOperator, "op", op));
    }

    // ── operand plumbing ────────────────────────────────────────────────────

    internal static List<JsonNode?> AsArgList(JsonNode? argNode)
    {
        if (argNode is JsonArray arr) return arr.Select(x => x).ToList();
        return new List<JsonNode?> { argNode };
    }

    internal static JsonNode? Eval(List<JsonNode?> args, int i, EvalContext ctx)
        => i < args.Count ? Evaluate(args[i], ctx) : null;

    internal static JsonNode Bool(bool b) => JsonValue.Create(b);

    // ── var / missing ───────────────────────────────────────────────────────

    internal static JsonNode? EvalVar(List<JsonNode?> args, EvalContext ctx)
    {
        string path = AsString(args.Count > 0 ? Evaluate(args[0], ctx) : null) ?? "";
        if (path.Length == 0) return null;
        var rv = ctx.Resolver.ResolveVar(path);
        return Unwrap(rv, args.Count > 1 ? Evaluate(args[1], ctx) : null);
    }

    internal static JsonNode? Unwrap(RefValue rv, JsonNode? fallback)
    {
        switch (rv.State)
        {
            case ValueState.Pending: throw new RulePendingException();
            case ValueState.Error: throw new RuleEvalException(rv.Error ?? RuleError.Of(RuleEngineCodes.UpstreamError));
            default:
                return rv.Value is null && fallback is not null ? fallback.DeepClone() : rv.Value?.DeepClone();
        }
    }

    internal static JsonNode EvalMissing(List<JsonNode?> args, EvalContext ctx)
    {
        var keys = args.Count == 1 && Evaluate(args[0], ctx) is JsonArray a
            ? a.Select(x => AsString(x) ?? "").ToList()
            : args.Select(x => AsString(Evaluate(x, ctx)) ?? "").ToList();
        var missing = new JsonArray();
        foreach (var k in keys)
        {
            if (k.Length == 0) continue;
            var rv = ctx.Resolver.ResolveVar(k);
            if (rv.State == ValueState.Pending) throw new RulePendingException();
            if (rv.State == ValueState.Error) throw new RuleEvalException(rv.Error ?? RuleError.Of(RuleEngineCodes.UpstreamError));
            if (rv.Value is null) missing.Add((JsonNode?)JsonValue.Create(k));
        }
        return missing;
    }

    internal static JsonNode EvalMissingSome(List<JsonNode?> args, EvalContext ctx)
    {
        int min = (int)ToNumber(Eval(args, 0, ctx));
        var keysNode = Eval(args, 1, ctx);
        var keys = keysNode is JsonArray a ? a.Select(x => AsString(x) ?? "").ToList() : new List<string>();
        var missing = new JsonArray();
        int present = 0;
        foreach (var k in keys)
        {
            var rv = ctx.Resolver.ResolveVar(k);
            if (rv.State == ValueState.Pending) throw new RulePendingException();
            if (rv.State == ValueState.Error) throw new RuleEvalException(rv.Error ?? RuleError.Of(RuleEngineCodes.UpstreamError));
            if (rv.Value is null) missing.Add((JsonNode?)JsonValue.Create(k));
            else present++;
        }
        return present >= min ? new JsonArray() : missing;
    }

    // ── logic ───────────────────────────────────────────────────────────────

    internal static JsonNode? EvalAnd(List<JsonNode?> args, EvalContext ctx)
    {
        JsonNode? last = JsonValue.Create(true);
        foreach (var a in args)
        {
            last = Evaluate(a, ctx);
            if (!IsTruthy(last)) return last;
        }
        return last;
    }

    internal static JsonNode? EvalOr(List<JsonNode?> args, EvalContext ctx)
    {
        JsonNode? last = JsonValue.Create(false);
        foreach (var a in args)
        {
            last = Evaluate(a, ctx);
            if (IsTruthy(last)) return last;
        }
        return last;
    }

    internal static JsonNode? EvalIf(List<JsonNode?> args, EvalContext ctx)
    {
        int i = 0;
        for (; i + 1 < args.Count; i += 2)
        {
            if (IsTruthy(Evaluate(args[i], ctx))) return Evaluate(args[i + 1], ctx);
        }
        return i < args.Count ? Evaluate(args[i], ctx) : null;
    }

    // ── compare / arithmetic ────────────────────────────────────────────────

    internal static int Compare(List<JsonNode?> args, EvalContext ctx)
    {
        double a = ToNumber(Eval(args, 0, ctx));
        double b = ToNumber(Eval(args, 1, ctx));
        // Relational order (matches the TS tier's `<`/`>`), NOT double.CompareTo's total
        // order — so a literal -0.0 compares EQUAL to +0.0 on both tiers (finding F6).
        return a < b ? -1 : a > b ? 1 : 0;
    }

    internal static JsonNode Arith(List<JsonNode?> args, EvalContext ctx, char op)
    {
        var values = args.Select(a => Evaluate(a, ctx)).ToList();

        // Unary minus: {"-":[x]} => -x ; unary plus passes through numeric.
        if (op == '-' && values.Count == 1) return NumNode(-ToNumber(values[0]));
        if (op == '+' && values.Count == 1) return NumNode(ToNumber(values[0]));

        if (values.Count == 0) throw new RuleEvalException(RuleError.Of(RuleEngineCodes.TypeError, "op", op.ToString()));

        double acc = ToNumber(values[0]);
        for (int i = 1; i < values.Count; i++)
        {
            double v = ToNumber(values[i]);
            switch (op)
            {
                case '+': acc += v; break;
                case '-': acc -= v; break;
                case '*': acc *= v; break;
                case '/':
                    if (v == 0) throw new RuleEvalException(RuleError.Of(RuleEngineCodes.DivByZero));
                    acc /= v;
                    break;
                case '%':
                    if (v == 0) throw new RuleEvalException(RuleError.Of(RuleEngineCodes.DivByZero));
                    acc %= v;
                    break;
            }
        }
        return NumNode(acc);
    }

    internal static JsonNode MinMax(List<JsonNode?> args, EvalContext ctx, bool min)
    {
        if (args.Count == 0) throw new RuleEvalException(RuleError.Of(RuleEngineCodes.TypeError, "op", min ? "min" : "max"));
        double best = ToNumber(Eval(args, 0, ctx));
        for (int i = 1; i < args.Count; i++)
        {
            double v = ToNumber(Eval(args, i, ctx));
            best = min ? Math.Min(best, v) : Math.Max(best, v);
        }
        return NumNode(best);
    }

    // ── membership / string ─────────────────────────────────────────────────

    internal static JsonNode EvalIn(List<JsonNode?> args, EvalContext ctx)
    {
        var needle = Eval(args, 0, ctx);
        var hay = Eval(args, 1, ctx);
        if (hay is JsonArray arr) return Bool(arr.Any(x => LooseEquals(x, needle)));
        // Substring membership only for a REAL string haystack (matches the TS tier's
        // `typeof hay === 'string'`); a non-string scalar haystack is never a member (finding F5).
        if (hay is JsonValue hv && hv.TryGetValue<string>(out var hs))
        {
            var n = AsString(needle);
            return Bool(n is not null && hs.Contains(n, StringComparison.Ordinal));
        }
        return Bool(false);
    }

    internal static JsonNode EvalCat(List<JsonNode?> args, EvalContext ctx)
    {
        var sb = new StringBuilder();
        foreach (var a in args)
        {
            var piece = AsString(Evaluate(a, ctx)) ?? "";
            ctx.Budget.ChargeSize(piece.Length); // charge concat work proportional to size (finding F4)
            sb.Append(piece);
        }
        return JsonValue.Create(sb.ToString());
    }

    // ── earlier source extensions ─────────────────────────────────────────────────

    internal static JsonNode? EvalAgg(List<JsonNode?> args, EvalContext ctx)
    {
        string fn = AsString(Eval(args, 0, ctx)) ?? throw BadAgg();
        string section = AsString(Eval(args, 1, ctx)) ?? throw BadAgg();
        string col = AsString(Eval(args, 2, ctx)) ?? throw BadAgg();
        return Unwrap(ctx.Resolver.ResolveAgg(fn, section, col), null);
    }

    internal static RuleEvalException BadAgg() => new(RuleError.Of(RuleEngineCodes.BadReference, "op", "agg"));

    internal static JsonNode Money(List<JsonNode?> args, EvalContext ctx, char op)
    {
        try
        {
            var values = args.Select(a => Evaluate(a, ctx)).ToList();
            if (values.Count == 0) throw new RuleEvalException(RuleError.Of(RuleEngineCodes.TypeError, "op", "money"));
            var acc = ToMoney(values[0]);
            ctx.Budget.ChargeSize(acc.Size); // charge money work proportional to operand size (finding F4)
            for (int i = 1; i < values.Count; i++)
            {
                var m = ToMoney(values[i]);
                ctx.Budget.ChargeSize(m.Size);
                acc = op switch { '+' => acc + m, '-' => acc - m, '*' => acc * m, _ => acc };
                ctx.Budget.ChargeSize(acc.Size);
            }
            return JsonValue.Create(acc.ToCanonicalString());
        }
        catch (FormatException)
        {
            throw new RuleEvalException(RuleError.Of(RuleEngineCodes.TypeError, "op", "money"));
        }
    }

    internal static MoneyDecimal ToMoney(JsonNode? n)
    {
        if (n is JsonValue v)
        {
            if (v.TryGetValue<string>(out var s)) return MoneyDecimal.Parse(s);
            if (v.TryGetValue<long>(out var l)) return MoneyDecimal.FromInteger(l);
            if (v.TryGetValue<int>(out var iv)) return MoneyDecimal.FromInteger(iv);
            // Reject non-integer JSON numbers: float parsing cannot recover exact decimal cross-tier.
            if (v.TryGetValue<double>(out var d) && d == Math.Floor(d) && Math.Abs(d) < 9.007e15)
                return MoneyDecimal.FromInteger((long)d);
        }
        throw new FormatException("money operand must be a decimal string or an integer");
    }

    internal static JsonNode DateAdd(List<JsonNode?> args, EvalContext ctx)
    {
        try
        {
            string date = AsString(Eval(args, 0, ctx)) ?? throw new FormatException("date");
            long n = (long)ToNumber(Eval(args, 1, ctx));
            string unit = AsString(Eval(args, 2, ctx)) ?? "day";
            return JsonValue.Create(DateMath.Add(date, n, unit));
        }
        catch (FormatException)
        {
            throw new RuleEvalException(RuleError.Of(RuleEngineCodes.TypeError, "op", "date.add"));
        }
    }

    internal static JsonNode DateDiff(List<JsonNode?> args, EvalContext ctx)
    {
        try
        {
            string a = AsString(Eval(args, 0, ctx)) ?? throw new FormatException("date");
            string b = AsString(Eval(args, 1, ctx)) ?? throw new FormatException("date");
            return JsonValue.Create(DateMath.DiffDays(a, b));
        }
        catch (FormatException)
        {
            throw new RuleEvalException(RuleError.Of(RuleEngineCodes.TypeError, "op", "date.diff"));
        }
    }

    /// <summary>
    /// <c>coding.is(value, system, code)</c> — taxonomy membership over a coding value
    /// shaped <c>{"system":...,"code":...}</c> (or an array of such). Decoupled from a
    /// concrete domain type (ADR 0056 <c>TaxonomyClassification</c>) to keep the engine
    /// foundation-light; the form/workflow layer maps its concept to this shape.
    /// </summary>
    internal static JsonNode EvalCodingIs(List<JsonNode?> args, EvalContext ctx)
    {
        var value = Eval(args, 0, ctx);
        string system = AsString(Eval(args, 1, ctx)) ?? "";
        string code = AsString(Eval(args, 2, ctx)) ?? "";
        bool Match(JsonNode? c) =>
            c is JsonObject o
            && AsString(o.TryGetPropertyValue("system", out var s) ? s : null) == system
            && AsString(o.TryGetPropertyValue("code", out var cd) ? cd : null) == code;

        if (value is JsonArray arr) return Bool(arr.Any(Match));
        return Bool(Match(value));
    }

    // ── coercion helpers ────────────────────────────────────────────────────

    internal static bool IsTruthy(JsonNode? n)
    {
        switch (n)
        {
            case null: return false;
            case JsonArray a: return a.Count > 0;
            case JsonObject o: return o.Count > 0;
            case JsonValue v:
                if (v.TryGetValue<bool>(out var b)) return b;
                if (v.TryGetValue<string>(out var s)) return s.Length > 0;
                if (TryDouble(v, out var d)) return d != 0;
                return true;
            default: return true;
        }
    }

    internal static double ToNumber(JsonNode? n)
    {
        switch (n)
        {
            case null: throw new RuleEvalException(RuleError.Of(RuleEngineCodes.TypeError, "reason", "null-as-number"));
            case JsonValue v:
                if (TryDouble(v, out var d)) return d;
                if (v.TryGetValue<bool>(out var b)) return b ? 1 : 0;
                if (v.TryGetValue<string>(out var s) && JsNumber.TryParse(s, out var sd)) return sd;
                throw new RuleEvalException(RuleError.Of(RuleEngineCodes.TypeError, "reason", "not-a-number"));
            default:
                throw new RuleEvalException(RuleError.Of(RuleEngineCodes.TypeError, "reason", "not-a-number"));
        }
    }

    internal static bool TryDouble(JsonValue v, out double d)
    {
        if (v.TryGetValue<double>(out d)) return true;
        if (v.TryGetValue<long>(out var l)) { d = l; return true; }
        if (v.TryGetValue<int>(out var i)) { d = i; return true; }
        if (v.TryGetValue<decimal>(out var m)) { d = (double)m; return true; }
        d = 0;
        return false;
    }

    internal static JsonNode NumNode(double d)
    {
        if (!double.IsFinite(d)) throw new RuleEvalException(RuleError.Of(RuleEngineCodes.TypeError, "reason", "non-finite"));
        if (d == Math.Floor(d) && Math.Abs(d) < 9.007e15) return JsonValue.Create((long)d);
        return JsonValue.Create(d);
    }

    internal static string? AsString(JsonNode? n)
    {
        if (n is JsonValue v)
        {
            if (v.TryGetValue<string>(out var s)) return s;
            if (v.TryGetValue<bool>(out var b)) return b ? "true" : "false";
            if (v.TryGetValue<long>(out var l)) return CanonicalNumber.ToJsonString(l);
            if (v.TryGetValue<int>(out var iv)) return CanonicalNumber.ToJsonString((long)iv);
            if (v.TryGetValue<double>(out var d)) return CanonicalNumber.ToJsonString(d);
        }
        return n?.ToJsonString();
    }

    internal static bool StrictEquals(JsonNode? a, JsonNode? b)
    {
        if (a is null || b is null) return a is null && b is null;
        if (a is JsonValue va && b is JsonValue vb)
        {
            bool an = TryDouble(va, out var ad), bn = TryDouble(vb, out var bd);
            if (an && bn) return ad == bd;
            if (an != bn) return false;
            if (va.TryGetValue<bool>(out var ab) && vb.TryGetValue<bool>(out var bb)) return ab == bb;
            if (va.TryGetValue<bool>(out _) != vb.TryGetValue<bool>(out _)) return false;
            return AsString(va) == AsString(vb);
        }
        return a.ToJsonString() == b.ToJsonString();
    }

    internal static bool LooseEquals(JsonNode? a, JsonNode? b)
    {
        if (a is null || b is null) return a is null && b is null;
        if (a is JsonValue va && b is JsonValue vb)
        {
            if (TryDouble(va, out var ad) && TryDouble(vb, out var bd)) return ad == bd;
            // Numeric coercion across number/string/bool.
            bool aCoerce = TryCoerceNumber(va, out var an);
            bool bCoerce = TryCoerceNumber(vb, out var bn);
            if (aCoerce && bCoerce) return an == bn;
            return AsString(va) == AsString(vb);
        }
        return a.ToJsonString() == b.ToJsonString();
    }

    internal static bool TryCoerceNumber(JsonValue v, out double d)
    {
        if (TryDouble(v, out d)) return true;
        if (v.TryGetValue<bool>(out var b)) { d = b ? 1 : 0; return true; }
        if (v.TryGetValue<string>(out var s) && JsNumber.TryParse(s, out d)) return true;
        d = 0;
        return false;
    }
}

using System.Globalization;
using System.Numerics;

namespace Harborline.Foundation.RuleEngine.Evaluation;

/// <summary>
/// Exact fixed-point decimal arithmetic for the <c>money.*</c> operators
/// (SPINE-1 design §1.4). Implemented over <see cref="BigInteger"/> mantissa +
/// base-10 scale — NOT IEEE-754 — so money math is decimal-correct and the
/// canonical string form is <b>byte-identical</b> to the TS tier's
/// <c>BigInt</c>-based port (the conformance corpus pins this).
/// </summary>
/// <remarks>
/// Operands are decimal <b>strings</b> (or integers); a non-integer JSON number
/// operand is rejected (<see cref="FormatException"/>) because JSON float parsing
/// cannot recover the exact decimal cross-tier. The canonical result trims
/// trailing fractional zeros and the trailing point, normalizing <c>-0</c> to
/// <c>0</c>.
/// </remarks>
internal readonly struct MoneyDecimal
{
    private readonly BigInteger _mantissa;
    private readonly int _scale; // value = _mantissa * 10^-_scale ; _scale >= 0

    /// <summary>Runtime bound on mantissa significant digits + scale (finding F4): a single
    /// large/super-linear money op (BigInteger multiply / <c>BigInteger.Pow</c> alignment) over a
    /// crafted or instance-supplied operand fails closed before it can run uncharged. Both tiers
    /// share the identical constant so the bound is cross-tier-deterministic.</summary>
    private const int MaxSignificantDigits = 4096;

    /// <summary>Count of significant digits in the mantissa (the BigInteger work-size proxy).</summary>
    internal int Size => _mantissa.IsZero ? 1 : BigInteger.Abs(_mantissa).ToString(CultureInfo.InvariantCulture).Length;

    private MoneyDecimal(BigInteger mantissa, int scale)
    {
        _mantissa = mantissa;
        _scale = scale;
    }

    /// <summary>Parses an exact decimal from its string form (e.g. "10", "-3.50", "0.005").</summary>
    public static MoneyDecimal Parse(string text)
    {
        if (string.IsNullOrEmpty(text)) throw new FormatException("empty money literal");
        var s = text.Trim();
        if (s.Length == 0) throw new FormatException("empty money literal");
        bool neg = false;
        int i = 0;
        if (s[0] == '+' || s[0] == '-') { neg = s[0] == '-'; i = 1; }

        var digits = new System.Text.StringBuilder();
        int scale = 0;
        bool seenDot = false;
        bool any = false;
        for (; i < s.Length; i++)
        {
            char c = s[i];
            if (c == '.')
            {
                if (seenDot) throw new FormatException("multiple decimal points");
                seenDot = true;
                continue;
            }
            if (c < '0' || c > '9') throw new FormatException($"invalid money literal '{text}'");
            digits.Append(c);
            any = true;
            if (seenDot) scale++;
        }
        if (!any) throw new FormatException($"invalid money literal '{text}'");
        if (digits.Length > MaxSignificantDigits)
            throw new FormatException($"money literal exceeds {MaxSignificantDigits} significant digits");

        var mantissa = BigInteger.Parse(digits.Length == 0 ? "0" : digits.ToString(), CultureInfo.InvariantCulture);
        if (neg) mantissa = -mantissa;
        return new MoneyDecimal(mantissa, scale);
    }

    /// <summary>Parses an exact decimal from an integer.</summary>
    public static MoneyDecimal FromInteger(long value) => new(new BigInteger(value), 0);

    private static (BigInteger A, BigInteger B, int Scale) Align(MoneyDecimal a, MoneyDecimal b)
    {
        int scale = Math.Max(a._scale, b._scale);
        if (scale - a._scale > MaxSignificantDigits || scale - b._scale > MaxSignificantDigits)
            throw new FormatException("money alignment exceeds the size bound");
        var am = a._mantissa * BigInteger.Pow(10, scale - a._scale);
        var bm = b._mantissa * BigInteger.Pow(10, scale - b._scale);
        return (am, bm, scale);
    }

    public static MoneyDecimal operator +(MoneyDecimal a, MoneyDecimal b)
    {
        var (am, bm, scale) = Align(a, b);
        return new MoneyDecimal(am + bm, scale);
    }

    public static MoneyDecimal operator -(MoneyDecimal a, MoneyDecimal b)
    {
        var (am, bm, scale) = Align(a, b);
        return new MoneyDecimal(am - bm, scale);
    }

    public static MoneyDecimal operator *(MoneyDecimal a, MoneyDecimal b)
    {
        if (a.Size + b.Size > MaxSignificantDigits || a._scale + b._scale > MaxSignificantDigits)
            throw new FormatException("money multiplication exceeds the size bound");
        return new(a._mantissa * b._mantissa, a._scale + b._scale);
    }

    /// <summary>Exact decimal ordering (aligned mantissa compare) — for decimal <c>min</c>/<c>max</c>
    /// aggregates over a money column (finding F7).</summary>
    public int Compare(MoneyDecimal o)
    {
        var (am, bm, _) = Align(this, o);
        return am.CompareTo(bm);
    }

    /// <summary>The canonical, cross-tier-identical decimal string (trailing zeros trimmed).</summary>
    public string ToCanonicalString()
    {
        if (_mantissa.IsZero) return "0";
        bool neg = _mantissa.Sign < 0;
        string digits = BigInteger.Abs(_mantissa).ToString(CultureInfo.InvariantCulture);

        if (_scale == 0)
        {
            return neg ? "-" + digits : digits;
        }

        if (digits.Length <= _scale)
        {
            digits = new string('0', _scale - digits.Length + 1) + digits;
        }
        int dot = digits.Length - _scale;
        string intPart = digits[..dot];
        string fracPart = digits[dot..].TrimEnd('0');
        string body = fracPart.Length == 0 ? intPart : intPart + "." + fracPart;
        return neg && body != "0" ? "-" + body : body;
    }
}

using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Compilation;
using Harborline.Foundation.RuleEngine.Context;
using Harborline.Foundation.RuleEngine.Environments;
using Harborline.Foundation.RuleEngine.Evaluation;
using Harborline.Foundation.RuleEngine.Graph;
using Harborline.Foundation.RuleEngine.Model;


namespace Harborline.Foundation.RuleEngine;

/// <summary>Resolves <c>field.</c> references against a flat workflow context bag (no tables).</summary>
internal sealed class ContextBagResolver : IValueResolver
{
    private readonly IReadOnlyDictionary<string, JsonNode?> _bag;

    public ContextBagResolver(IReadOnlyDictionary<string, JsonNode?> bag) => _bag = bag;

    public RefValue ResolveVar(string path)
    {
        // row. references are not addressable in a flat guard context.
        if (path.StartsWith("row.", StringComparison.Ordinal))
        {
            return RefValue.OfError(RuleError.Of(RuleEngineCodes.BadReference, "path", path));
        }
        // "field.x" and a bare "x" both address the context bag.
        string name = path.StartsWith("field.", StringComparison.Ordinal) ? path["field.".Length..] : path;
        if (_bag.TryGetValue(name, out var v))
        {
            return PendingSentinel.Is(v) ? RefValue.Pending : RefValue.Resolved(v);
        }
        return RefValue.Resolved(null);
    }

    // A flat context bag carries no tables: every aggregate is unavailable data (ticket 162's
    // one shared refusal shape — the corpus pins its params across tiers).
    public RefValue ResolveAgg(string fn, string section, string col)
        => RefValue.UnavailableAggregate(fn, section, col);
}

/// <summary>The atom (SPINE-1 design §5.2): evaluate one compiled rule against a resolver.</summary>
internal sealed class RuleEvaluator : IRuleEvaluator
{
    /// <inheritdoc />
    public RuleOutcome Evaluate(CompiledRule rule, CellAddress target, string ruleKey,
        IValueResolver resolver, DateTimeOffset now, RuleEngineLimits limits, CancellationToken ct)
    {
        using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
        cts.CancelAfter(limits.WallClockCeiling);
        var ctx = new EvalContext(resolver, now, new EvalBudget(limits, cts.Token));
        try
        {
            return OutcomeBuilder.Build(rule, target, resolver, ctx).Outcome;
        }
        catch (RuleBudgetException) { return FailClosed(rule, target, RuleEngineCodes.BudgetExceeded); }
        // RuleEngineTimeoutException propagates (non-authoritative liveness fault; D1 ratification).
    }

    internal static RuleOutcome FailClosed(CompiledRule rule, CellAddress target, string code) => rule.OutputType switch
    {
        OutputType.Value => RuleOutcome.OfValue(rule.Source.Id, target, ComputedValue.OfError(RuleError.Of(code))),
        OutputType.Validity => RuleOutcome.OfValidity(rule.Source.Id, target, Validity.Invalid(RuleError.Of(code))),
        OutputType.Visibility => RuleOutcome.OfVisibility(rule.Source.Id, target, new VisibilityState(Visible: false)),
        // Fail-closed options is the empty list — a choice field falls back to no dynamic options.
        OutputType.Options => RuleOutcome.OfOptions(rule.Source.Id, target, OptionsOutcome.OfError(RuleError.Of(code))),
        _ => RuleOutcome.OfPresentation(rule.Source.Id, target, new PresentationOutcome(Severity.Error)),
    };
}

/// <summary>
/// The workflow orchestrator (SPINE-1 design §5.4): evaluate a transition guard /
/// action condition (a one-node graph) over a flat context bag. Server-side +
/// fail-closed — a pending/errored guard does not let a transition fire.
/// </summary>
public sealed class GuardEvaluator : IGuardEvaluator
{
    private readonly RuleEngineLimits _limits;
    private readonly TimeProvider _clock;

    /// <summary>Creates an evaluator reading time from <paramref name="clock"/>, bounded by <paramref name="limits"/> or <see cref="RuleEngineLimits.Default"/>.</summary>
    public GuardEvaluator(TimeProvider clock, RuleEngineLimits? limits = null)
    {
        _limits = limits ?? RuleEngineLimits.Default;
        _clock = clock ?? throw new ArgumentNullException(nameof(clock));
    }

    /// <summary>
    /// Refuses an uncaptured dictionary without enumerating it. Host code must explicitly capture
    /// data before calling the snapshot overload; this method remains only to give existing binary
    /// consumers a deterministic refusal instead of a hidden callback-capable capture.
    /// </summary>
    public Validity EvaluateGuard(RuleDefinition rule, IReadOnlyDictionary<string, JsonNode?> context, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(rule);
        ArgumentNullException.ThrowIfNull(context);
        return Validity.Invalid(RuleError.Of(RuleEngineCodes.ContextSnapshotRequired));
    }

    /// <summary>Evaluates only data captured into the runtime-owned inert snapshot contract.</summary>
    public Validity EvaluateGuard(RuleDefinition rule, RuleContextSnapshot context, RuleEvalScope scope, EvaluationAdmission? admission, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(rule);
        ArgumentNullException.ThrowIfNull(context);
        CompiledGraph compiled;
        // T-687: a rule that does not compile is a withheld guard carrying the compile code, like an
        // evaluation fault, so callers need not hand-roll the fail-closed guarantee. The message
        // (which can quote the expression) stays out of the result.
        try { compiled = RuleCompiler.Compile(new[] { rule }, _limits); }
        catch (RuleCompilationException ex) { return Validity.Invalid(RuleError.Of(ex.Code)); }
        // rules-eng-26: evaluation needs admission evidence; the check runs before any value is read.
        if (BorrowerEnvironmentAdmission.Check(admission, compiled) is { } refusal) return Validity.Invalid(RuleError.Of(refusal));
        if (compiled.RuleCount == 0) return Validity.Valid;
        var cr = compiled.Rules[0];
        return Run(cr, context.CreateResolver(scope), ct,
            onValue: v => HarborlineJsonLogic.IsTruthy(v) ? Validity.Valid : Validity.Invalid(RuleError.Of(rule.Id)),
            onError: e => Validity.Invalid(e),
            onPending: () => Validity.Invalid(RuleError.Of(RuleEngineCodes.PendingAtSave)),
            onAbort: code => Validity.Invalid(RuleError.Of(code, "rule", rule.Id)));
    }

    /// <summary>
    /// Evaluates a guard rule (a <c>Validate</c>-shaped boolean) against ANY pillar's context adapter
    /// (ADR 0146 D3), resolving <c>var</c>/<c>agg</c>/<c>row.</c> references at <paramref name="scope"/>.
    /// The bag overload is the special case <c>ContextBagAdapter + Root</c>; the documents pillar (#111)
    /// evaluates a template block guard through its <c>DocumentMergeContextAdapter</c> at ROOT_SCOPE (a
    /// header/footer condition) or a row scope (a per-line-item condition) with this overload — the
    /// seam completion the D3 remarks anticipate for the three new adapters. Fail-closed: a pending /
    /// errored / budget-aborted guard is <see cref="Validity.Invalid(RuleError)"/> (never lets a gated
    /// block render on an ambiguous verdict).
    /// </summary>
    public Validity EvaluateGuard(RuleDefinition rule, IContextAdapter adapter, RuleEvalScope scope, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(rule);
        ArgumentNullException.ThrowIfNull(adapter);
        // Do not call CreateResolver: an adapter is arbitrary host code. Capturers must turn
        // source data into RuleContextSnapshot before crossing this evaluator boundary.
        return Validity.Invalid(RuleError.Of(RuleEngineCodes.ContextSnapshotRequired));
    }

    /// <summary>Refuses an uncaptured dictionary without reading it; use the snapshot overload.</summary>
    public ComputedValue EvaluateValue(RuleDefinition rule, IReadOnlyDictionary<string, JsonNode?> context, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(rule);
        ArgumentNullException.ThrowIfNull(context);
        return ComputedValue.OfError(RuleError.Of(RuleEngineCodes.ContextSnapshotRequired));
    }

    /// <summary>Evaluates a value against an inert captured snapshot.</summary>
    public ComputedValue EvaluateValue(RuleDefinition rule, RuleContextSnapshot context, RuleEvalScope scope, EvaluationAdmission? admission, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(rule);
        ArgumentNullException.ThrowIfNull(context);
        CompiledGraph compiled;
        // T-739: a rule that does not compile is an errored computed value carrying the compile
        // code, like an evaluation fault, so callers need not hand-roll the fail-closed guarantee.
        // The message (which can quote the expression) stays out of the result.
        try { compiled = RuleCompiler.Compile(new[] { rule }, _limits); }
        catch (RuleCompilationException ex) { return ComputedValue.OfError(RuleError.Of(ex.Code)); }
        if (BorrowerEnvironmentAdmission.Check(admission, compiled) is { } refusal) return ComputedValue.OfError(RuleError.Of(refusal));
        if (compiled.RuleCount == 0) return ComputedValue.Resolved(null);
        return Run(compiled.Rules[0], context.CreateResolver(scope), ct,
            onValue: ComputedValue.Resolved, onError: ComputedValue.OfError,
            onPending: ComputedValue.OfPending, onAbort: code => ComputedValue.OfError(RuleError.Of(code, "rule", rule.Id)));
    }

    /// <summary>
    /// Evaluates a value expression (a <c>Compute</c>-shaped rule) against ANY pillar's context adapter
    /// (ADR 0146 D3) at <paramref name="scope"/> — the adapter-based companion to the bag overload. The
    /// documents pillar (#111) resolves a computed merge value (a named-Rule or inline compute) through
    /// its <c>DocumentMergeContextAdapter</c> with this; plain merge fields ask the resolver directly.
    /// </summary>
    public ComputedValue EvaluateValue(RuleDefinition rule, IContextAdapter adapter, RuleEvalScope scope, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(rule);
        ArgumentNullException.ThrowIfNull(adapter);
        return ComputedValue.OfError(RuleError.Of(RuleEngineCodes.ContextSnapshotRequired));
    }

    private T Run<T>(CompiledRule cr, IValueResolver resolver, CancellationToken ct,
        Func<JsonNode?, T> onValue, Func<RuleError, T> onError, Func<T> onPending, Func<string, T> onAbort)
    {
        using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
        cts.CancelAfter(_limits.WallClockCeiling);
        var ctx = new EvalContext(resolver, _clock.GetUtcNow(), new EvalBudget(_limits, cts.Token));
        try { return onValue(HarborlineJsonLogic.Evaluate(cr.Ast, ctx)); }
        catch (RuleEvalException ex) { return onError(ex.Error); }
        catch (RulePendingException) { return onPending(); }
        catch (RuleBudgetException) { return onAbort(RuleEngineCodes.BudgetExceeded); }
        // RuleEngineTimeoutException propagates (non-authoritative liveness fault; D1 ratification):
        // a guard that hits the wall-clock is an infrastructure fault, not a transition verdict.
    }
}

using System.Text;

using Harborline.Foundation.RuleEngine.Compilation;
using Harborline.Foundation.RuleEngine.Model;
using Harborline.Foundation.RuleEngine.Skins;


namespace Harborline.Foundation.RuleEngine.Explain;

// ─────────────────────────────────────────────────────────────────────────────
//  ADR 0146 D10 — interactive explainability traces (the Pilot "why is this field
//  hidden? / why did this route to a director?" substrate; the design constitution's
//  cognitive-accessibility respect).
//
//  A trace is a list of localizable CODE + PARAM entries (the ADR 0055
//  validation-codes doctrine — never embedded English). Every interactive / CP-gated
//  evaluation can carry one; per-row batch/streaming paths run traceless (they simply
//  do not build a trace) with a sampling hook (the sampler builds a trace on a sample,
//  identical shape).
//
//  Board F2 (BINDING) — the value-leak seam is closed BY CONSTRUCTION:
//    A trace is a pure projection over (a) the compiled rules' STATIC field references
//    (names) + (b) the built RuleOutcome (a code). It has NO access to a resolved
//    RefValue — the now-public IValueResolver/RefValue seam (slice 2) is never touched
//    here — so a field VALUE can never enter a trace param. The AUTHORITY FILTER then
//    gates the field REFERENCES: a shredded subject's refs darken to a reference+hash
//    form, and a viewer-unreadable field's ref redacts. Explainability is never a PBAC
//    or crypto-shred bypass.
// ─────────────────────────────────────────────────────────────────────────────

/// <summary>Stable, locale-independent trace codes (ADR 0146 D10). Byte-identical to the TS
/// <c>RuleTraceCodes</c>. The client keys a localized template off the code; params interpolate.</summary>
public static class RuleTraceCodes
{
    /// <summary>A compute rule produced a value.</summary>
    public const string ValueComputed = "rule.trace.value_computed";
    /// <summary>A compute rule produced a coded error; <c>cause</c> names it.</summary>
    public const string ValueError = "rule.trace.value_error";
    /// <summary>A rule could not settle because an input is pending.</summary>
    public const string Pending = "rule.trace.pending";
    /// <summary>A validation rule passed.</summary>
    public const string ValidationPassed = "rule.trace.validation_passed";
    /// <summary>A validation rule failed; <c>cause</c> names the error.</summary>
    public const string ValidationFailed = "rule.trace.validation_failed";
    /// <summary>A visibility rule showed its target.</summary>
    public const string Shown = "rule.trace.shown";
    /// <summary>A visibility rule hid its target.</summary>
    public const string Hidden = "rule.trace.hidden";
    /// <summary>A rule made its target required.</summary>
    public const string Required = "rule.trace.required";
    /// <summary>A rule left its target optional.</summary>
    public const string NotRequired = "rule.trace.not_required";
    /// <summary>A rule made its target read-only.</summary>
    public const string ReadOnly = "rule.trace.readonly";
    /// <summary>A rule left its target editable.</summary>
    public const string Editable = "rule.trace.editable";
    /// <summary>An options rule set its target's choices.</summary>
    public const string OptionsSet = "rule.trace.options_set";
    /// <summary>An options rule failed and its target falls back to no dynamic options.</summary>
    public const string OptionsError = "rule.trace.options_error";
    /// <summary>A presentation rule applied its presentation to the target.</summary>
    public const string Presented = "rule.trace.presented";
    /// <summary>A presentation rule did not apply.</summary>
    public const string NotPresented = "rule.trace.not_presented";
    /// <summary>A workflow guard passed, so its transition may fire.</summary>
    public const string GuardPassed = "rule.trace.guard_passed";
    /// <summary>A workflow guard failed, was pending or errored, so its transition may not fire.</summary>
    public const string GuardFailed = "rule.trace.guard_failed";
}

/// <summary>How a field reference appears in a trace (board F2). The filter decides; the builder renders.</summary>
public enum TraceFieldDisclosure
{
    /// <summary>The field reference is shown (the viewer may read it — the default).</summary>
    Show = 0,

    /// <summary>The field reference is redacted (the viewer is not authorized to read the field).</summary>
    Redact = 1,

    /// <summary>The field reference darkens to a reference+hash form (the data subject is crypto-shredded).</summary>
    Hash = 2,
}

/// <summary>
/// The authority filter that gates field references in a trace (board F2). Sees only field NAMES, never
/// values — it decides disclosure per field. A pillar supplies it from the viewing-principal / subject-key
/// context (the ADR 0146 D3 context-adapter is where that context is threaded). Default:
/// <see cref="PassThroughTraceFilter"/> (all fields shown — no authority context bound).
/// </summary>
public interface ITraceAuthorityFilter
{
    /// <summary>Decides how <paramref name="fieldName"/> appears in a trace param. NEVER receives a value.</summary>
    TraceFieldDisclosure Disclose(string fieldName);
}

/// <summary>The no-op filter — every field reference is shown. The default when no authority context is bound.</summary>
public sealed class PassThroughTraceFilter : ITraceAuthorityFilter
{
    /// <summary>The shared instance; the filter holds no state.</summary>
    public static PassThroughTraceFilter Instance { get; } = new();
    /// <inheritdoc />
    public TraceFieldDisclosure Disclose(string fieldName) => TraceFieldDisclosure.Show;
}

/// <summary>
/// One trace entry — a localizable code + params for one rule's outcome (ADR 0146 D10). Params are scalar
/// strings (the ADR 0055 convention): <c>rule</c> (the rule id), optional <c>reads</c> (the filtered field
/// references the rule read), and optional <c>cause</c> (an underlying error code for error/invalid outcomes).
/// A field VALUE never appears in <see cref="Params"/> — the builder cannot access one.
/// </summary>
public sealed record RuleTraceEntry(string RuleId, string Target, string Code, IReadOnlyDictionary<string, string> Params);

/// <summary>
/// Builds explainability traces as a pure projection over compiled rules + built outcomes (ADR 0146 D10 /
/// board F2). No evaluation, no resolver, no value access — structurally leak-free.
/// </summary>
public static class RuleTraceBuilder
{
    /// <summary>
    /// Builds the trace for a whole form evaluation — one entry per rule outcome. Call this on the
    /// interactive / CP-gated path; the batch path simply does not call it (traceless). The
    /// <paramref name="filter"/> gates each field reference; pass <see cref="PassThroughTraceFilter.Instance"/>
    /// when no authority context is bound.
    /// </summary>
    public static IReadOnlyList<RuleTraceEntry> BuildForm(
        CompiledGraph compiled, RuleEvaluationResult result, ITraceAuthorityFilter? filter = null)
        => BuildForm(compiled, result, filter, []);

    /// <summary>
    /// Builds the form trace naming, for every rule a decision table supplied, the table's declared hit policy
    /// (DES-0018 <c>rules-run-2</c>) as the <c>hitPolicy</c> param. The policy comes from the authored table,
    /// never from evaluation, so the trace stays a value-free projection.
    /// </summary>
    public static IReadOnlyList<RuleTraceEntry> BuildForm(
        CompiledGraph compiled, RuleEvaluationResult result, ITraceAuthorityFilter? filter, IReadOnlyCollection<DecisionTableSkin> tables)
    {
        ArgumentNullException.ThrowIfNull(tables);
        var policies = tables.ToDictionary(table => table.RuleId, table => table.HitPolicy, StringComparer.Ordinal);
        ArgumentNullException.ThrowIfNull(compiled);
        ArgumentNullException.ThrowIfNull(result);
        var f = filter ?? PassThroughTraceFilter.Instance;

        var rulesById = new Dictionary<string, CompiledRule>(StringComparer.Ordinal);
        foreach (var r in compiled.Rules) rulesById[r.Source.Id] = r;

        var entries = new List<RuleTraceEntry>();
        // Deterministic order (the ByRule dictionary order is not guaranteed): sort by rule key.
        foreach (var key in result.ByRule.Keys.OrderBy(k => k, StringComparer.Ordinal))
        {
            var outcome = result.ByRule[key];
            rulesById.TryGetValue(outcome.RuleId, out var rule);
            var entry = DescribeOutcome(key, outcome, rule, f);
            if (policies.TryGetValue(outcome.RuleId, out var policy))
                entry = entry with { Params = new Dictionary<string, string>(entry.Params, StringComparer.Ordinal) { ["hitPolicy"] = WireName(policy) } };
            entries.Add(entry);
        }
        return entries;
    }

    /// <summary>
    /// Builds a single trace entry for a workflow guard outcome (the <c>GuardEvaluator</c> arm). Re-derives
    /// the guard rule's field references from its definition (deterministic; the rule already compiled during
    /// evaluation). A compile failure degrades to an entry with no reads (never throws from the trace path).
    /// </summary>
    public static RuleTraceEntry BuildGuard(
        RuleDefinition rule, Validity outcome, ITraceAuthorityFilter? filter = null, RuleEngineLimits? limits = null)
    {
        ArgumentNullException.ThrowIfNull(rule);
        ArgumentNullException.ThrowIfNull(outcome);
        var f = filter ?? PassThroughTraceFilter.Instance;

        IReadOnlyList<string> reads = Array.Empty<string>();
        try
        {
            var compiled = RuleCompiler.Compile(new[] { rule }, limits ?? RuleEngineLimits.Default);
            if (compiled.Rules.Count > 0) reads = FieldRefsOf(compiled.Rules[0]);
        }
        catch (RuleCompilationException) { /* trace is best-effort — never throws */ }

        string code = outcome.Ok ? RuleTraceCodes.GuardPassed : RuleTraceCodes.GuardFailed;
        var p = BaseParams(rule.Id, reads, f);
        if (!outcome.Ok && outcome.Error is not null) p["cause"] = outcome.Error.Code;
        return new RuleTraceEntry(rule.Id, "guard:" + rule.Id, code, p);
    }

    private static RuleTraceEntry DescribeOutcome(string key, RuleOutcome outcome, CompiledRule? rule, ITraceAuthorityFilter f)
    {
        IReadOnlyList<string> reads = rule is not null ? FieldRefsOf(rule) : Array.Empty<string>();
        var p = BaseParams(outcome.RuleId, reads, f);

        string code;
        switch (outcome.OutputType)
        {
            case OutputType.Value:
                code = outcome.Value!.State switch
                {
                    ValueState.Resolved => RuleTraceCodes.ValueComputed,
                    ValueState.Pending => RuleTraceCodes.Pending,
                    _ => Cause(p, outcome.Value.Error, RuleTraceCodes.ValueError),
                };
                break;
            case OutputType.Validity:
                code = outcome.Validity!.Ok
                    ? RuleTraceCodes.ValidationPassed
                    : Cause(p, outcome.Validity.Error, RuleTraceCodes.ValidationFailed);
                break;
            case OutputType.Visibility:
                code = VisibilityCode(rule?.Source.Action ?? RuleActionKind.Visibility, outcome.Visibility!);
                break;
            case OutputType.Options:
                code = outcome.Options!.State switch
                {
                    ValueState.Resolved => RuleTraceCodes.OptionsSet,
                    ValueState.Pending => RuleTraceCodes.Pending,
                    _ => Cause(p, outcome.Options.Error, RuleTraceCodes.OptionsError),
                };
                break;
            default: // Presentation
                code = outcome.Presentation!.Severity is not null ? RuleTraceCodes.Presented : RuleTraceCodes.NotPresented;
                break;
        }
        return new RuleTraceEntry(outcome.RuleId, outcome.Target.Key, code, p);
    }

    // The authored wire form both tiers share (the conformance corpus spelling).
    private static string WireName(HitPolicy policy) => policy == HitPolicy.FirstMatch ? "first-match" : "priority";

    private static string VisibilityCode(RuleActionKind action, VisibilityState v) => action switch
    {
        RuleActionKind.Required => v.Required ? RuleTraceCodes.Required : RuleTraceCodes.NotRequired,
        RuleActionKind.ReadOnly => v.ReadOnly ? RuleTraceCodes.ReadOnly : RuleTraceCodes.Editable,
        _ => v.Visible ? RuleTraceCodes.Shown : RuleTraceCodes.Hidden,
    };

    private static string Cause(Dictionary<string, string> p, RuleError? error, string code)
    {
        if (error is not null) p["cause"] = error.Code;
        return code;
    }

    private static Dictionary<string, string> BaseParams(string ruleId, IReadOnlyList<string> reads, ITraceAuthorityFilter f)
    {
        var p = new Dictionary<string, string>(StringComparer.Ordinal) { ["rule"] = ruleId };
        if (reads.Count > 0)
        {
            // Field references are disclosed per the authority filter — the value-leak seam is already
            // closed (there is no value here); this darkens the REFERENCE for unreadable / shredded subjects.
            var disclosed = reads.Select(name => Render(name, f.Disclose(name)));
            p["reads"] = string.Join(",", disclosed);
        }
        return p;
    }

    private static string Render(string fieldName, TraceFieldDisclosure disclosure) => disclosure switch
    {
        TraceFieldDisclosure.Redact => "[redacted]",
        TraceFieldDisclosure.Hash => "#" + Fnv1a.Hash8(fieldName),
        _ => fieldName,
    };

    // The static field references a rule reads, in first-seen order, de-duplicated. Internal RuleRef
    // subtypes (same assembly) — extracts the readable field/column name.
    private static IReadOnlyList<string> FieldRefsOf(CompiledRule rule)
    {
        var seen = new List<string>();
        var set = new HashSet<string>(StringComparer.Ordinal);
        foreach (var rf in rule.References)
        {
            string? name = rf switch
            {
                FieldRef fr => fr.Name,
                RowFieldRef rr => rr.Field,
                AggRef ar => ar.Col,
                _ => null,
            };
            if (name is not null && set.Add(name)) seen.Add(name);
        }
        return seen;
    }
}

/// <summary>A tiny FNV-1a 32-bit hash — byte-identical to the TS tier — used only to darken a field
/// reference to an opaque, stable token for a crypto-shredded subject (board F2). Not a security primitive:
/// the subject's data is already destroyed; this only avoids echoing a bare field name in a shredded trace.</summary>
internal static class Fnv1a
{
    public static string Hash8(string s)
    {
        const uint offset = 2166136261;
        const uint prime = 16777619;
        uint h = offset;
        foreach (char c in s)
        {
            h ^= (byte)(c & 0xFF);
            h *= prime;
            h ^= (byte)((c >> 8) & 0xFF);
            h *= prime;
        }
        return h.ToString("x8");
    }
}

