using Harborline.Foundation.RuleEngine.Evaluation;

using L = Harborline.Foundation.RuleEngine.Evaluation.HarborlineJsonLogic;

namespace Harborline.Foundation.RuleEngine.Functions;

/// <summary>One executable built-in: its reference, its arity and its implementation.</summary>
public sealed class BuiltInFunctionDefinition
{
    internal BuiltInFunctionDefinition(string key, string category, int minArity, int maxArity, bool authorable,
        Func<List<JsonNode?>, EvalContext, JsonNode?> invoke)
    {
        Reference = new BuiltInFunction(key);
        Category = category;
        MinArity = minArity;
        MaxArity = maxArity;
        Authorable = authorable;
        Invoke = invoke;
    }

    /// <summary>The discriminated reference the register owns.</summary>
    public BuiltInFunction Reference { get; }

    /// <summary>The operator key.</summary>
    public string Key => Reference.Key;

    /// <summary>The palette group.</summary>
    public string Category { get; }

    /// <summary>Fewest arguments admitted.</summary>
    public int MinArity { get; }

    /// <summary>Most arguments admitted; -1 is unbounded.</summary>
    public int MaxArity { get; }

    /// <summary>False only for <c>var</c>, which authors reach through a declared reference.</summary>
    public bool Authorable { get; }

    internal Func<List<JsonNode?>, EvalContext, JsonNode?> Invoke { get; }

    internal bool Admits(int count) => count >= MinArity && (MaxArity < 0 || count <= MaxArity);
}

/// <summary>
/// The R1 function register (DES-0018 <c>rules-eng-27</c>): the single source of truth for the
/// executable built-ins. The evaluator dispatches through it, the compiler admits keys and arity from
/// it, and both editor lanes generate their function palette from it. Only the built-in arm of
/// <see cref="FunctionReference"/> is inhabited; every entry carries its implementation, so nothing is
/// registered that cannot execute. The package-provider arm is T-685.
/// </summary>
public static class BuiltInFunctionRegister
{
    /// <summary>The folds <c>agg</c> accepts over a bounded child collection (<c>rules-bound-4</c>).</summary>
    public static IReadOnlyList<string> AggregateFolds { get; } = ["sum", "count", "avg", "min", "max", "any", "all"];

    /// <summary>Every executable built-in, in palette order.</summary>
    public static IReadOnlyList<BuiltInFunctionDefinition> Functions { get; } =
    [
        Def("var", "data", 1, 2, L.EvalVar, authorable: false),
        Def("missing", "data", 0, -1, L.EvalMissing),
        Def("missing_some", "data", 2, 2, L.EvalMissingSome),

        Def("==", "logic", 2, 2, (a, c) => L.Bool(L.LooseEquals(L.Eval(a, 0, c), L.Eval(a, 1, c)))),
        Def("!=", "logic", 2, 2, (a, c) => L.Bool(!L.LooseEquals(L.Eval(a, 0, c), L.Eval(a, 1, c)))),
        Def("===", "logic", 2, 2, (a, c) => L.Bool(L.StrictEquals(L.Eval(a, 0, c), L.Eval(a, 1, c)))),
        Def("!==", "logic", 2, 2, (a, c) => L.Bool(!L.StrictEquals(L.Eval(a, 0, c), L.Eval(a, 1, c)))),
        Def("!", "logic", 1, 1, (a, c) => L.Bool(!L.IsTruthy(L.Eval(a, 0, c)))),
        Def("!!", "logic", 1, 1, (a, c) => L.Bool(L.IsTruthy(L.Eval(a, 0, c)))),
        Def("and", "logic", 0, -1, L.EvalAnd),
        Def("or", "logic", 0, -1, L.EvalOr),
        // A one-argument `if` is the decision-table skin's otherwise-only shape.
        Def("if", "logic", 0, -1, L.EvalIf),

        Def(">", "compare", 2, 2, (a, c) => L.Bool(L.Compare(a, c) > 0)),
        Def(">=", "compare", 2, 2, (a, c) => L.Bool(L.Compare(a, c) >= 0)),
        Def("<", "compare", 2, 2, (a, c) => L.Bool(L.Compare(a, c) < 0)),
        Def("<=", "compare", 2, 2, (a, c) => L.Bool(L.Compare(a, c) <= 0)),

        Def("+", "arithmetic", 1, -1, (a, c) => L.Arith(a, c, '+')),
        Def("-", "arithmetic", 1, -1, (a, c) => L.Arith(a, c, '-')),
        Def("*", "arithmetic", 1, -1, (a, c) => L.Arith(a, c, '*')),
        Def("/", "arithmetic", 1, -1, (a, c) => L.Arith(a, c, '/')),
        Def("%", "arithmetic", 1, -1, (a, c) => L.Arith(a, c, '%')),
        Def("min", "arithmetic", 1, -1, (a, c) => L.MinMax(a, c, min: true)),
        Def("max", "arithmetic", 1, -1, (a, c) => L.MinMax(a, c, min: false)),

        Def("in", "membership", 2, 2, L.EvalIn),
        Def("cat", "text", 0, -1, L.EvalCat),

        Def("agg", "fold", 3, 3, L.EvalAgg),
        Def("money.add", "money", 1, -1, (a, c) => L.Money(a, c, '+')),
        Def("money.sub", "money", 1, -1, (a, c) => L.Money(a, c, '-')),
        Def("money.mul", "money", 1, -1, (a, c) => L.Money(a, c, '*')),
        Def("date.add", "date", 3, 3, L.DateAdd),
        Def("date.diff", "date", 2, 2, L.DateDiff),
        Def("date.today", "date", 0, 0, (_, c) => JsonValue.Create(DateMath.Today(c.Now))),
        Def("coding.is", "coding", 3, 3, L.EvalCodingIs),
    ];

    private static readonly Dictionary<string, BuiltInFunctionDefinition> ByKey =
        Functions.ToDictionary(function => function.Key, StringComparer.Ordinal);

    /// <summary>Resolves a key to its single registered definition.</summary>
    public static bool TryResolve(string key, out BuiltInFunctionDefinition function)
        => ByKey.TryGetValue(key, out function!);

    /// <summary>Resolves a key to the register's one reference; throws when unregistered.</summary>
    public static BuiltInFunction Resolve(string key) => TryResolve(key, out var function)
        ? function.Reference
        : throw new FunctionReferenceException(FunctionReferenceCodec.UnknownBuiltIn, $"'{key}' is not a registered built-in");

    private static BuiltInFunctionDefinition Def(string key, string category, int min, int max,
        Func<List<JsonNode?>, EvalContext, JsonNode?> invoke, bool authorable = true)
        => new(key, category, min, max, authorable, invoke);
}

using System.Security.Cryptography;
using System.Text;
using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Environments;

namespace Harborline.Foundation.RuleEngine.Functions;

/// <summary>
/// A structurally discriminated function reference (DES-0018 <c>rules-ck-29</c>): exactly
/// <see cref="BuiltInFunction"/> or <see cref="PackageFunction"/>. The canonical form and the digest
/// carry the discriminant and the structured fields; <see cref="Display"/> is for people only and is
/// never parsed or hashed.
/// </summary>
public abstract record FunctionReference
{
    private protected FunctionReference() { }

    /// <summary>Sorted-key canonical JSON carrying the <c>kind</c> discriminant.</summary>
    public string CanonicalJson => Canonical().ToJsonString(BorrowerEnvironmentAdmission.CanonicalOptions);

    /// <summary>Lower-case hex SHA-256 of <see cref="CanonicalJson"/>.</summary>
    public string Digest => Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(CanonicalJson)));

    /// <summary>Human-readable form. Not a wire form: nothing parses or hashes it.</summary>
    public abstract string Display { get; }

    internal abstract JsonObject Canonical();
}

/// <summary>
/// The built-in arm. It has no public constructor: the only instances are the ones
/// <see cref="BuiltInFunctionRegister"/> holds, so package data cannot construct or shadow one.
/// </summary>
public sealed record BuiltInFunction : FunctionReference
{
    internal BuiltInFunction(string key) => Key = key;

    /// <summary>The register key, e.g. <c>money.add</c>.</summary>
    public string Key { get; }

    /// <inheritdoc />
    public override string Display => Key;

    internal override JsonObject Canonical() => new() { ["key"] = Key, ["kind"] = "builtin" };
}

/// <summary>
/// The package-provider arm. Modelled so the discriminant is real; R1 registers and executes no
/// package function (owner ruling 2026-09-21, T-685 owns the provider).
/// </summary>
public sealed record PackageFunction : FunctionReference
{
    /// <summary>Creates a package reference; <c>:</c> and empty values refuse.</summary>
    public PackageFunction(string packageId, string functionKey)
    {
        PackageId = FunctionReferenceCodec.Field(packageId);
        FunctionKey = FunctionReferenceCodec.Field(functionKey);
    }

    /// <summary>The exporting package.</summary>
    public string PackageId { get; }

    /// <summary>The function key inside that package.</summary>
    public string FunctionKey { get; }

    /// <inheritdoc />
    public override string Display => PackageId + "::" + FunctionKey;

    internal override JsonObject Canonical() => new() { ["functionKey"] = FunctionKey, ["kind"] = "package", ["packageId"] = PackageId };
}

/// <summary>A refused function reference, by stable code.</summary>
public sealed class FunctionReferenceException(string code, string message) : Exception(message)
{
    /// <summary>The stable refusal code.</summary>
    public string Code { get; } = code;
}

/// <summary>Reads the structured wire form of a <see cref="FunctionReference"/>.</summary>
public static class FunctionReferenceCodec
{
    /// <summary>A package payload tried to name the built-in arm.</summary>
    public const string BuiltInFromPackage = "rule.function.builtin_from_package";

    /// <summary>A structured field contains <c>:</c> or is empty.</summary>
    public const string ColonForbidden = "rule.function.field_invalid";

    /// <summary>The value is not a structured reference.</summary>
    public const string MalformedReference = "rule.function.malformed";

    /// <summary>The built-in key is not in the register.</summary>
    public const string UnknownBuiltIn = "rule.function.unknown_builtin";

    /// <summary>
    /// Reads a reference supplied by package data. Only the package arm can come out: a payload
    /// naming <c>builtin</c> refuses, whatever key it carries.
    /// </summary>
    public static PackageFunction ReadPackagePayload(JsonNode? node)
    {
        var obj = node as JsonObject ?? throw Malformed();
        if (Text(obj, "kind") == "builtin")
            throw new FunctionReferenceException(BuiltInFromPackage, "package data cannot construct a built-in function reference");
        return Read(obj) as PackageFunction ?? throw Malformed();
    }

    /// <summary>Reads a platform-authored reference. A built-in resolves only through the register.</summary>
    public static FunctionReference Read(JsonNode? node)
    {
        var obj = node as JsonObject ?? throw Malformed();
        return Text(obj, "kind") switch
        {
            "builtin" when obj.Count == 2 => BuiltInFunctionRegister.TryResolve(Text(obj, "key") ?? "", out var function)
                ? function.Reference
                : throw new FunctionReferenceException(UnknownBuiltIn, "the built-in key is not registered"),
            "package" when obj.Count == 3 => new PackageFunction(Text(obj, "packageId") ?? "", Text(obj, "functionKey") ?? ""),
            _ => throw Malformed(),
        };
    }

    internal static string Field(string value) => string.IsNullOrEmpty(value) || value.Contains(':')
        ? throw new FunctionReferenceException(ColonForbidden, "a function reference field must be non-empty and must not contain ':'")
        : value;

    private static string? Text(JsonObject obj, string name)
        => obj.TryGetPropertyValue(name, out var value) && value is JsonValue text && text.TryGetValue<string>(out var s) ? s : null;

    private static FunctionReferenceException Malformed() => new(MalformedReference, "a function reference must be the structured kind form");
}

using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Compilation;
using Harborline.Foundation.RuleEngine.Evaluation;
using Harborline.Foundation.RuleEngine.Model;


namespace Harborline.Foundation.RuleEngine.Graph;

/// <summary>The sentinel a corpus / async tier uses to mark an unresolved (Pending) value.</summary>
internal static class PendingSentinel
{
    public static bool Is(JsonNode? n) =>
        n is JsonObject o && o.Count == 1 && o.TryGetPropertyValue("@pending", out var v)
        && v is JsonValue jv && jv.TryGetValue<bool>(out var b) && b;
}

/// <summary>
/// Resolves a rule's <c>var</c>/<c>agg</c> references against already-evaluated
/// computed cells + the raw instance (SPINE-1 design §2.2). Error/Pending of an
/// upstream computed cell propagate to the dependent.
/// </summary>
internal sealed class CellResolver : IValueResolver
{
    private readonly IReadOnlyDictionary<string, ComputedValue> _computed;
    private readonly RuleInstance _instance;
    private readonly string? _rowSection;
    private readonly string? _rowId;

    public CellResolver(IReadOnlyDictionary<string, ComputedValue> computed, RuleInstance instance,
        string? rowSection = null, string? rowId = null)
    {
        _computed = computed;
        _instance = instance;
        _rowSection = rowSection;
        _rowId = rowId;
    }

    public RefValue ResolveVar(string path)
    {
        if (path.StartsWith("row.", StringComparison.Ordinal))
        {
            if (_rowSection is null || _rowId is null) return RefValue.OfError(RuleError.Of(RuleEngineCodes.BadReference, "path", path));
            string field = path["row.".Length..];
            string rkey = CellAddress.Row(_rowSection, _rowId, field).Key;
            if (_computed.TryGetValue(rkey, out var rcv)) return FromComputed(rcv, rkey);
            return RawRowField(_rowSection, _rowId, field);
        }
        // "field.x" and a bare "x" (e.g. a missing/missing_some key) both address a top-level field.
        string name = path.StartsWith("field.", StringComparison.Ordinal) ? path["field.".Length..] : path;
        string key = CellAddress.Field(name).Key;
        if (_computed.TryGetValue(key, out var cv)) return FromComputed(cv, key);
        return RawField(name);
    }

    public RefValue ResolveAgg(string fn, string section, string col)
    {
        string key = CellAddress.TableAggregate(section, fn, col).Key;
        // An aggregate the graph never computed is unavailable data, not a value (ticket 162):
        // resolving it to null fabricated a result the preview could not compute. Refuse with the
        // one shared bad-reference shape. Since the compiler now refuses agg nodes it cannot
        // statically register, every compiled agg has a fold cell — this branch is defense-in-depth.
        return _computed.TryGetValue(key, out var cv)
            ? FromComputed(cv, key)
            : RefValue.UnavailableAggregate(fn, section, col);
    }

    private RefValue RawField(string name)
    {
        if (_instance.Fields.TryGetValue(name, out var v))
        {
            return PendingSentinel.Is(v) ? RefValue.Pending : RefValue.Resolved(v);
        }
        return RefValue.Resolved(null);
    }

    private RefValue RawRowField(string section, string rowId, string field)
    {
        if (_instance.Tables.TryGetValue(section, out var rows))
        {
            var row = rows.FirstOrDefault(r => r.Id == rowId);
            if (row is not null && row.Fields.TryGetValue(field, out var v))
            {
                return PendingSentinel.Is(v) ? RefValue.Pending : RefValue.Resolved(v);
            }
        }
        return RefValue.Resolved(null);
    }

    private static RefValue FromComputed(ComputedValue cv, string key) => cv.State switch
    {
        ValueState.Resolved => RefValue.Resolved(cv.Value),
        ValueState.Pending => RefValue.Pending,
        _ => RefValue.OfError(RuleError.Of(RuleEngineCodes.UpstreamError, "cell", key)),
    };
}

/// <summary>Builds a single rule's <see cref="RuleOutcome"/> from its AST evaluation (SPINE-1 design §1.3).</summary>
internal static class OutcomeBuilder
{
    /// <summary>The result of building one outcome (carries whether it landed Pending, for the save gate).</summary>
    internal readonly record struct Built(RuleOutcome Outcome, bool Pending);

    public static Built Build(CompiledRule rule, CellAddress target, IValueResolver resolver, EvalContext ctx)
    {
        string ruleId = rule.Source.Id;
        try
        {
            var v = HarborlineJsonLogic.Evaluate(rule.Ast, ctx);
            return rule.OutputType switch
            {
                OutputType.Value => new Built(RuleOutcome.OfValue(ruleId, target, ComputedValue.Resolved(v)), false),
                OutputType.Validity => new Built(RuleOutcome.OfValidity(ruleId, target,
                    HarborlineJsonLogic.IsTruthy(v) ? Validity.Valid : Validity.Invalid(RuleError.Of(ruleId))), false),
                OutputType.Visibility => new Built(RuleOutcome.OfVisibility(ruleId, target,
                    VisibilityFor(rule.Source.Action, HarborlineJsonLogic.IsTruthy(v))), false),
                OutputType.Presentation => new Built(RuleOutcome.OfPresentation(ruleId, target,
                    HarborlineJsonLogic.IsTruthy(v) ? PresentationFor(rule.Source) : new PresentationOutcome()), false),
                OutputType.Options => new Built(RuleOutcome.OfOptions(ruleId, target, OptionsFor(v)), false),
                _ => throw new InvalidOperationException("unreachable"),
            };
        }
        catch (RulePendingException)
        {
            return rule.OutputType switch
            {
                OutputType.Value => new Built(RuleOutcome.OfValue(ruleId, target, ComputedValue.OfPending()), true),
                // On the synchronous .NET integrity tier a pending dependency at save is fail-closed.
                OutputType.Validity => new Built(RuleOutcome.OfValidity(ruleId, target,
                    Validity.Invalid(RuleError.Of(RuleEngineCodes.PendingAtSave))), true),
                // Required is a restriction. If it cannot produce a verdict, emit a refusing
                // validity outcome rather than silently relaxing the field to not-required.
                OutputType.Visibility when rule.Source.Action == RuleActionKind.Required =>
                    new Built(RuleOutcome.OfValidity(ruleId, target,
                        Validity.Invalid(RuleError.Of(RuleEngineCodes.PendingAtSave, "rule", ruleId))), true),
                OutputType.Visibility => new Built(RuleOutcome.OfVisibility(ruleId, target, FailClosedVisibility(rule.Source.Action)), true),
                OutputType.Options => new Built(RuleOutcome.OfOptions(ruleId, target, OptionsOutcome.OfPending()), true),
                _ => new Built(RuleOutcome.OfPresentation(ruleId, target, new PresentationOutcome()), true),
            };
        }
        catch (RuleEvalException ex)
        {
            return rule.OutputType switch
            {
                OutputType.Value => new Built(RuleOutcome.OfValue(ruleId, target, ComputedValue.OfError(ex.Error)), false),
                OutputType.Validity => new Built(RuleOutcome.OfValidity(ruleId, target, Validity.Invalid(ex.Error)), false),
                OutputType.Visibility when rule.Source.Action == RuleActionKind.Required =>
                    new Built(RuleOutcome.OfValidity(ruleId, target, Validity.Invalid(WithRule(ex.Error, ruleId))), false),
                OutputType.Visibility => new Built(RuleOutcome.OfVisibility(ruleId, target, FailClosedVisibility(rule.Source.Action)), false),
                OutputType.Options => new Built(RuleOutcome.OfOptions(ruleId, target, OptionsOutcome.OfError(ex.Error)), false),
                _ => new Built(RuleOutcome.OfPresentation(ruleId, target, new PresentationOutcome(Severity.Error)), false),
            };
        }
    }

    private static RuleError WithRule(RuleError error, string ruleId)
    {
        if (error.Params.ContainsKey("rule")) return error;
        var withRule = new Dictionary<string, string>(error.Params.Count + 1, StringComparer.Ordinal);
        foreach (var (key, value) in error.Params) withRule[key] = value;
        withRule["rule"] = ruleId;
        return new RuleError(error.Code, withRule);
    }

    // A set-options rule's expression must evaluate to a JSON array; any other type fails closed
    // (ADR 0146 D2). Elements are detached (DeepClone) so the resolved list owns them.
    private static OptionsOutcome OptionsFor(JsonNode? v)
        => v is JsonArray arr
            ? OptionsOutcome.Resolved(arr.Select(e => e?.DeepClone()).ToList())
            : OptionsOutcome.OfError(RuleError.Of(RuleEngineCodes.OptionsNotArray));

    private static VisibilityState VisibilityFor(RuleActionKind action, bool result) => action switch
    {
        RuleActionKind.Required => new VisibilityState(Required: result),
        RuleActionKind.ReadOnly => new VisibilityState(ReadOnly: result),
        _ => new VisibilityState(Visible: result), // Visibility
    };

    // Fail-closed-safe state when a visibility-family permit errors: hide / readonly. Required is a
    // restriction and refuses through a failing validity outcome before this method is reached.
    private static VisibilityState FailClosedVisibility(RuleActionKind action) => action switch
    {
        RuleActionKind.ReadOnly => new VisibilityState(ReadOnly: true),
        _ => new VisibilityState(Visible: false),
    };

    private static PresentationOutcome PresentationFor(RuleDefinition rule)
    {
        if (!rule.Presentation.HasValue || rule.Presentation.Value is not { } hint)
            return new PresentationOutcome();
        return new PresentationOutcome(
            hint.Severity.HasValue
                ? hint.Severity.Value switch
                {
                    PresentationHintSeverityValue.Info => Severity.Info,
                    PresentationHintSeverityValue.Warn => Severity.Warn,
                    PresentationHintSeverityValue.Error => Severity.Error,
                    _ => null,
                }
                : null,
            hint.Badge.HasValue ? hint.Badge.Value : null,
            hint.StyleToken.HasValue ? hint.StyleToken.Value : null);
    }
}

using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Compilation;
using Harborline.Foundation.RuleEngine.Environments;
using Harborline.Foundation.RuleEngine.Context;
using Harborline.Foundation.RuleEngine.Evaluation;
using Harborline.Foundation.RuleEngine.Model;


namespace Harborline.Foundation.RuleEngine.Graph;

/// <summary>
/// The form orchestrator (SPINE-1 design §2, §5.2). Builds the instance dependency
/// graph (addressable-cell DAG), topo-sorts it (Kahn), evaluates value cells with
/// Error/Pending propagation, exposes per-rule outcomes + form-facing views, and
/// reactively re-evaluates the transitive-dependent set on a single-cell change or a
/// child-table row add/remove.
/// </summary>
public sealed class FormRuleGraph : IFormRuleGraph
{
    private readonly RuleEngineLimits _limits;
    private readonly TimeProvider _clock;

    private RuleInstance _instance = new();

    // Build artifacts (rebuilt on structural change).
    private readonly List<ComputedCell> _order = new();              // topo-ordered computed cells
    private readonly Dictionary<string, ComputedCell> _cells = new();
    private readonly Dictionary<string, HashSet<string>> _deps = new();      // cell -> its dependency cells
    private readonly Dictionary<string, HashSet<string>> _dependents = new();// cell -> computed cells depending on it
    // Broad reverse index: ANY referenced cell key (raw field OR computed) -> computed cells that read it.
    // Used by the reactive path so a change to a RAW field still dirties its dependents.
    private readonly Dictionary<string, HashSet<string>> _readers = new();
    // Actual (expression-valued missing key) reads from the current generation.
    // Kept separate from static references so a key-list change can replace them.
    private readonly Dictionary<string, HashSet<string>> _dynamicReaders = new();
    private readonly Dictionary<string, HashSet<string>> _actualCellReads = new();
    private readonly Dictionary<string, HashSet<string>> _actualPlanReads = new();
    private readonly List<OutcomePlan> _plans = new();

    // Last evaluation state (mutated incrementally).
    private readonly Dictionary<string, ComputedValue> _values = new();
    private readonly Dictionary<string, RuleOutcome> _outcomes = new();
    private DateTimeOffset _evaluationInstant;
    private readonly string? _refusal;

    /// <summary>
    /// Binds a compiled graph to a borrower's admitted environment (rules-eng-26). A null or insufficient
    /// admission does not throw here: every evaluation entry point refuses with its code instead.
    /// </summary>
    public FormRuleGraph(CompiledGraph compiled, TimeProvider clock, EvaluationAdmission? admission, RuleEngineLimits? limits = null)
    {
        Compiled = compiled ?? throw new ArgumentNullException(nameof(compiled));
        _limits = limits ?? RuleEngineLimits.Default;
        _clock = clock ?? throw new ArgumentNullException(nameof(clock));
        WorkProof = CoreWorkDerivation.DeriveGraph(Compiled.Rules, _limits);
        // T-818: the admission refusal keeps priority; otherwise the proof under THIS graph's limits must fit.
        _refusal = BorrowerEnvironmentAdmission.Check(admission, compiled)
            ?? RuleCompiler.StaticWorkRefusal(WorkProof, _limits)?.Code;
    }

    /// <inheritdoc />
    public CompiledGraph Compiled { get; }

    /// <summary>Finite proof instantiated for this graph's structural runtime dimensions.</summary>
    public WorkProof WorkProof { get; }

    /// <inheritdoc />
    public RuleEvaluationResult EvaluateInstance(RuleInstance instance, CancellationToken ct = default)
    {
        if (_refusal is not null) return FailClosed(_refusal);
        try
        {
            _instance = (instance ?? throw new ArgumentNullException(nameof(instance))).CaptureOwned();
        }
        catch (InvalidOperationException exception) when (exception.Message == RuleEngineCodes.ContextSnapshotRequired)
        {
            return FailClosed(RuleEngineCodes.ContextSnapshotRequired);
        }
        catch (ArgumentException)
        {
            return FailClosed(RuleEngineCodes.InputTooLarge);
        }
        return BuildAndEvaluate(ct);
    }

    /// <inheritdoc />
    public RuleEvaluationResult Reevaluate(string fieldName, JsonNode? unownedValue, CancellationToken ct = default)
    {
        if (_refusal is not null) return FailClosed(_refusal);
        try { RuntimeInputEnvelope.ValidateMemberName(fieldName, nameof(fieldName)); }
        catch (ArgumentException) { return FailClosed(RuleEngineCodes.InputTooLarge); }
        return FailClosed(RuleEngineCodes.ContextSnapshotRequired);
    }

    /// <inheritdoc />
    public RuleEvaluationResult Reevaluate(string fieldName, RuleInputValue newValue, CancellationToken ct = default)
    {
        if (_refusal is not null) return FailClosed(_refusal);
        ArgumentNullException.ThrowIfNull(fieldName);
        ArgumentNullException.ThrowIfNull(newValue);
        try { RuntimeInputEnvelope.ValidateMemberName(fieldName, nameof(fieldName)); }
        catch (ArgumentException) { return FailClosed(RuleEngineCodes.InputTooLarge); }
        bool hadPrevious = _instance.Fields.TryGetValue(fieldName, out var previous);
        _instance.Fields[fieldName] = newValue.CloneOwned();
        try { _instance.EnsureEnvelope(); }
        catch (ArgumentException)
        {
            if (hadPrevious) _instance.Fields[fieldName] = previous;
            else _instance.Fields.Remove(fieldName);
            return FailClosed(RuleEngineCodes.InputTooLarge);
        }
        string changedKey = CellAddress.Field(fieldName).Key;

        // Transitive dependents of the changed (possibly raw) cell, via the broad reader index.
        var dirty = new HashSet<string>();
        var queue = new Queue<string>();
        queue.Enqueue(changedKey);
        while (queue.Count > 0)
        {
            var node = queue.Dequeue();
            foreach (var readers in ReadersOf(node))
            {
                foreach (var d in readers)
                {
                    if (dirty.Add(d)) queue.Enqueue(d);
                }
            }
        }

        // The business clock is an explicit graph input. Seed only cells that read it, then use the
        // existing reader index to reach their transitive dependents; unrelated outcomes retain identity.
        foreach (var cell in _order.Where(cell => UsesClock(cell.Rule)))
        {
            if (dirty.Add(cell.Key)) queue.Enqueue(cell.Key);
        }
        while (queue.Count > 0)
        {
            var node = queue.Dequeue();
            foreach (var readers in ReadersOf(node))
            {
                foreach (var reader in readers)
                {
                    if (dirty.Add(reader)) queue.Enqueue(reader);
                }
            }
        }

        _evaluationInstant = _clock.GetUtcNow();
        var budget = NewBudget(ct);
        var adapter = new FormContextAdapter(_values, _instance); // ADR 0146 D3 context seam
        var run = new DemandRun(this, budget, adapter, dirty);
        try
        {
            // Re-eval only the dirty computed cells, in topo order.
            foreach (var cell in _order.Where(c => dirty.Contains(c.Key)))
            {
                _values[cell.Key] = run.Evaluate(cell);
            }
            // Re-eval only the outcomes that read the changed field or a dirty cell (referential stability elsewhere).
            var touched = new HashSet<string>(dirty) { changedKey };
            foreach (var plan in _plans.Where(p => UsesClock(p.Rule) || p.Reads.Overlaps(touched)
                || (_actualPlanReads.TryGetValue(p.Key, out var actual) && actual.Overlaps(touched))
                || dirty.Contains(p.Target.Key)))
            {
                run.InFlightRule = plan.Rule.Source.Id;
                run.InFlightCell = null;
                _outcomes[plan.Key] = BuildOutcome(plan, run);
            }
        }
        catch (RuleBudgetException) { return FailClosed(RuleEngineCodes.BudgetExceeded, run.InFlightRule, run.InFlightCell); }
        // RuleEngineTimeoutException is a non-authoritative liveness fault (D1 ratification): it is NOT
        // caught here — it propagates as an infrastructure exception so the wall-clock can never emit a
        // divergent evaluation outcome. The op-budget above is the sole authoritative fail-closed bound.

        return Project();
    }

    /// <inheritdoc />
    public RuleEvaluationResult AddRow(string section, RuleRow row, CancellationToken ct = default)
    {
        if (_refusal is not null) return FailClosed(_refusal);
        ArgumentNullException.ThrowIfNull(section);
        ArgumentNullException.ThrowIfNull(row);
        try { RuntimeInputEnvelope.ValidateMemberName(section, nameof(section)); }
        catch (ArgumentException) { return FailClosed(RuleEngineCodes.InputTooLarge); }
        RuleRow captured;
        try
        {
            captured = row.CaptureOwned();
        }
        catch (InvalidOperationException exception) when (exception.Message == RuleEngineCodes.ContextSnapshotRequired)
        {
            return FailClosed(RuleEngineCodes.ContextSnapshotRequired);
        }
        catch (ArgumentException)
        {
            return FailClosed(RuleEngineCodes.InputTooLarge);
        }
        var prospective = _instance.CaptureOwned();
        if (!prospective.Tables.TryGetValue(section, out var prospectiveRows)) prospective.Tables[section] = prospectiveRows = new List<RuleRow>();
        prospectiveRows.Add(captured);
        try { prospective.EnsureEnvelope(); }
        catch (ArgumentException)
        {
            return FailClosed(RuleEngineCodes.InputTooLarge);
        }
        if (_instance.Tables.TryGetValue(section, out var rows) && rows.Count >= _limits.MaxTableRowsPerAggregate && HasAggregateForSection(section))
            return RefuseTableRow(section);
        if (!_instance.Tables.TryGetValue(section, out rows)) _instance.Tables[section] = rows = new List<RuleRow>();
        rows.Add(captured);
        return BuildAndEvaluate(ct); // structural change: rebuild graph + re-link aggregates
    }

    /// <inheritdoc />
    public RuleEvaluationResult RemoveRow(string section, string rowId, CancellationToken ct = default)
    {
        if (_refusal is not null) return FailClosed(_refusal);
        try
        {
            RuntimeInputEnvelope.ValidateMemberName(section, nameof(section));
            RuntimeInputEnvelope.ValidateMemberName(rowId, nameof(rowId));
        }
        catch (ArgumentException) { return FailClosed(RuleEngineCodes.InputTooLarge); }
        if (_instance.Tables.TryGetValue(section, out var rows)) rows.RemoveAll(r => r.Id == rowId);
        return BuildAndEvaluate(ct);
    }

    // ── build + full evaluate ────────────────────────────────────────────────

    private EvalBudget NewBudget(CancellationToken ct)
    {
        // The .NET integrity tier's authoritative wall-clock backstop: a linked CTS with the ceiling.
        var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
        cts.CancelAfter(_limits.WallClockCeiling);
        return new EvalBudget(_limits, cts.Token);
    }

    private RuleEvaluationResult BuildAndEvaluate(CancellationToken ct)
    {
        _evaluationInstant = _clock.GetUtcNow();
        var preflight = PreflightBounds();
        if (preflight is not null) return FailClosed(preflight);

        Build();

        if (_cells.Count > _limits.MaxGraphNodes)
        {
            return FailClosed(RuleEngineCodes.GraphTooLarge);
        }

        var budget = NewBudget(ct);
        _values.Clear();
        _outcomes.Clear();
        var adapter = new FormContextAdapter(_values, _instance); // ADR 0146 D3 context seam
        var run = new DemandRun(this, budget, adapter, null);
        try
        {
            foreach (var cell in _order)
            {
                _values[cell.Key] = run.Evaluate(cell);
            }
            foreach (var plan in _plans)
            {
                run.InFlightRule = plan.Rule.Source.Id;
                run.InFlightCell = null;
                _outcomes[plan.Key] = BuildOutcome(plan, run);
            }
        }
        catch (RuleBudgetException) { return FailClosed(RuleEngineCodes.BudgetExceeded, run.InFlightRule, run.InFlightCell); }
        // RuleEngineTimeoutException is a non-authoritative liveness fault (D1 ratification 2026-07-01):
        // it is NOT caught here — it propagates as an infrastructure exception so the wall-clock can never
        // emit a divergent evaluation outcome. The op-budget above is the sole authoritative fail-closed bound.

        return Project();
    }

    private string? PreflightBounds()
    {
        // Bound the otherwise un-budgeted graph CONSTRUCTION (finding F3): project the cell count
        // BEFORE Build() expands Row rules across every (user-controlled) instance row + Kahn-sorts.
        // Also reject a Compute rule that addresses no form cell — Section/Schema scope — as a
        // fail-closed config error rather than a silent no-op (finding F8). (Guards use the shared
        // compiler directly, not this form graph, so their Schema-scoped Compute is unaffected.)
        long projectedCells = 0;
        var aggCells = new HashSet<string>();
        foreach (var rule in Compiled.Rules)
        {
            if (rule.Source.Action == RuleActionKind.Compute)
            {
                if (rule.Source.Scope is not (RuleScope.Field or RuleScope.Row or RuleScope.Table))
                    return RuleEngineCodes.ComputeScopeInvalid;
                projectedCells += rule.Source.Scope == RuleScope.Row ? RowsOf(rule.RowSection!).Count : 1;
            }
            foreach (var rf in rule.References)
                if (rf is AggRef a) aggCells.Add(CellAddress.TableAggregate(a.Section, a.Fn, a.Col).Key);
            if (projectedCells > _limits.MaxGraphNodes) return RuleEngineCodes.GraphTooLarge;
        }
        return projectedCells + aggCells.Count > _limits.MaxGraphNodes ? RuleEngineCodes.GraphTooLarge : null;
    }

    private void Build()
    {
        _cells.Clear();
        _deps.Clear();
        _dependents.Clear();
        _readers.Clear();
        _dynamicReaders.Clear();
        _actualCellReads.Clear();
        _actualPlanReads.Clear();
        _order.Clear();
        _plans.Clear();

        // 1. Compute cells (rule-driven) + their outcome plans; 2. implicit aggregate cells.
        foreach (var rule in Compiled.Rules)
        {
            if (rule.Source.Action == RuleActionKind.Compute)
            {
                AddComputeCellsAndPlans(rule);
            }
            else
            {
                AddNonComputePlans(rule);
            }

            // Aggregate cells referenced anywhere become implicit fold cells (unless a Table-compute defines them).
            foreach (var rf in rule.References)
            {
                if (rf is AggRef a)
                {
                    var addr = CellAddress.TableAggregate(a.Section, a.Fn, a.Col);
                    if (!_cells.ContainsKey(addr.Key))
                    {
                        _cells[addr.Key] = new ComputedCell(addr.Key, addr, null, null, AggFold: (a.Fn, a.Section, a.Col));
                    }
                }
            }
        }

        // 3. Edges.
        foreach (var cell in _cells.Values)
        {
            _deps.TryAdd(cell.Key, new HashSet<string>());
            _dependents.TryAdd(cell.Key, new HashSet<string>());
        }
        foreach (var cell in _cells.Values)
        {
            if (cell.AggFold is { } fold)
            {
                // Aggregate depends on each row's column cell. Bound this un-budgeted edge walk:
                // a table over the per-aggregate row cap fails closed in FoldAggregate, so don't
                // pre-walk all its (user-controlled) rows here (finding F3).
                if (_instance.Tables.TryGetValue(fold.Section, out var rows)
                    && rows.Count <= _limits.MaxTableRowsPerAggregate)
                {
                    foreach (var row in rows)
                    {
                        var rowKey = CellAddress.Row(fold.Section, row.Id, fold.Col).Key;
                        AddReader(rowKey, cell.Key);
                        if (_cells.ContainsKey(rowKey)) Edge(cell.Key, rowKey);
                    }
                }
            }
            else if (cell.Rule is { } cr)
            {
                foreach (var rf in cr.References)
                {
                    var depKey = ResolveRefKey(rf, cr, cell.RowId);
                    if (depKey is not null)
                    {
                        AddReader(depKey, cell.Key);
                        if (_cells.ContainsKey(depKey)) Edge(cell.Key, depKey);
                    }
                }
            }
        }

        // 4. Topological order (Kahn); cells that remain are in a (defensive) cycle.
        TopoSort();
    }

    private void AddComputeCellsAndPlans(CompiledRule rule)
    {
        switch (rule.Source.Scope)
        {
            case RuleScope.Field:
            {
                var addr = CellAddress.Field(rule.Source.ScopeTarget);
                _cells[addr.Key] = new ComputedCell(addr.Key, addr, rule, null, null);
                _plans.Add(MakePlan(rule, addr, null));
                break;
            }
            case RuleScope.Row:
            {
                foreach (var row in RowsOf(rule.RowSection!))
                {
                    var addr = CellAddress.Row(rule.RowSection!, row.Id, rule.RowField!);
                    _cells[addr.Key] = new ComputedCell(addr.Key, addr, rule, row.Id, null);
                    _plans.Add(MakePlan(rule, addr, row.Id));
                }
                break;
            }
            case RuleScope.Table:
            {
                var addr = rule.StaticTarget!.Value;
                _cells[addr.Key] = new ComputedCell(addr.Key, addr, rule, null, null);
                _plans.Add(MakePlan(rule, addr, null));
                break;
            }
        }
    }

    private void AddNonComputePlans(CompiledRule rule)
    {
        switch (rule.Source.Scope)
        {
            case RuleScope.Row:
                foreach (var row in RowsOf(rule.RowSection!))
                {
                    var addr = CellAddress.Row(rule.RowSection!, row.Id, rule.RowField!);
                    _plans.Add(MakePlan(rule, addr, row.Id));
                }
                break;
            default:
                _plans.Add(MakePlan(rule, rule.StaticTarget!.Value, null));
                break;
        }
    }

    private OutcomePlan MakePlan(CompiledRule rule, CellAddress target, string? rowId)
    {
        string key = rowId is null ? rule.Source.Id : rule.Source.Id + "#" + rowId;
        var reads = new HashSet<string>();
        foreach (var rf in rule.References)
        {
            var k = ResolveRefKey(rf, rule, rowId);
            if (k is not null) reads.Add(k);
        }
        return new OutcomePlan(key, rule, target, rowId, reads, rule.Source.Action == RuleActionKind.Compute);
    }

    private string? ResolveRefKey(RuleRef rf, CompiledRule rule, string? rowId) => rf switch
    {
        FieldRef f => CellAddress.Field(f.Name).Key,
        RowFieldRef rfld when rule.RowSection is not null && rowId is not null
            => CellAddress.Row(rule.RowSection, rowId, rfld.Field).Key,
        AggRef a => CellAddress.TableAggregate(a.Section, a.Fn, a.Col).Key,
        _ => null,
    };

    private IReadOnlyList<RuleRow> RowsOf(string section)
        => _instance.Tables.TryGetValue(section, out var rows) ? rows : Array.Empty<RuleRow>();

    private void Edge(string from, string dep)
    {
        _deps[from].Add(dep);
        _dependents[dep].Add(from);
    }

    private void AddReader(string key, string reader)
    {
        if (!_readers.TryGetValue(key, out var set)) _readers[key] = set = new HashSet<string>();
        set.Add(reader);
    }

    private IEnumerable<HashSet<string>> ReadersOf(string key)
    {
        if (_readers.TryGetValue(key, out var staticReaders)) yield return staticReaders;
        if (_dynamicReaders.TryGetValue(key, out var dynamicReaders)) yield return dynamicReaders;
    }

    private void ClearActualCellReads(string owner)
    {
        if (!_actualCellReads.Remove(owner, out var prior)) return;
        foreach (var key in prior)
        {
            if (!_dynamicReaders.TryGetValue(key, out var readers)) continue;
            readers.Remove(owner);
            if (readers.Count == 0) _dynamicReaders.Remove(key);
        }
    }

    private void RecordActualCellRead(string owner, string key)
    {
        if (!_actualCellReads.TryGetValue(owner, out var reads)) _actualCellReads[owner] = reads = new HashSet<string>();
        if (!reads.Add(key)) return;
        if (!_dynamicReaders.TryGetValue(key, out var readers)) _dynamicReaders[key] = readers = new HashSet<string>();
        readers.Add(owner);
    }

    private void BeginPlanReads(string key) => _actualPlanReads[key] = new HashSet<string>();

    private void RecordActualPlanRead(string owner, string key)
    {
        if (!_actualPlanReads.TryGetValue(owner, out var reads)) _actualPlanReads[owner] = reads = new HashSet<string>();
        reads.Add(key);
    }

    private void TopoSort()
    {
        var inDeg = _cells.Keys.ToDictionary(k => k, k => _deps[k].Count);
        var ready = new Queue<string>(inDeg.Where(kv => kv.Value == 0).Select(kv => kv.Key));
        var ordered = new HashSet<string>();
        while (ready.Count > 0)
        {
            var node = ready.Dequeue();
            _order.Add(_cells[node]);
            ordered.Add(node);
            foreach (var dependent in _dependents[node])
            {
                if (--inDeg[dependent] == 0) ready.Enqueue(dependent);
            }
        }
        // Any cell not ordered is in a defensive per-row cycle — appended; eval marks them Error(cycle).
        foreach (var cell in _cells.Values)
        {
            if (!ordered.Contains(cell.Key)) _order.Add(cell with { Cyclic = true });
        }
    }

    // ── cell + outcome evaluation ────────────────────────────────────────────

    private ComputedValue EvalComputedCell(ComputedCell cell, DemandRun run)
    {
        if (cell.Cyclic) return ComputedValue.OfError(RuleError.Of(RuleEngineCodes.Cycle, "cell", cell.Key));

        if (cell.AggFold is { } fold) return FoldAggregate(fold.Fn, fold.Section, fold.Col, run);

        var scope = new RuleEvalScope(cell.Rule!.RowSection, cell.RowId);
        var resolver = new DemandResolver(run.Adapter.CreateResolver(scope), run, cell.Key, scope);
        var ctx = new EvalContext(resolver, _evaluationInstant, run.Budget);
        try
        {
            return ComputedValue.Resolved(HarborlineJsonLogic.Evaluate(cell.Rule.Ast, ctx));
        }
        catch (RulePendingException) { return ComputedValue.OfPending(); }
        catch (RuleEvalException ex) { return ComputedValue.OfError(ex.Error); }
    }

    private static bool UsesClock(CompiledRule? rule) => rule is not null && ContainsDateToday(rule.Ast);

    private static bool ContainsDateToday(JsonNode? node)
    {
        // The evaluator only executes a single-key object; arrays and multi-key objects
        // are literal data.  Recurse only through an executable operator's argument list.
        if (node is not JsonObject obj || obj.Count != 1) return false;
        var (op, raw) = obj.First();
        if (op == "date.today") return true;
        return raw is JsonArray args
            ? args.Any(ContainsDateToday)
            : ContainsDateToday(raw);
    }

    private RuleOutcome BuildOutcome(OutcomePlan plan, DemandRun run)
    {
        if (plan.IsComputeValue)
        {
            var cv = _values.TryGetValue(plan.Target.Key, out var v) ? v : ComputedValue.Resolved(null);
            return RuleOutcome.OfValue(plan.Rule.Source.Id, plan.Target, cv);
        }
        BeginPlanReads(plan.Key);
        var scope = new RuleEvalScope(plan.Rule.RowSection, plan.RowId);
        var resolver = new DemandResolver(run.Adapter.CreateResolver(scope), run, plan.Key, scope, plan: true);
        var ctx = new EvalContext(resolver, _evaluationInstant, run.Budget);
        return OutcomeBuilder.Build(plan.Rule, plan.Target, resolver, ctx).Outcome;
    }

    private ComputedValue FoldAggregate(string fn, string section, string col, DemandRun run)
    {
        if (!_instance.Tables.TryGetValue(section, out var rows)) rows = new List<RuleRow>();
        if (rows.Count > _limits.MaxTableRowsPerAggregate)
        {
            return ComputedValue.OfError(RuleError.Of(RuleEngineCodes.TableTooLarge, "section", section));
        }

        var values = new List<JsonNode?>();
        foreach (var row in rows)
        {
            run.Budget.Charge();
            var rowKey = CellAddress.Row(section, row.Id, col).Key;
            ComputedValue cv;
            // A demanded aggregate can run before the ordinary topo loop reaches its
            // row producer. Demand the current-generation cell when one exists;
            // only an absent producer is permitted to use the raw row value.
            if (_cells.TryGetValue(rowKey, out var rowCell))
            {
                cv = run.Evaluate(rowCell);
            }
            else
            {
                var raw = row.Fields.TryGetValue(col, out var rv) ? rv : null;
                cv = PendingSentinel.Is(raw) ? ComputedValue.OfPending() : ComputedValue.Resolved(raw);
            }
            if (cv.State == ValueState.Pending) return ComputedValue.OfPending();
            if (cv.State == ValueState.Error) return ComputedValue.OfError(RuleError.Of(RuleEngineCodes.UpstreamError, "cell", rowKey));
            values.Add(cv.Value);
        }

        // A column whose every value is a decimal string is money — sum/min/max/avg must be exact
        // decimal, never IEEE double (finding F7). Number columns keep the numeric (double) fold.
        bool allDecimalStrings = values.Count > 0 && values.All(v => v is JsonValue jv && jv.TryGetValue<string>(out _));
        try
        {
            if (allDecimalStrings && fn is "sum" or "min" or "max" or "avg")
            {
                return MoneyAggregate(fn, values, section);
            }
            return fn switch
            {
                "count" => ComputedValue.Resolved(JsonValue.Create(values.Count)),
                "sum" => ComputedValue.Resolved(NumNode(values.Sum(v => HarborlineJsonLogic.ToNumber(v)))),
                "avg" => ComputedValue.Resolved(values.Count == 0
                    ? JsonValue.Create(0)
                    : NumNode(values.Sum(v => HarborlineJsonLogic.ToNumber(v)) / values.Count)),
                "min" => ComputedValue.Resolved(values.Count == 0 ? null : NumNode(values.Min(v => HarborlineJsonLogic.ToNumber(v)))),
                "max" => ComputedValue.Resolved(values.Count == 0 ? null : NumNode(values.Max(v => HarborlineJsonLogic.ToNumber(v)))),
                "any" => ComputedValue.Resolved(JsonValue.Create(values.Any(HarborlineJsonLogic.IsTruthy))),
                "all" => ComputedValue.Resolved(JsonValue.Create(values.All(HarborlineJsonLogic.IsTruthy))),
                _ => ComputedValue.OfError(RuleError.Of(RuleEngineCodes.UnknownOperator, "agg", fn)),
            };
        }
        catch (RuleEvalException ex)
        {
            return ComputedValue.OfError(ex.Error);
        }
    }

    private ComputedValue MoneyAggregate(string fn, List<JsonNode?> values, string section)
    {
        // Exact decimal sum/min/max over a money (decimal-string) column (finding F7). avg needs
        // exact decimal division (undefined in v1) → fail closed rather than silently use double.
        if (fn == "avg")
            return ComputedValue.OfError(RuleError.Of(RuleEngineCodes.MoneyAggUnsupported, "section", section));
        try
        {
            var acc = MoneyDecimal.Parse(((JsonValue)values[0]!).GetValue<string>());
            for (int i = 1; i < values.Count; i++)
            {
                var m = MoneyDecimal.Parse(((JsonValue)values[i]!).GetValue<string>());
                acc = fn switch
                {
                    "sum" => acc + m,
                    "min" => m.Compare(acc) < 0 ? m : acc,
                    "max" => m.Compare(acc) > 0 ? m : acc,
                    _ => acc,
                };
            }
            return ComputedValue.Resolved(JsonValue.Create(acc.ToCanonicalString()));
        }
        catch (FormatException)
        {
            return ComputedValue.OfError(RuleError.Of(RuleEngineCodes.TypeError, "op", "agg"));
        }
    }

    private static JsonNode NumNode(double d)
        => d == Math.Floor(d) && Math.Abs(d) < 9.007e15 ? JsonValue.Create((long)d) : JsonValue.Create(d);

    // ── projection ───────────────────────────────────────────────────────────

    private RuleEvaluationResult Project()
    {
        var projectedOutcomes = _outcomes.ToDictionary(pair => pair.Key, pair => ProjectOutcome(pair.Value));
        var projectedValues = _values.ToDictionary(pair => pair.Key, pair => ProjectValue(pair.Value));
        var visibility = new Dictionary<string, VisibilityState>();
        var validations = new List<RuleOutcome>();
        var options = new Dictionary<string, OptionsOutcome>();
        bool hasPending = projectedValues.Values.Any(v => v.State == ValueState.Pending);

        foreach (var outcome in projectedOutcomes.Values)
        {
            switch (outcome.OutputType)
            {
                case OutputType.Visibility:
                    visibility[outcome.Target.Key] = Merge(
                        visibility.TryGetValue(outcome.Target.Key, out var prev) ? prev : new VisibilityState(),
                        outcome.Visibility!);
                    break;
                case OutputType.Validity when outcome.Validity is { Ok: false }:
                    validations.Add(outcome);
                    break;
                case OutputType.Value when outcome.Value is { State: ValueState.Pending }:
                    hasPending = true;
                    break;
                case OutputType.Options:
                    // Last-writer-wins per cell (multiple set-options rules on one field is an
                    // authoring smell, not an engine concern — the graph is deterministically ordered).
                    options[outcome.Target.Key] = outcome.Options!;
                    break;
            }
        }

        return new RuleEvaluationResult(
            projectedOutcomes,
            projectedValues,
            visibility,
            validations,
            hasPending,
            options);
    }

    private static ComputedValue ProjectValue(ComputedValue value)
        => value.State == ValueState.Resolved && value.Value is JsonObject or JsonArray
            ? value with { Value = value.Value.DeepClone() }
            : value;

    private static RuleOutcome ProjectOutcome(RuleOutcome outcome)
        => outcome.OutputType switch
        {
            OutputType.Value when !ReferenceEquals(ProjectValue(outcome.Value!), outcome.Value)
                => RuleOutcome.OfValue(outcome.RuleId, outcome.Target, ProjectValue(outcome.Value!)),
            OutputType.Value => outcome,
            OutputType.Options => RuleOutcome.OfOptions(outcome.RuleId, outcome.Target,
                outcome.Options! with { Options = outcome.Options.Options?.Select(option => option?.DeepClone()).ToList() }),
            _ => outcome,
        };

    // Merge rule: any visibility-rule false hides; required/readOnly are OR-merged.
    private static VisibilityState Merge(VisibilityState a, VisibilityState b)
        => new(a.Visible && b.Visible, a.Required || b.Required, a.ReadOnly || b.ReadOnly);

    private RuleEvaluationResult FailClosed(string code, string? ruleId = null, string? cellKey = null)
    {
        var error = ruleId is not null ? RuleError.Of(code, "rule", ruleId)
            : cellKey is not null ? RuleError.Of(code, "cell", cellKey)
            : RuleError.Of(code);
        var synthetic = RuleOutcome.OfValidity("rule.engine", CellAddress.Schema(),
            Validity.Invalid(error));
        return new RuleEvaluationResult(
            new Dictionary<string, RuleOutcome> { ["rule.engine"] = synthetic },
            new Dictionary<string, ComputedValue>(),
            new Dictionary<string, VisibilityState>(),
            new List<RuleOutcome> { synthetic },
            hasPending: false);
    }

    private RuleEvaluationResult RefuseTableRow(string section)
    {
        var accepted = Project();
        var values = accepted.Values.ToDictionary(pair => pair.Key, pair => pair.Value);
        foreach (var key in values.Keys.Where(key => key.StartsWith("agg:" + section + "/", StringComparison.Ordinal)).ToArray())
            values[key] = ComputedValue.OfError(RuleError.Of(RuleEngineCodes.TableTooLarge, "section", section));
        return new RuleEvaluationResult(accepted.ByRule, values, accepted.Visibility, accepted.Validations, accepted.HasPending, accepted.Options);
    }

    private bool HasAggregateForSection(string section)
        => Compiled.Rules.Any(rule => rule.References.Any(reference => reference is AggRef aggregate && aggregate.Section == section));

    // ── internal node + plan records ─────────────────────────────────────────

    private sealed class DemandRun
    {
        private readonly FormRuleGraph _graph;
        private readonly HashSet<string> _active = new();
        private readonly HashSet<string> _completed = new();
        private readonly HashSet<string>? _dirty;

        public DemandRun(FormRuleGraph graph, EvalBudget budget, IContextAdapter adapter, HashSet<string>? dirty)
        {
            _graph = graph;
            Budget = budget;
            Adapter = adapter;
            _dirty = dirty;
        }

        public EvalBudget Budget { get; }
        public IContextAdapter Adapter { get; }
        public string? InFlightRule { get; set; }
        public string? InFlightCell { get; set; }

        public ComputedValue Evaluate(ComputedCell cell)
        {
            if (_dirty is not null && !_dirty.Contains(cell.Key) && _graph._values.TryGetValue(cell.Key, out var stable)) return stable;
            if (_completed.Contains(cell.Key) && _graph._values.TryGetValue(cell.Key, out var complete)) return complete;
            if (_active.Contains(cell.Key)) return ComputedValue.OfError(RuleError.Of(RuleEngineCodes.Cycle, "cell", cell.Key));
            // Static admission bounds a declared chain; this closes the additional runtime
            // dynamic chain before host recursion can grow without a validated limit.
            // _active already contains the parent chain, so before adding this cell its
            // count is the number of demand edges that will lead to it. Match compiler
            // admission: depth zero permits a leaf, and only depth greater than the cap
            // is refused.
            if (_active.Count > Budget.Limits.MaxDependencyDepth)
            {
                var parameters = new Dictionary<string, string> { ["cell"] = cell.Key };
                if (cell.Rule is not null) parameters["rule"] = cell.Rule.Source.Id;
                return ComputedValue.OfError(new RuleError(RuleEngineCodes.BudgetExceeded, parameters));
            }

            var previousRule = InFlightRule;
            var previousCell = InFlightCell;
            InFlightRule = cell.Rule?.Source.Id;
            InFlightCell = cell.Rule is null ? cell.Key : null;
            Budget.Charge();
            _active.Add(cell.Key);
            _graph.ClearActualCellReads(cell.Key);
            try
            {
                var value = _graph.EvalComputedCell(cell, this);
                _graph._values[cell.Key] = value;
                _completed.Add(cell.Key);
                InFlightRule = previousRule;
                InFlightCell = previousCell;
                return value;
            }
            finally
            {
                _active.Remove(cell.Key);
            }
        }

        public RefValue Resolve(string owner, bool plan, string key, Func<RefValue> fallback)
        {
            if (plan) _graph.RecordActualPlanRead(owner, key);
            else _graph.RecordActualCellRead(owner, key);
            if (!_graph._cells.TryGetValue(key, out var cell)) return fallback();
            return FromComputed(Evaluate(cell), key);
        }

        private static RefValue FromComputed(ComputedValue value, string key) => value.State switch
        {
            ValueState.Resolved => RefValue.Resolved(value.Value),
            ValueState.Pending => RefValue.Pending,
            _ => RefValue.OfError(value.Error?.Code is RuleEngineCodes.Cycle or RuleEngineCodes.BudgetExceeded
                ? value.Error
                : RuleError.Of(RuleEngineCodes.UpstreamError, "cell", key)),
        };
    }

    private sealed class DemandResolver : IValueResolver
    {
        private readonly IValueResolver _fallback;
        private readonly DemandRun _run;
        private readonly string _owner;
        private readonly bool _plan;
        private readonly RuleEvalScope _scope;

        public DemandResolver(IValueResolver fallback, DemandRun run, string owner, RuleEvalScope scope, bool plan = false)
        {
            _fallback = fallback;
            _run = run;
            _owner = owner;
            _scope = scope;
            _plan = plan;
        }

        public RefValue ResolveVar(string path)
        {
            if (path.StartsWith("row.", StringComparison.Ordinal))
            {
                if (_scope.RowSection is null || _scope.RowId is null) return _fallback.ResolveVar(path);
                var rowKey = CellAddress.Row(_scope.RowSection, _scope.RowId, path["row.".Length..]).Key;
                return _run.Resolve(_owner, _plan, rowKey, () => _fallback.ResolveVar(path));
            }
            var name = path.StartsWith("field.", StringComparison.Ordinal) ? path["field.".Length..] : path;
            var key = CellAddress.Field(name).Key;
            return _run.Resolve(_owner, _plan, key, () => _fallback.ResolveVar(path));
        }

        public RefValue ResolveAgg(string fn, string section, string col)
        {
            var key = CellAddress.TableAggregate(section, fn, col).Key;
            return _run.Resolve(_owner, _plan, key, () => _fallback.ResolveAgg(fn, section, col));
        }
    }

    private sealed record ComputedCell(
        string Key,
        CellAddress Address,
        CompiledRule? Rule,
        string? RowId,
        (string Fn, string Section, string Col)? AggFold)
    {
        public bool Cyclic { get; init; }
    }

    private sealed record OutcomePlan(
        string Key,
        CompiledRule Rule,
        CellAddress Target,
        string? RowId,
        HashSet<string> Reads,
        bool IsComputeValue);
}

using System.Text.Json.Nodes;
using System.Runtime.CompilerServices;
using System.Text.Json;

using Harborline.Foundation.RuleEngine.Context;

namespace Harborline.Foundation.RuleEngine.Graph;

/// <summary>Explicit, bounded JSON-text capture for one reactive field value.</summary>
public sealed class RuleInputValue
{
    private readonly JsonNode? _value;

    private RuleInputValue(JsonNode? value) => _value = value;

    /// <summary>Parses and owns one JSON value outside graph evaluation.</summary>
    public static RuleInputValue FromJsonText(string jsonText)
        => new(RuleInstance.CaptureParsedValue(RuntimeInputEnvelope.Parse(jsonText, nameof(jsonText))));

    internal JsonNode? CloneOwned() => RuleInstance.CloneTrusted(_value);
}

/// <summary>One child-table row in a <see cref="RuleInstance"/>.</summary>
public sealed class RuleRow
{
    /// <summary>Creates a row with an explicit <paramref name="id"/>, capturing a private copy of each field value.</summary>
    public RuleRow(string id, IReadOnlyDictionary<string, JsonNode?> fields)
        : this(id, fields.ToDictionary(pair => pair.Key, pair => RuleInstance.CaptureHostValue(pair.Value), StringComparer.Ordinal), hasExplicitId: true)
    {
    }

    internal RuleRow(string id, Dictionary<string, JsonNode?> fields, bool hasExplicitId)
    {
        Id = id;
        Fields = fields;
        HasExplicitId = hasExplicitId;
    }

    /// <summary>Stable row id (the row's <c>_id</c> property, else its ordinal at load).</summary>
    public string Id { get; }

    /// <summary>The row's cell values, keyed by field name.</summary>
    public Dictionary<string, JsonNode?> Fields { get; }

    internal bool HasExplicitId { get; }

    internal RuleRow CaptureOwned()
    {
        // Fields remain publicly mutable. Validate every current descendant before any
        // clone can promote it into runtime-owned state.
        // A row is temporarily represented by a root-only prospective instance below.
        // Refuse an impossible member count before allocating/copying every public entry.
        if (Fields.Count > RuntimeInputEnvelope.MaxNodes - 1)
            throw new ArgumentException("Rule context exceeds the bounded structure envelope.");
        var prospective = new RuleInstance();
        foreach (var (key, value) in Fields) prospective.Fields[key] = value;
        prospective.EnsureEnvelope();
        var fields = new Dictionary<string, JsonNode?>();
        foreach (var (key, value) in Fields) fields[key] = RuleInstance.CloneTrusted(value);
        return RuleInstance.CreateCapturedRow(Id, fields, HasExplicitId);
    }
}

/// <summary>
/// A form instance the rule graph evaluates over (SPINE-1 design §2.1): top-level
/// fields plus child tables (ordered rows). Decoupled from the persistence /
/// FormDefinition shape — the engine operates on this abstract value tree, so it
/// does not depend on the FORM-2 child-table build state.
/// </summary>
public sealed class RuleInstance
{
    private static readonly ConditionalWeakTable<JsonNode, object> TrustedNodes = new();
    private static readonly object TrustedMarker = new();
    /// <summary>Top-level field values, keyed by field name.</summary>
    public Dictionary<string, JsonNode?> Fields { get; } = new();

    /// <summary>Child tables, keyed by section id; each is an ordered list of rows.</summary>
    public Dictionary<string, List<RuleRow>> Tables { get; } = new();

    /// <summary>
    /// Builds an instance from a JSON object: a property whose value is an array of
    /// objects is a child table (section id = property name; row id = each element's
    /// <c>_id</c> string, else its index); every other property is a top-level field.
    /// </summary>
    public static RuleInstance FromJson(JsonObject json)
    {
        ArgumentNullException.ThrowIfNull(json);
        ValidateHostObject(json);
        return CaptureParsedObject(json.DeepClone().AsObject());
    }

    /// <summary>Captures a bounded JSON object into a runtime-owned graph instance.</summary>
    public static RuleInstance FromJsonText(string jsonText)
    {
        var json = RuntimeInputEnvelope.Parse(jsonText, nameof(jsonText)) as JsonObject
            ?? throw new ArgumentException("Rule instance must be a JSON object.", nameof(jsonText));
        return CaptureParsedObject(json);
    }

    private static RuleInstance CaptureParsedObject(JsonObject json)
    {
        var instance = new RuleInstance();
        foreach (var (key, value) in json)
        {
            if (value is JsonArray arr && arr.Count > 0 && arr.All(e => e is JsonObject))
            {
                var rows = new List<RuleRow>();
                for (int i = 0; i < arr.Count; i++)
                {
                    var rowObj = (JsonObject)arr[i]!;
                    string id = rowObj.TryGetPropertyValue("_id", out var idNode) && idNode is not null
                        ? idNode.GetValue<string>()
                        : i.ToString(System.Globalization.CultureInfo.InvariantCulture);
                    var fields = new Dictionary<string, JsonNode?>();
                    foreach (var (fk, fv) in rowObj)
                    {
                        if (fk == "_id") continue;
                    fields[fk] = CaptureParsedValue(fv);
                    }
                    rows.Add(CreateCapturedRow(id, fields, idNode is not null));
                }
                instance.Tables[key] = rows;
            }
            else
            {
                instance.Fields[key] = CaptureParsedValue(value);
            }
        }
        return instance;
    }

    /// <summary>
    /// Produces the runtime-owned value tree used by a graph. The graph must not retain
    /// aliases to a host instance after its explicit capture boundary.
    /// </summary>
    internal RuleInstance CaptureOwned()
    {
        PreflightStructure();
        var captured = new RuleInstance();
        foreach (var (key, value) in Fields) captured.Fields[key] = CloneTrusted(value);
        foreach (var (section, rows) in Tables)
        {
            var table = new List<RuleRow>();
            foreach (var row in rows)
            {
                var fields = new Dictionary<string, JsonNode?>();
                foreach (var (key, value) in row.Fields) fields[key] = CloneTrusted(value);
                table.Add(CreateCapturedRow(row.Id, fields, row.HasExplicitId));
            }
            captured.Tables[section] = table;
        }
        return captured;
    }

    /// <summary>Validates the complete prospective graph state against the JSON capture envelope.</summary>
    internal void EnsureEnvelope()
    {
        PreflightStructure();
    }

    private void PreflightStructure()
    {
        var nodes = 1; // root object
        var composedContainers = new List<JsonNode>();
        void Visit(JsonNode? node, int depth)
        {
            if (node is null) { if (++nodes > RuntimeInputEnvelope.MaxNodes) throw new ArgumentException("Rule context exceeds the node envelope."); return; }
            if (++nodes > RuntimeInputEnvelope.MaxNodes)
                throw new ArgumentException("Rule context exceeds the bounded structure envelope.");
            switch (node)
            {
                case JsonValue:
                    EnsureTrusted(node);
                    break;
                case JsonObject obj:
                    if (depth > RuntimeInputEnvelope.MaxDepth) throw new ArgumentException("Rule context exceeds the bounded structure envelope.");
                    composedContainers.Add(node);
                    foreach (var (key, child) in obj) { RuntimeInputEnvelope.ValidateMemberName(key, nameof(RuleInstance)); Visit(child, depth + 1); }
                    break;
                case JsonArray array:
                    if (depth > RuntimeInputEnvelope.MaxDepth) throw new ArgumentException("Rule context exceeds the bounded structure envelope.");
                    composedContainers.Add(node);
                    foreach (var child in array) Visit(child, depth + 1);
                    break;
                default:
                    throw new InvalidOperationException(RuleEngineCodes.ContextSnapshotRequired);
            }
        }
        foreach (var (key, value) in Fields) { RuntimeInputEnvelope.ValidateMemberName(key, nameof(RuleInstance)); Visit(value, 2); }
        foreach (var (section, rows) in Tables)
        {
            RuntimeInputEnvelope.ValidateMemberName(section, nameof(RuleInstance));
            if (++nodes > RuntimeInputEnvelope.MaxNodes) throw new ArgumentException("Rule context exceeds the node envelope."); // table array
            foreach (var row in rows)
            {
                RuntimeInputEnvelope.ValidateMemberName(row.Id, nameof(RuleInstance));
                if (++nodes > RuntimeInputEnvelope.MaxNodes) throw new ArgumentException("Rule context exceeds the node envelope."); // row object
                if (row.HasExplicitId && ++nodes > RuntimeInputEnvelope.MaxNodes) throw new ArgumentException("Rule context exceeds the node envelope."); // supplied _id
                foreach (var (key, value) in row.Fields) { RuntimeInputEnvelope.ValidateMemberName(key, nameof(RuleInstance)); Visit(value, 4); }
            }
        }

        var bytes = new JsonStringifyCounter(RuntimeInputEnvelope.MaxUtf8Bytes);
        bytes.Add(1); // root brace
        var first = true;
        void AddMember(string name, JsonNode? value)
        {
            if (!first) bytes.Add(1);
            bytes.CountString(name);
            bytes.Add(1); // colon
            first = false;
            bytes.CountValue(value);
        }
        foreach (var (key, value) in Fields) AddMember(key, value);
        foreach (var (section, rows) in Tables)
        {
            if (!first) bytes.Add(1);
            bytes.CountString(section);
            bytes.Add(2); // colon + opening array bracket
            first = false;
            var firstRow = true;
            foreach (var row in rows)
            {
                if (!firstRow) bytes.Add(1);
                firstRow = false;
                bytes.Add(1); // object opening brace
                var firstRowMember = true;
                void AddRowMember(string name, JsonNode? value)
                {
                    if (!firstRowMember) bytes.Add(1);
                    bytes.CountString(name);
                    bytes.Add(1); // colon
                    firstRowMember = false;
                    bytes.CountValue(value);
                }
                if (row.HasExplicitId) AddRowMember("_id", JsonValue.Create(row.Id));
                foreach (var (key, value) in row.Fields) AddRowMember(key, value);
                bytes.Add(1); // object closing brace
            }
            bytes.Add(1); // array closing brace
        }
        bytes.Add(1); // root object closing brace

        // A host may compose a new object/array from separately captured leaves. Only
        // brand those mutable containers after provenance and the complete envelope pass.
        foreach (var container in composedContainers) TrustedNodes.GetValue(container, _ => TrustedMarker);

    }

    /// <summary>Counts the UTF-8 bytes that ECMAScript <c>JSON.stringify</c> would emit without materializing JSON.</summary>
    private sealed class JsonStringifyCounter
    {
        private readonly int _maximum;
        private int _count;

        public JsonStringifyCounter(int maximum)
        {
            _maximum = maximum;
        }

        public void Add(int count)
        {
            if (count < 0 || count > _maximum - _count)
                throw new ArgumentException("Rule context exceeds the UTF-8 byte envelope.");
            _count += count;
        }

        public void CountValue(JsonNode? node)
        {
            if (node is null) { Add(4); return; }
            switch (node)
            {
                case JsonObject obj:
                    Add(1);
                    var firstObjectMember = true;
                    foreach (var (name, value) in obj)
                    {
                        if (!firstObjectMember) Add(1);
                        CountString(name);
                        Add(1);
                        CountValue(value);
                        firstObjectMember = false;
                    }
                    Add(1);
                    return;
                case JsonArray array:
                    Add(1);
                    var firstElement = true;
                    foreach (var value in array)
                    {
                        if (!firstElement) Add(1);
                        CountValue(value);
                        firstElement = false;
                    }
                    Add(1);
                    return;
                case JsonValue value:
                    CountScalar(value);
                    return;
                default:
                    throw new InvalidOperationException(RuleEngineCodes.ContextSnapshotRequired);
            }
        }

        public void CountString(string value)
        {
            Add(2); // quotes
            for (var index = 0; index < value.Length; index++)
            {
                var character = value[index];
                switch (character)
                {
                    case '"':
                    case '\\':
                    case '\b':
                    case '\f':
                    case '\n':
                    case '\r':
                    case '\t':
                        Add(2);
                        break;
                    default:
                        if (character < 0x20) Add(6);
                        else if (character < 0x80) Add(1);
                        else if (character < 0x800) Add(2);
                        else if (char.IsHighSurrogate(character) && index + 1 < value.Length && char.IsLowSurrogate(value[index + 1]))
                        {
                            Add(4);
                            index++;
                        }
                        else if (char.IsSurrogate(character)) Add(6); // well-formed JSON.stringify escapes lone surrogates
                        else Add(3);
                        break;
                }
            }
        }

        private void CountScalar(JsonValue value)
        {
            switch (value.GetValueKind())
            {
                case JsonValueKind.String:
                    CountString(value.GetValue<string>());
                    return;
                case JsonValueKind.True:
                    Add(4);
                    return;
                case JsonValueKind.False:
                    Add(5);
                    return;
                case JsonValueKind.Number:
                    CountNumber(value);
                    return;
                case JsonValueKind.Null:
                    Add(4);
                    return;
                default:
                    throw new InvalidOperationException(RuleEngineCodes.ContextSnapshotRequired);
            }
        }

        private void CountNumber(JsonValue value)
        {
            // JsonValue preserves the CLR numeric type for safe host captures. Normalize
            // each through the existing ECMAScript number formatter; parsed JSON numbers
            // arrive through the double branch and retain the same rule.
            if (value.TryGetValue<sbyte>(out var signedByte)) { Add(CanonicalNumber.ToJsonString((long)signedByte).Length); return; }
            if (value.TryGetValue<byte>(out var unsignedByte)) { Add(CanonicalNumber.ToJsonString((long)unsignedByte).Length); return; }
            if (value.TryGetValue<short>(out var shortInteger)) { Add(CanonicalNumber.ToJsonString((long)shortInteger).Length); return; }
            if (value.TryGetValue<ushort>(out var unsignedShort)) { Add(CanonicalNumber.ToJsonString((long)unsignedShort).Length); return; }
            if (value.TryGetValue<int>(out var integer)) { Add(CanonicalNumber.ToJsonString((long)integer).Length); return; }
            if (value.TryGetValue<long>(out var longInteger)) { Add(CanonicalNumber.ToJsonString(longInteger).Length); return; }
            if (value.TryGetValue<uint>(out var unsignedInteger)) { Add(CanonicalNumber.ToJsonString((long)unsignedInteger).Length); return; }
            if (value.TryGetValue<ulong>(out var unsignedLong)) { Add(CanonicalNumber.ToJsonString((double)unsignedLong).Length); return; }
            if (value.TryGetValue<double>(out var number)) { CountDouble(number); return; }
            // Parsed JsonElement numbers can satisfy both float and double. Probe the
            // non-lossy double representation first: 1.2 must not become 1.2000000476837158.
            if (value.TryGetValue<float>(out var single)) { CountDouble(single); return; }
            if (value.TryGetValue<decimal>(out var decimalNumber)) { CountDouble((double)decimalNumber); return; }
            throw new InvalidOperationException(RuleEngineCodes.ContextSnapshotRequired);
        }

        private void CountDouble(double number)
        {
            if (!double.IsFinite(number)) Add(4); // JSON.stringify serializes non-finite Numbers as null.
            else Add(CanonicalNumber.ToJsonString(number).Length);
        }
    }

    /// <summary>Explicit host adaptation for a JSON node; never called by graph evaluation.</summary>
    internal static JsonNode? CaptureHostValue(JsonNode? value)
    {
        if (value is null) return null;
        if (value is not JsonValue jsonValue || !IsSafeHostValue(jsonValue))
            throw new InvalidOperationException(RuleEngineCodes.ContextSnapshotRequired);
        MeasureHostValue(value);
        return CaptureParsedValue(value);
    }

    internal static RuleRow CreateCapturedRow(string id, Dictionary<string, JsonNode?> fields, bool hasExplicitId = true)
        => new(id, fields, hasExplicitId);

    internal static JsonNode? CaptureParsedValue(JsonNode? value)
    {
        return value is null ? null : MarkAndReturn(NormalizeParsedValue(value));
    }

    // JsonElement-backed JsonValue throws when GetValue<string>() is asked for a legal
    // JSON escaped lone surrogate. Move parsed values into ordinary owned JsonNodes at
    // the capture boundary, preserving the UTF-16 code unit that JSON.stringify escapes.
    private static JsonNode NormalizeParsedValue(JsonNode value) => value switch
    {
        JsonObject obj => new JsonObject(obj.Select(pair => KeyValuePair.Create(pair.Key,
            pair.Value is null ? null : NormalizeParsedValue(pair.Value)))),
        JsonArray array => new JsonArray(array.Select(item => item is null ? null : NormalizeParsedValue(item)).ToArray()),
        // Only JsonElement-backed values came from parsed JSON and need the token
        // decoder for escaped lone surrogates.  Safe host CLR strings are already
        // values: routing them through ToJsonString would allow the framework to
        // replace an unpaired UTF-16 code unit before we capture it.
        JsonValue scalar when scalar.GetValueKind() == JsonValueKind.String && scalar.TryGetValue<JsonElement>(out var element)
            => JsonValue.Create(ReadJsonString(element.GetRawText()))!,
        JsonValue scalar when scalar.GetValueKind() == JsonValueKind.String => JsonValue.Create(scalar.GetValue<string>())!,
        _ => value.DeepClone(),
    };

    private static string ReadJsonString(string json)
    {
        var result = new System.Text.StringBuilder();
        for (var index = 1; index < json.Length - 1; index++)
        {
            var character = json[index];
            if (character != '\\') { result.Append(character); continue; }
            var escapeCode = json[++index];
            result.Append(escapeCode switch
            {
                '"' => '"', '\\' => '\\', '/' => '/', 'b' => '\b', 'f' => '\f', 'n' => '\n', 'r' => '\r', 't' => '\t',
                'u' => (char)Convert.ToInt32(json.Substring(index += 1, 4), 16),
                _ => throw new ArgumentException("Invalid JSON string escape."),
            });
            if (escapeCode == 'u') index += 3;
        }
        return result.ToString();
    }

    internal static JsonNode? CloneTrusted(JsonNode? value)
    {
        if (value is null) return null;
        EnsureTrusted(value);
        return MarkAndReturn(value.DeepClone());
    }

    private static JsonNode MarkAndReturn(JsonNode value)
    {
        MarkTrusted(value);
        return value;
    }

    private static void MarkTrusted(JsonNode node)
    {
        TrustedNodes.GetValue(node, _ => TrustedMarker);
        switch (node)
        {
            case JsonObject obj:
                foreach (var (_, child) in obj) if (child is not null) MarkTrusted(child);
                break;
            case JsonArray array:
                foreach (var child in array) if (child is not null) MarkTrusted(child);
                break;
        }
    }

    private static void EnsureTrusted(JsonNode node)
    {
        if (!TrustedNodes.TryGetValue(node, out _))
            throw new InvalidOperationException(RuleEngineCodes.ContextSnapshotRequired);
    }

    private static bool IsSafeHostValue(JsonValue value)
        => !value.GetType().Name.StartsWith("JsonValueCustomized", StringComparison.Ordinal)
            && value.GetValueKind() is not (JsonValueKind.Object or JsonValueKind.Array or JsonValueKind.Undefined);

    private static void ValidateHostObject(JsonObject json)
    {
        var nodes = 0;
        void Visit(JsonNode? node, int depth)
        {
            if (++nodes > RuntimeInputEnvelope.MaxNodes)
                throw new ArgumentException("Rule context exceeds the node envelope.", nameof(json));
            switch (node)
            {
                case null:
                    return;
                case JsonValue value when IsSafeHostValue(value):
                    return;
                case JsonValue:
                    throw new InvalidOperationException(RuleEngineCodes.ContextSnapshotRequired);
                case JsonObject obj:
                    if (depth > RuntimeInputEnvelope.MaxDepth)
                        throw new ArgumentException("Rule context exceeds the bounded structure envelope.", nameof(json));
                    foreach (var (key, child) in obj)
                    {
                        RuntimeInputEnvelope.ValidateMemberName(key, nameof(json));
                        Visit(child, depth + 1);
                    }
                    return;
                case JsonArray array:
                    if (depth > RuntimeInputEnvelope.MaxDepth)
                        throw new ArgumentException("Rule context exceeds the bounded structure envelope.", nameof(json));
                    foreach (var child in array) Visit(child, depth + 1);
                    return;
                default:
                    throw new InvalidOperationException(RuleEngineCodes.ContextSnapshotRequired);
            }
        }

        Visit(json, 1);
        MeasureHostValue(json);
    }

    private static void MeasureHostValue(JsonNode value)
    {
        // Validation always runs first, so this pass never invokes a host converter.
        var counter = new JsonStringifyCounter(RuntimeInputEnvelope.MaxUtf8Bytes);
        counter.CountValue(value);
    }
}

using System.Globalization;

namespace Harborline.Foundation.RuleEngine;

/// <summary>
/// Faithful ECMAScript <c>ToNumber(String)</c> (ECMA-262 §7.1.4.1.1) — the exact
/// semantics the TS tier gets from <c>Number(trimmed)</c> after a non-empty trim
/// (SPINE-1 cross-tier guarantee; finding F2). Replaces the prior
/// <c>double.TryParse(s, NumberStyles.Any, …)</c>, which diverged from JS by
/// <b>accepting</b> thousands separators (<c>"1,000"</c> → 1000), parenthesised
/// negatives (<c>"(5)"</c> → -5) and currency symbols, and by <b>rejecting</b>
/// JS-valid radix literals (<c>"0x1F"</c> → 31). String field values are user data,
/// so a benign arithmetic/compare rule over them must coerce identically on both tiers.
/// </summary>
internal static class JsNumber
{
    /// <summary>
    /// Parses <paramref name="input"/> as the TS tier's <c>toNumber</c>/<c>coerceNumber</c>
    /// would: trim ECMAScript whitespace; an empty/whitespace-only result is NOT a number;
    /// otherwise apply the StringNumericLiteral grammar; a NaN or non-finite result is NOT a
    /// number. Returns <see langword="false"/> for every input the TS tier rejects.
    /// </summary>
    public static bool TryParse(string? input, out double value)
    {
        value = 0;
        if (input is null) return false;
        int start = 0, end = input.Length;
        while (start < end && IsJsSpace(input[start])) start++;
        while (end > start && IsJsSpace(input[end - 1])) end--;
        if (start == end) return false;                 // empty / whitespace-only → not a number
        if (!ParseLiteral(input[start..end], out value)) return false;
        return double.IsFinite(value);                  // Infinity / NaN → not a number (TS isFinite guard)
    }

    private static bool ParseLiteral(string s, out double value)
    {
        value = 0;

        // Non-decimal radix literals carry NO sign in ECMAScript Number(string).
        if (s.Length > 2 && s[0] == '0')
        {
            int radix = s[1] switch { 'x' or 'X' => 16, 'o' or 'O' => 8, 'b' or 'B' => 2, _ => 0 };
            if (radix != 0) return TryRadix(s[2..], radix, out value);
        }

        int i = 0;
        double sign = 1;
        if (s[0] == '+') i = 1;
        else if (s[0] == '-') { sign = -1; i = 1; }
        string rest = s[i..];
        if (rest.Length == 0) return false;
        if (rest == "Infinity") { value = sign * double.PositiveInfinity; return true; }

        // Decimal literal only — NO thousands separators, parentheses, currency, or whitespace.
        const NumberStyles styles = NumberStyles.AllowDecimalPoint | NumberStyles.AllowExponent;
        if (double.TryParse(rest, styles, CultureInfo.InvariantCulture, out var d) && !double.IsNaN(d))
        {
            value = sign * d;
            return true;
        }
        return false;
    }

    private static bool TryRadix(string digits, int radix, out double value)
    {
        value = 0;
        if (digits.Length == 0) return false;
        double acc = 0;
        foreach (char c in digits)
        {
            int dv = DigitValue(c);
            if (dv < 0 || dv >= radix) return false;
            acc = acc * radix + dv;
        }
        value = acc;
        return true;
    }

    private static int DigitValue(char c)
        => c is >= '0' and <= '9' ? c - '0'
         : c is >= 'a' and <= 'f' ? c - 'a' + 10
         : c is >= 'A' and <= 'F' ? c - 'A' + 10
         : -1;

    private static bool IsJsSpace(char c) => char.IsWhiteSpace(c) || c == '\uFEFF';
}

namespace Harborline.Foundation.RuleEngine.Model;

/// <summary>
/// The grain of an <see cref="CellAddress"/> — which kind of addressable cell
/// a rule targets or references (SPINE-1 design §2.1).
/// </summary>
public enum CellKind
{
    /// <summary>A top-level form field — <c>field:&lt;name&gt;</c>.</summary>
    Field = 0,

    /// <summary>A child-table row's cell — <c>row:&lt;sectionId&gt;/&lt;rowId&gt;/&lt;field&gt;</c>.</summary>
    Row = 1,

    /// <summary>A table aggregate pseudo-cell — <c>agg:&lt;sectionId&gt;/&lt;fn&gt;/&lt;col&gt;</c>.</summary>
    TableAggregate = 2,

    /// <summary>A section-scoped pseudo-cell (e.g. whole-section visibility) — <c>section:&lt;id&gt;</c>.</summary>
    Section = 3,

    /// <summary>The whole-schema pseudo-cell — <c>schema:</c>.</summary>
    Schema = 4,
}

/// <summary>
/// An addressable cell in a form instance's dependency graph (SPINE-1 design
/// §2.1). The node identity of the graph evaluator. Value-equal + ordered by its
/// canonical <see cref="Key"/> so it can key a dictionary and serialize stably.
/// </summary>
/// <remarks>
/// The canonical string form (<see cref="Key"/>) is the single cross-tier key used
/// in the conformance corpus' <c>expectedOutcomes</c> map; the TS engine produces
/// byte-identical keys.
/// </remarks>
public readonly record struct CellAddress
{
    private CellAddress(CellKind kind, string sectionId, string rowId, string name)
    {
        Kind = kind;
        SectionId = sectionId;
        RowId = rowId;
        Name = name;
    }

    /// <summary>The cell grain.</summary>
    public CellKind Kind { get; }

    /// <summary>Owning child-table section id (Row / TableAggregate / Section); else empty.</summary>
    public string SectionId { get; }

    /// <summary>Stable row id within the child table (Row only); else empty.</summary>
    public string RowId { get; }

    /// <summary>
    /// Field name (Field / Row), aggregate <c>"&lt;fn&gt;/&lt;col&gt;"</c> tail (TableAggregate);
    /// else empty.
    /// </summary>
    public string Name { get; }

    /// <summary>A top-level field cell.</summary>
    public static CellAddress Field(string name) => new(CellKind.Field, "", "", name);

    /// <summary>A child-table row cell.</summary>
    public static CellAddress Row(string sectionId, string rowId, string field)
        => new(CellKind.Row, sectionId, rowId, field);

    /// <summary>A table-aggregate pseudo-cell (<paramref name="fn"/> over <paramref name="col"/>).</summary>
    public static CellAddress TableAggregate(string sectionId, string fn, string col)
        => new(CellKind.TableAggregate, sectionId, "", fn + "/" + col);

    /// <summary>A section-scoped pseudo-cell.</summary>
    public static CellAddress Section(string sectionId) => new(CellKind.Section, sectionId, "", "");

    /// <summary>The whole-schema pseudo-cell.</summary>
    public static CellAddress Schema() => new(CellKind.Schema, "", "", "");

    /// <summary>
    /// The canonical, stable string key (cross-tier identical). Forms:
    /// <c>field:name</c>, <c>row:section/rowId/field</c>, <c>agg:section/fn/col</c>,
    /// <c>section:id</c>, <c>schema:</c>.
    /// </summary>
    public string Key => Kind switch
    {
        CellKind.Field => "field:" + Name,
        CellKind.Row => "row:" + SectionId + "/" + RowId + "/" + Name,
        CellKind.TableAggregate => "agg:" + SectionId + "/" + Name,
        CellKind.Section => "section:" + SectionId,
        CellKind.Schema => "schema:",
        _ => "?:",
    };

    /// <inheritdoc />
    public override string ToString() => Key;
}

using System.Text.Json.Nodes;

namespace Harborline.Foundation.RuleEngine.Model;

/// <summary>
/// The output-type taxonomy of a <see cref="RuleOutcome"/> (SPINE-1 design §1.3).
/// Maps onto <see cref="Harborline.Contracts.Forms.RuleActionKind"/>:
/// <c>Compute → Value</c>, <c>Validate → Validity</c>,
/// <c>Visibility/Required/ReadOnly → Visibility</c>, <c>Presentation → Presentation</c>.
/// </summary>
public enum OutputType
{
    /// <summary>A computed value (<c>Compute</c>) — carries <see cref="RuleOutcome.Value"/>.</summary>
    Value = 0,

    /// <summary>A validation verdict (<c>Validate</c>) — carries <see cref="RuleOutcome.Validity"/>.</summary>
    Validity = 1,

    /// <summary>Show/hide/required/readonly state — carries <see cref="RuleOutcome.Visibility"/>.</summary>
    Visibility = 2,

    /// <summary>Style/badge/severity hint — carries <see cref="RuleOutcome.Presentation"/>.</summary>
    Presentation = 3,

    /// <summary>The available options of a choice field (<c>set-options</c>) — carries
    /// <see cref="RuleOutcome.Options"/>. The additive fifth OutputType (ADR 0140 D1 amendment;
    /// built ADR 0146 D2 Wave-1).</summary>
    Options = 4,
}

/// <summary>
/// State of a <see cref="ComputedValue"/> (SPINE-1 design §1.3, Decision DE).
/// </summary>
public enum ValueState
{
    /// <summary>The computed value is available (<see cref="ComputedValue.Value"/> populated).</summary>
    Resolved = 0,

    /// <summary>The rule threw (type error, division-by-zero) or read an upstream <see cref="Error"/>;
    /// errors propagate transitively.</summary>
    Error = 1,

    /// <summary>A dependency is not yet available. <b>Client-tier only</b>: a <see cref="Pending"/>
    /// reaching the synchronous .NET integrity tier at save is a fail-closed validation error.</summary>
    Pending = 2,
}

/// <summary>Severity of a <see cref="PresentationOutcome"/>.</summary>
public enum Severity
{
    /// <summary>Informational.</summary>
    Info = 0,

    /// <summary>Warning.</summary>
    Warn = 1,

    /// <summary>Error-level presentation (distinct from a hard <see cref="OutputType.Validity"/> failure).</summary>
    Error = 2,
}

/// <summary>
/// A localizable rule error — a stable <see cref="Code"/> + interpolation
/// <see cref="Params"/>, never English prose (memory: validation errors are codes).
/// The client keys a translated template off <see cref="Code"/>.
/// </summary>
/// <param name="Code">Stable, locale-independent error code (e.g. <c>rule.div_by_zero</c>,
/// <c>rule.type_error</c>, <c>rule.upstream_error</c>, <c>rule.cycle</c>, or a rule id for a
/// <c>Validate</c> failure).</param>
/// <param name="Params">Stringified interpolation parameters (the existing forms
/// <c>ValidationError.params</c> convention — scalars only).</param>
public sealed record RuleError(string Code, IReadOnlyDictionary<string, string> Params)
{
    /// <summary>An error with a code and no parameters.</summary>
    public static RuleError Of(string code) => new(code, EmptyParams);

    /// <summary>An error with a code and one parameter.</summary>
    public static RuleError Of(string code, string key, string value)
        => new(code, new Dictionary<string, string> { [key] = value });

    internal static readonly IReadOnlyDictionary<string, string> EmptyParams
        = new Dictionary<string, string>();
}

/// <summary>
/// A computed value outcome (SPINE-1 design §1.3). Exactly one of
/// <see cref="Value"/> / <see cref="Error"/> is populated per <see cref="State"/>.
/// </summary>
public sealed record ComputedValue(ValueState State, JsonNode? Value = null, RuleError? Error = null)
{
    /// <summary>A resolved value.</summary>
    public static ComputedValue Resolved(JsonNode? value) => new(ValueState.Resolved, value);

    /// <summary>An error value (propagating).</summary>
    public static ComputedValue OfError(RuleError error) => new(ValueState.Error, Error: error);

    /// <summary>A pending value (client tier only).</summary>
    public static ComputedValue OfPending() => new(ValueState.Pending);
}

/// <summary>A validation verdict (SPINE-1 design §1.3). <paramref name="Error"/> is null iff valid.</summary>
public sealed record Validity(bool Ok, RuleError? Error = null)
{
    /// <summary>A passing verdict.</summary>
    public static Validity Valid { get; } = new(true);

    /// <summary>A failing verdict carrying a localizable code.</summary>
    public static Validity Invalid(RuleError error) => new(false, error);
}

/// <summary>
/// The merged show/hide/required/readonly state for a cell (SPINE-1 design §1.3).
/// Defaults: visible, not-required, not-readonly.
/// </summary>
public sealed record VisibilityState(bool Visible = true, bool Required = false, bool ReadOnly = false);

/// <summary>A presentation hint outcome (SPINE-1 Decision DA).</summary>
public sealed record PresentationOutcome(
    Severity? Severity = null,
    Harborline.Contracts.Forms.InternationalizedText? Badge = null,
    string? StyleToken = null);

/// <summary>
/// The available-options outcome of a <c>set-options</c> rule (ADR 0146 D2 Wave-1). Mirrors
/// <see cref="ComputedValue"/>'s state machine: exactly one of <see cref="Options"/> /
/// <see cref="Error"/> is populated per <see cref="State"/>. The engine evaluates the rule's
/// expression to a JSON value; a JSON array resolves to its elements, any other type fails closed
/// with <see cref="RuleEngineCodes.OptionsNotArray"/>. Option <i>labelling</i> (i18n) is a
/// renderer/i18n-cascade concern, not a rule-engine one — the outcome carries raw JSON option values.
/// </summary>
public sealed record OptionsOutcome(ValueState State, IReadOnlyList<JsonNode?>? Options = null, RuleError? Error = null)
{
    /// <summary>A resolved options list.</summary>
    public static OptionsOutcome Resolved(IReadOnlyList<JsonNode?> options) => new(ValueState.Resolved, options);

    /// <summary>An error outcome (propagating; e.g. a non-array expression or an upstream error).</summary>
    public static OptionsOutcome OfError(RuleError error) => new(ValueState.Error, Error: error);

    /// <summary>A pending outcome (client tier only — a dependency is not yet available).</summary>
    public static OptionsOutcome OfPending() => new(ValueState.Pending);
}

/// <summary>
/// The single neutral evaluation result both tiers emit (SPINE-1 design §1.3).
/// Exactly one payload is populated, keyed by <see cref="OutputType"/>.
/// </summary>
public sealed record RuleOutcome
{
    private RuleOutcome(string ruleId, CellAddress target, OutputType outputType)
    {
        RuleId = ruleId;
        Target = target;
        OutputType = outputType;
    }

    /// <summary>The rule that produced this outcome.</summary>
    public string RuleId { get; private init; }

    /// <summary>The cell this outcome applies to (Row rules resolve per-row).</summary>
    public CellAddress Target { get; private init; }

    /// <summary>Which payload is populated.</summary>
    public OutputType OutputType { get; private init; }

    /// <summary>Populated iff <see cref="OutputType"/> is <see cref="OutputType.Value"/>.</summary>
    public ComputedValue? Value { get; private init; }

    /// <summary>Populated iff <see cref="OutputType"/> is <see cref="OutputType.Validity"/>.</summary>
    public Validity? Validity { get; private init; }

    /// <summary>Populated iff <see cref="OutputType"/> is <see cref="OutputType.Visibility"/>.</summary>
    public VisibilityState? Visibility { get; private init; }

    /// <summary>Populated iff <see cref="OutputType"/> is <see cref="OutputType.Presentation"/>.</summary>
    public PresentationOutcome? Presentation { get; private init; }

    /// <summary>Populated iff <see cref="OutputType"/> is <see cref="OutputType.Options"/>.</summary>
    public OptionsOutcome? Options { get; private init; }

    /// <summary>A <see cref="OutputType.Value"/> outcome.</summary>
    public static RuleOutcome OfValue(string ruleId, CellAddress target, ComputedValue value)
        => new(ruleId, target, OutputType.Value) { Value = value };

    /// <summary>A <see cref="OutputType.Validity"/> outcome.</summary>
    public static RuleOutcome OfValidity(string ruleId, CellAddress target, Validity validity)
        => new(ruleId, target, OutputType.Validity) { Validity = validity };

    /// <summary>A <see cref="OutputType.Visibility"/> outcome.</summary>
    public static RuleOutcome OfVisibility(string ruleId, CellAddress target, VisibilityState visibility)
        => new(ruleId, target, OutputType.Visibility) { Visibility = visibility };

    /// <summary>A <see cref="OutputType.Presentation"/> outcome.</summary>
    public static RuleOutcome OfPresentation(string ruleId, CellAddress target, PresentationOutcome presentation)
        => new(ruleId, target, OutputType.Presentation) { Presentation = presentation };

    /// <summary>A <see cref="OutputType.Options"/> outcome.</summary>
    public static RuleOutcome OfOptions(string ruleId, CellAddress target, OptionsOutcome options)
        => new(ruleId, target, OutputType.Options) { Options = options };
}

