/// <summary>An exact pin: name, concrete version and digest. Nothing floats.</summary>
public sealed record ExactPin(string Name, string Version, string Digest);

/// <summary>A refused reference, by stable code.</summary>
public sealed class NamedReferenceException(string code, string message) : Exception(message)
{
    /// <summary>The stable refusal code.</summary>
    public string Code { get; } = code;
}

/// <summary>
/// An immutable, Rules-owned named predicate (DES-0018 <c>rules-ck-22</c>): authored once, reused by
/// view filters, rule conditions, automation conditions and report populations, each of which stores
/// only its <see cref="Pin"/>. The expression is admitted by the compiler when the predicate is made.
/// </summary>
public sealed record NamedPredicate
{
    /// <summary>Creates the predicate; refuses a floating version or an expression the compiler rejects.</summary>
    public NamedPredicate(string name, string version, string expression)
    {
        Name = NamedReferences.Exact(name, version).Name;
        Version = version;
        Expression = NamedReferences.Canonical(expression);
        RuleCompiler.Compile([NamedReferences.Rule("predicate:" + name, Expression, RuleActionKind.Validate)]);
        Pin = new ExactPin(Name, Version, NamedReferences.Digest("predicate", Name, Version, Expression));
    }

    /// <summary>The reference's name.</summary>
    public string Name { get; }
    /// <summary>The exact version; never floating.</summary>
    public string Version { get; }
    /// <summary>The canonical JSON of the admitted JsonLogic expression.</summary>
    public string Expression { get; }
    /// <summary>The exact pin a consumer stores: name, version and a digest of the canonical expression.</summary>
    public ExactPin Pin { get; }
}

/// <summary>
/// A named calculation (DES-0018 <c>rules-ck-23</c>, ADR 0033): a substrate under Rules, referenced by
/// exact pin and never inlined. <see cref="NamedReferences.Compute"/> is a pure call that returns its value.
/// </summary>
public sealed record NamedCalculation
{
    /// <summary>Creates the calculation; refuses a floating version or an expression the compiler rejects.</summary>
    public NamedCalculation(string name, string version, string expression)
    {
        Name = NamedReferences.Exact(name, version).Name;
        Version = version;
        Expression = NamedReferences.Canonical(expression);
        RuleCompiler.Compile([NamedReferences.Rule("calculation:" + name, Expression, RuleActionKind.Compute)]);
        Pin = new ExactPin(Name, Version, NamedReferences.Digest("calculation", Name, Version, Expression));
    }

    /// <summary>The reference's name.</summary>
    public string Name { get; }
    /// <summary>The exact version; never floating.</summary>
    public string Version { get; }
    /// <summary>The canonical JSON of the admitted JsonLogic expression.</summary>
    public string Expression { get; }
    /// <summary>The exact pin a consumer stores: name, version and a digest of the canonical expression.</summary>
    public ExactPin Pin { get; }
}

/// <summary>
/// A cited legality rule set (DES-0018 <c>rules-ck-24</c>): sealed, jurisdiction-scoped, effective-dated
/// and package-owned. Rules carries the citation and its provenance; it has no body to evaluate and
/// nothing here interprets it.
/// </summary>
public sealed record LegalityRuleSetCitation
{
    /// <summary>
    /// Creates the citation; throws <see cref="NamedReferenceException"/> with <see cref="NamedReferences.Floating"/> for a
    /// non-exact version, or <see cref="NamedReferences.Malformed"/> for a blank package or jurisdiction, a digest that is not
    /// 64 hex characters, or an end date before the start.
    /// </summary>
    public LegalityRuleSetCitation(string packageId, string name, string version, string digest, string jurisdiction,
        DateOnly effectiveFrom, DateOnly? effectiveTo)
    {
        NamedReferences.Exact(name, version);
        if (string.IsNullOrWhiteSpace(packageId) || string.IsNullOrWhiteSpace(jurisdiction)
            || digest is not { Length: 64 } || !digest.All(Uri.IsHexDigit) || effectiveTo < effectiveFrom)
            throw new NamedReferenceException(NamedReferences.Malformed, "a legality citation needs a package, jurisdiction, 64-hex digest and ordered dates");
        (PackageId, Pin, Jurisdiction, EffectiveFrom, EffectiveTo) = (packageId, new ExactPin(name, version, digest), jurisdiction, effectiveFrom, effectiveTo);
    }

    /// <summary>The package that owns the rule set.</summary>
    public string PackageId { get; }
    /// <summary>The rule set's exact name, version and package-supplied digest.</summary>
    public ExactPin Pin { get; }
    /// <summary>The jurisdiction the rule set governs.</summary>
    public string Jurisdiction { get; }
    /// <summary>The first day the rule set applies.</summary>
    public DateOnly EffectiveFrom { get; }
    /// <summary>The last day the rule set applies; null when open-ended.</summary>
    public DateOnly? EffectiveTo { get; }

    /// <summary>Canonical JSON preserving provenance, dates and jurisdiction.</summary>
    public string CanonicalJson => new JsonObject
    {
        ["digest"] = Pin.Digest,
        ["effectiveFrom"] = EffectiveFrom.ToString("O"),
        ["effectiveTo"] = EffectiveTo?.ToString("O"),
        ["jurisdiction"] = Jurisdiction,
        ["name"] = Pin.Name,
        ["packageId"] = PackageId,
        ["version"] = Pin.Version,
    }.ToJsonString();
}

/// <summary>What a named predicate is reused by (<c>rules-auth-9</c>).</summary>
public enum PredicateConsumer
{
    /// <summary>A view's row filter.</summary>
    ViewFilter,
    /// <summary>A rule's condition.</summary>
    RuleCondition,
    /// <summary>An automation's trigger condition.</summary>
    AutomationCondition,
    /// <summary>A report's population filter.</summary>
    ReportPopulation,
    /// <summary>A Layout block's <c>show_when</c> guard (DES-0052 <c>layout-ck-29</c>, T-724 ruling 72).</summary>
    LayoutGuard,
}

/// <summary>
/// The immutable dependency closure a signed definition was published with. Consumers resolve their
/// pins here and only here, never against the live catalogue.
/// </summary>
public sealed class PinnedClosure
{
    private readonly Dictionary<(string, string), NamedPredicate> _predicates;
    private readonly Dictionary<(string, string), NamedCalculation> _calculations;

    /// <summary>Freezes the closure; a duplicate name and version throws <see cref="ArgumentException"/>.</summary>
    public PinnedClosure(IEnumerable<NamedPredicate> predicates, IEnumerable<NamedCalculation> calculations)
    {
        _predicates = predicates.ToDictionary(p => (p.Name, p.Version));
        _calculations = calculations.ToDictionary(c => (c.Name, c.Version));
    }

    internal NamedPredicate Predicate(ExactPin pin) => Verify(pin, _predicates.GetValueOrDefault((pin.Name, pin.Version)), p => p.Pin);

    internal NamedCalculation Calculation(ExactPin pin) => Verify(pin, _calculations.GetValueOrDefault((pin.Name, pin.Version)), c => c.Pin);

    private static T Verify<T>(ExactPin pin, T? found, Func<T, ExactPin> pinOf) where T : class
    {
        NamedReferences.Exact(pin.Name, pin.Version);
        if (found is null) throw new NamedReferenceException(NamedReferences.Unresolved, $"{pin.Name}@{pin.Version} is not in the pinned closure");
        if (pinOf(found).Digest != pin.Digest) throw new NamedReferenceException(NamedReferences.DigestMismatch, $"{pin.Name}@{pin.Version} digest differs from the pin");
        return found;
    }
}

/// <summary>Resolution of named predicates and calculations through exact pins.</summary>
public static class NamedReferences
{
    /// <summary>A version is blank or floating (<c>latest</c>, <c>*</c>, <c>^</c>, <c>~</c>).</summary>
    public const string Floating = "rule.reference.floating";
    /// <summary>A pin names a version absent from the pinned closure.</summary>
    public const string Unresolved = "rule.reference.unresolved";
    /// <summary>A pin's digest differs from the closure entry's digest.</summary>
    public const string DigestMismatch = "rule.reference.digest_mismatch";
    /// <summary>A reference is missing a name, its expression is not JSON, or a citation's fields are invalid.</summary>
    public const string Malformed = "rule.reference.malformed";

    /// <summary>
    /// The guard a consumer evaluates for its pinned predicate. The same pin yields the same rule for every
    /// consumer kind; the consumer's own admission still governs evaluation.
    /// </summary>
    public static RuleDefinition Bind(PredicateConsumer consumer, ExactPin pin, PinnedClosure closure)
    {
        var predicate = closure.Predicate(pin);
        return Rule($"{consumer}:{pin.Name}@{pin.Version}", predicate.Expression, RuleActionKind.Validate);
    }

    /// <summary>
    /// <c>Compute</c> as a pure call (owner ruling 2026-09-21): resolves the exact calculation pin from the
    /// closure and returns its typed value over the caller's inert snapshot. It writes nothing and accepts
    /// no inline expression.
    /// </summary>
    public static ComputedValue Compute(ExactPin pin, PinnedClosure closure, IGuardEvaluator evaluator,
        RuleContextSnapshot context, EvaluationAdmission admission, CancellationToken ct = default)
    {
        var calculation = closure.Calculation(pin);
        return evaluator.EvaluateValue(Rule($"calculation:{pin.Name}@{pin.Version}", calculation.Expression, RuleActionKind.Compute),
            context, RuleEvalScope.Root, admission, ct);
    }

    internal static ExactPin Exact(string name, string version)
    {
        if (string.IsNullOrWhiteSpace(name)) throw new NamedReferenceException(Malformed, "a named reference needs a name");
        if (string.IsNullOrWhiteSpace(version) || version is "latest" or "*" || version.Contains('*') || version.Contains('^') || version.Contains('~'))
            throw new NamedReferenceException(Floating, $"'{version}' is not an exact version");
        return new ExactPin(name, version, "");
    }

    internal static string Canonical(string expression)
    {
        try { return Sort(JsonNode.Parse(expression))?.ToJsonString() ?? "null"; }
        catch (JsonException) { throw new NamedReferenceException(Malformed, "the expression is not JSON"); }
    }

    internal static string Digest(string kind, string name, string version, string expression)
        => Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(
            new JsonObject { ["expression"] = JsonNode.Parse(expression), ["kind"] = kind, ["name"] = name, ["version"] = version }.ToJsonString())));

    internal static RuleDefinition Rule(string id, string expression, RuleActionKind action) => new()
    {
        Id = id, Tier = RuleTier.JsonLogic, Scope = RuleScope.Schema, ScopeTarget = "", Expression = expression, Action = action,
    };

    private static JsonNode? Sort(JsonNode? node) => node switch
    {
        JsonObject obj => new JsonObject(obj.OrderBy(p => p.Key, StringComparer.Ordinal).Select(p => KeyValuePair.Create(p.Key, Sort(p.Value)))),
        JsonArray arr => new JsonArray(arr.Select(Sort).ToArray()),
        _ => node?.DeepClone(),
    };
}

using Harborline.Foundation.RuleEngine.Compilation;

namespace Harborline.Foundation.RuleEngine.Registry;

/// <summary>
/// Thrown when a compile/cache swap would install a STALE (downgrade) compiled AST over a newer one
/// already cached for the same key — the reject-stale half of the S-8 watermark (ADR 0146 D5).
/// </summary>
public sealed class StaleRulePublishException : Exception
{
    /// <summary>Constructs the exception with the cache key + the stale and current versions.</summary>
    public StaleRulePublishException(string cacheKey, string staleVersion, string currentVersion)
        : base($"rule compile cache '{cacheKey}': refused a stale publish (version '{staleVersion}' is below the cached tip '{currentVersion}')")
    {
        CacheKey = cacheKey;
        StaleVersion = staleVersion;
        CurrentVersion = currentVersion;
    }

    /// <summary>The <c>(tenant, rule-key)</c> cache key.</summary>
    public string CacheKey { get; }

    /// <summary>The rejected (stale) version.</summary>
    public string StaleVersion { get; }

    /// <summary>The cached tip version that stands.</summary>
    public string CurrentVersion { get; }
}

/// <summary>
/// The per-node compiled-AST cache with the HomeEpochFence read-tip-reject-stale discipline
/// (ADR 0146 D5). A compile/cache swap for a rule key is MONOTONIC: reading the currently cached tip
/// version under the SAME critical section as the swap, a publish whose version is a downgrade of
/// the cached tip is REJECTED — so a stale publish arriving late can never overwrite a newer,
/// already-compiled AST mid-transaction. This mirrors the shipped <c>HomeEpochFence</c>
/// (read-the-tip-on-this-transaction, reject-if-stale) rather than inventing a new primitive (D5).
///
/// <para>In-memory here; the read-compare-swap is made atomic by a lock — the in-process analog of
/// the fence's <c>BEGIN IMMEDIATE</c> write lock, closing the read-through-write TOCTOU the fence
/// exists to close (the same reason <c>HomeEpochFence</c> requires the caller to hold the write lock
/// before the tip read). Cached in isolation for Wave 1: no production node yet drives the swap from
/// a live sync feed (Wave-2 cascade, D8).</para>
/// </summary>
public sealed class RuleCompileCache
{
    private readonly object _gate = new();
    private readonly Dictionary<(string Tenant, string Key), (string Version, CompiledGraph Graph)> _cache = new();

    /// <summary>Reads the cached compiled AST for <c>(tenant, ruleKey)</c>, if any.</summary>
    public bool TryGet(string tenant, string ruleKey, out string version, out CompiledGraph? graph)
    {
        ArgumentNullException.ThrowIfNull(tenant);
        ArgumentNullException.ThrowIfNull(ruleKey);
        lock (_gate)
        {
            if (_cache.TryGetValue((tenant, ruleKey), out var cur))
            {
                version = cur.Version;
                graph = cur.Graph;
                return true;
            }
            version = string.Empty;
            graph = null;
            return false;
        }
    }

    /// <summary>
    /// Installs a freshly-compiled AST for <paramref name="version"/> into the cache, MONOTONICALLY.
    /// The tip read + version compare + swap run inside one lock (atomic — no TOCTOU). A version that
    /// is a downgrade of the cached tip is a stale publish and is REFUSED
    /// (<see cref="StaleRulePublishException"/>); the newer cached AST stands. An equal or higher
    /// version installs (equal re-installs are idempotent). Returns the now-cached graph.
    /// </summary>
    public CompiledGraph Swap(string tenant, string ruleKey, string version, CompiledGraph graph)
    {
        ArgumentNullException.ThrowIfNull(tenant);
        ArgumentNullException.ThrowIfNull(ruleKey);
        ArgumentNullException.ThrowIfNull(version);
        ArgumentNullException.ThrowIfNull(graph);
        lock (_gate)
        {
            var key = (tenant, ruleKey);
            if (_cache.TryGetValue(key, out var cur) && RuleVersion.IsDowngrade(cur.Version, version))
            {
                throw new StaleRulePublishException($"{tenant}/{ruleKey}", version, cur.Version);
            }
            _cache[key] = (version, graph);
            return graph;
        }
    }
}

namespace Harborline.Foundation.RuleEngine.Registry;

/// <summary>The version policy a caller declares when resolving a named rule (ADR 0146 D5).</summary>
public enum RuleVersionPolicyKind
{
    /// <summary>The highest published version wins (default for forms/views/notifications).</summary>
    Latest = 0,

    /// <summary>An exact version (compliance scenarios; any pin change re-runs admission).</summary>
    Pinned = 1,

    /// <summary>A draft version — sandbox evaluation ONLY (never returned on a production resolve).</summary>
    Draft = 2,
}

/// <summary>
/// A caller-declared version policy (ADR 0146 D5): <c>latest</c> | <c>pinned:&lt;v&gt;</c> |
/// <c>draft</c>. Value type — cheap to pass per resolve.
/// </summary>
public readonly record struct RuleVersionPolicy
{
    private RuleVersionPolicy(RuleVersionPolicyKind kind, string? version)
    {
        Kind = kind;
        Version = version;
    }

    /// <summary>Which policy this is.</summary>
    public RuleVersionPolicyKind Kind { get; }

    /// <summary>The pinned version — non-null iff <see cref="Kind"/> is <see cref="RuleVersionPolicyKind.Pinned"/>.</summary>
    public string? Version { get; }

    /// <summary>Resolve the highest published (non-draft) version.</summary>
    public static RuleVersionPolicy Latest { get; } = new(RuleVersionPolicyKind.Latest, null);

    /// <summary>Resolve exactly <paramref name="version"/> (re-runs admission on any pin change).</summary>
    public static RuleVersionPolicy Pinned(string version)
        => new(RuleVersionPolicyKind.Pinned, version ?? throw new ArgumentNullException(nameof(version)));

    /// <summary>Resolve the latest draft — reachable ONLY through a sandbox-scoped resolve.</summary>
    public static RuleVersionPolicy Draft { get; } = new(RuleVersionPolicyKind.Draft, null);
}

/// <summary>
/// The trust boundary a resolve runs under (ADR 0146 D5 / board F6). The draft-exclusion is a
/// MECHANISM, not prose: a <see cref="Production"/> resolve NEVER returns a draft version — drafts
/// are reachable only through an explicit <see cref="Sandbox"/> resolve.
/// </summary>
public enum RuleResolveScope
{
    /// <summary>The production evaluation path — refuses every draft version (board F6).</summary>
    Production = 0,

    /// <summary>An explicitly sandbox-scoped resolve — the only path that reaches a draft.</summary>
    Sandbox = 1,
}

/// <summary>The outcome of a resolve.</summary>
public enum RuleResolutionStatus
{
    /// <summary>A version was resolved — <see cref="RuleResolution.Version"/> + <see cref="RuleResolution.Definition"/> are populated.</summary>
    Resolved = 0,

    /// <summary>No published version matched the (tenant, key, policy).</summary>
    NotFound = 1,

    /// <summary>A draft was requested (or the pinned version is a draft) on the production path — refused (board F6).</summary>
    DraftRefused = 2,
}

/// <summary>The result of resolving a named rule to a version + its definition.</summary>
public sealed record RuleResolution
{
    private RuleResolution(RuleResolutionStatus status, string? version, RuleDefinition? definition)
    {
        Status = status;
        Version = version;
        Definition = definition;
    }

    /// <summary>Whether a version resolved, was not found, or was a draft refused on the production path.</summary>
    public RuleResolutionStatus Status { get; }

    /// <summary>The resolved (or refused) version, when known.</summary>
    public string? Version { get; }

    /// <summary>The resolved definition — non-null iff <see cref="Status"/> is <see cref="RuleResolutionStatus.Resolved"/>.</summary>
    public RuleDefinition? Definition { get; }

    /// <summary>Convenience: true iff a version resolved.</summary>
    public bool IsResolved => Status == RuleResolutionStatus.Resolved;

    /// <summary>A resolved version.</summary>
    public static RuleResolution Resolved(string version, RuleDefinition definition)
        => new(RuleResolutionStatus.Resolved, version, definition);

    /// <summary>No match.</summary>
    public static RuleResolution NotFound { get; } = new(RuleResolutionStatus.NotFound, null, null);

    /// <summary>A draft refused on the production path (<paramref name="version"/> is the draft, or null for a draft-policy request).</summary>
    public static RuleResolution DraftRefused(string? version)
        => new(RuleResolutionStatus.DraftRefused, version, null);
}

/// <summary>
/// A D7 instance pin (ADR 0146 D5): the exact rule version captured at consumer-instance creation
/// (a running workflow, an in-progress report run, a document render). Resolving through the pin
/// replays deterministically against that version; re-admission happens when the consumer re-pins.
/// </summary>
public sealed record RulePin(string Tenant, string RuleKey, string Version);

/// <summary>One published rule version in the registry.</summary>
/// <param name="RuleKey">The named-rule key.</param>
/// <param name="Version">The monotonic version (S-8 watermark order, see <see cref="RuleVersion"/>).</param>
/// <param name="IsDraft">True for a draft — reachable only through a sandbox-scoped resolve.</param>
/// <param name="Definition">The rule definition compiled by the evaluator.</param>
public sealed record PublishedRuleVersion(string RuleKey, string Version, bool IsDraft, RuleDefinition Definition);

/// <summary>An equal rule version was presented with a different immutable body.</summary>
public sealed class RuleVersionConflictException(string tenant, string ruleKey, string version)
    : InvalidOperationException($"rule publish refused: '{tenant}/{ruleKey}@{version}' already has a different body")
{
    /// <summary>The tenant whose registry refused the publish.</summary>
    public string Tenant { get; } = tenant;
    /// <summary>The key of the rule whose version conflicted.</summary>
    public string RuleKey { get; } = ruleKey;
    /// <summary>The version already published with a different body.</summary>
    public string Version { get; } = version;
}

/// <summary>
/// The named-rule registry (ADR 0146 D5 / Wave 1): resolve a rule by <c>(tenant, rule-key)</c> under
/// a version policy. Composes shipped patterns, no new primitive — the S-8 monotonic watermark
/// (<see cref="RuleVersion"/>) for offline "latest", D7 instance pins (<see cref="RulePin"/>), and
/// (in the sibling <see cref="RuleCompileCache"/>) the HomeEpochFence read-tip-reject-stale
/// discipline for the per-node compile/cache swap.
/// </summary>
public interface IRuleRegistry
{
    /// <summary>Publishes (idempotent upsert) a rule version. A CRDT-synced record may arrive in any
    /// order — "latest" is resolved by the S-8 watermark, so a late older record simply never wins.</summary>
    void Publish(string tenant, PublishedRuleVersion published);

    /// <summary>Resolves a named rule under <paramref name="policy"/>. A <paramref name="scope"/> of
    /// <see cref="RuleResolveScope.Production"/> NEVER returns a draft (board F6).</summary>
    RuleResolution Resolve(string tenant, string ruleKey, RuleVersionPolicy policy, RuleResolveScope scope);

    /// <summary>Captures a D7 instance pin by resolving <paramref name="policy"/> once and freezing the
    /// version; returns null if nothing resolved (a refused/absent rule cannot be pinned).</summary>
    RulePin? Pin(string tenant, string ruleKey, RuleVersionPolicy policy, RuleResolveScope scope);

    /// <summary>Replays a D7 pin — resolves the exact pinned version (deterministic replay).</summary>
    RuleResolution ResolvePinned(RulePin pin, RuleResolveScope scope);
}

/// <summary>
/// In-memory <see cref="IRuleRegistry"/> — the Wave-1 unification floor. Holds published versions
/// per <c>(tenant, rule-key)</c> and resolves under the D5 version policies. Exercised in isolation:
/// no production CRDT sync feeds it yet — that is the Wave-2 cascade
/// (<c>PackContentKind.RuleDefinition</c>, D8). Thread-safe (a single gate over the store).
/// </summary>
public sealed class RuleRegistry : IRuleRegistry
{
    private readonly object _gate = new();
    // (tenant, ruleKey) -> version -> published. Inner dict keyed by version for idempotent upsert.
    private readonly Dictionary<(string Tenant, string Key), Dictionary<string, PublishedRuleVersion>> _store = new();

    /// <inheritdoc />
    public void Publish(string tenant, PublishedRuleVersion published)
    {
        ArgumentNullException.ThrowIfNull(tenant);
        ArgumentNullException.ThrowIfNull(published);
        RuleVersion.Validate(published.Version);
        lock (_gate)
        {
            var key = (tenant, published.RuleKey);
            if (!_store.TryGetValue(key, out var versions))
            {
                _store[key] = versions = new Dictionary<string, PublishedRuleVersion>(StringComparer.Ordinal);
            }
            if (versions.TryGetValue(published.Version, out var existing))
            {
                if (existing == published) return;
                throw new RuleVersionConflictException(tenant, published.RuleKey, published.Version);
            }
            versions.Add(published.Version, published);
        }
    }

    /// <inheritdoc />
    public RuleResolution Resolve(string tenant, string ruleKey, RuleVersionPolicy policy, RuleResolveScope scope)
    {
        ArgumentNullException.ThrowIfNull(tenant);
        ArgumentNullException.ThrowIfNull(ruleKey);
        lock (_gate)
        {
            if (!_store.TryGetValue((tenant, ruleKey), out var versions) || versions.Count == 0)
            {
                return RuleResolution.NotFound;
            }

            switch (policy.Kind)
            {
                case RuleVersionPolicyKind.Pinned:
                {
                    if (policy.Version is null || !versions.TryGetValue(policy.Version, out var pinned))
                    {
                        return RuleResolution.NotFound;
                    }
                    // A pinned DRAFT is refused on the production path — the draft-exclusion mechanism.
                    if (pinned.IsDraft && scope == RuleResolveScope.Production)
                    {
                        return RuleResolution.DraftRefused(pinned.Version);
                    }
                    return RuleResolution.Resolved(pinned.Version, pinned.Definition);
                }

                case RuleVersionPolicyKind.Draft:
                {
                    // The draft policy is reachable ONLY through a sandbox-scoped resolve (board F6).
                    if (scope == RuleResolveScope.Production)
                    {
                        return RuleResolution.DraftRefused(null);
                    }
                    return Highest(versions.Values.Where(v => v.IsDraft));
                }

                default: // Latest
                {
                    // Production excludes drafts (the mechanism); sandbox sees every version.
                    var pool = scope == RuleResolveScope.Production
                        ? versions.Values.Where(v => !v.IsDraft)
                        : versions.Values;
                    return Highest(pool);
                }
            }
        }
    }

    /// <inheritdoc />
    public RulePin? Pin(string tenant, string ruleKey, RuleVersionPolicy policy, RuleResolveScope scope)
    {
        var resolution = Resolve(tenant, ruleKey, policy, scope);
        return resolution.IsResolved ? new RulePin(tenant, ruleKey, resolution.Version!) : null;
    }

    /// <inheritdoc />
    public RuleResolution ResolvePinned(RulePin pin, RuleResolveScope scope)
    {
        ArgumentNullException.ThrowIfNull(pin);
        return Resolve(pin.Tenant, pin.RuleKey, RuleVersionPolicy.Pinned(pin.Version), scope);
    }

    // Picks the highest version in the pool by the S-8 monotonic watermark — order-independent, so
    // two offline peers holding the same set converge on the identical "latest".
    private static RuleResolution Highest(IEnumerable<PublishedRuleVersion> pool)
    {
        PublishedRuleVersion? best = null;
        foreach (var candidate in pool)
        {
            if (best is null || RuleVersion.Compare(candidate.Version, best.Version) > 0)
            {
                best = candidate;
            }
        }
        return best is null ? RuleResolution.NotFound : RuleResolution.Resolved(best.Version, best.Definition);
    }
}

using System.Globalization;

namespace Harborline.Foundation.RuleEngine.Registry;

/// <summary>
/// The per-rule-key monotonic-version comparator (ADR 0146 D5). Reuses the shipped S-8
/// monotonic-watermark SEMANTICS of <c>foundation-packs</c>' <c>PackVersion</c> — parse
/// <c>major.minor.patch</c> (extra numeric segments compared in order; a pre-release suffix after
/// '-' orders BEFORE the same core per SemVer §11; an unparseable version is refused) — as the
/// "which rule version wins offline" order. This is NOT a new versioning
/// primitive (D5: compose shipped patterns, no new primitive); it is the pack watermark applied
/// per rule key. It is mirrored here rather than referenced because the kernel rule engine cannot
/// depend UP on the pack machinery (packs consume rules as <c>PackContentKind.RuleDefinition</c>,
/// D8) — kept byte-compatible with <c>PackVersion.Compare</c>/<c>IsDowngrade</c>.
///
/// <para><c>foundation-versioning.VersionVector</c> is deliberately NOT used — it is a federation
/// handshake check, not a last-writer-wins watermark (a false friend, per the substrate survey).</para>
/// </summary>
public static class RuleVersion
{
    private sealed record ParsedVersion(int[] Core, string PreRelease, string BuildMetadata);

    /// <summary>
    /// Compares two rule versions. Returns &lt;0 if <paramref name="a"/> precedes
    /// <paramref name="b"/>, 0 if equal, &gt;0 if <paramref name="a"/> follows <paramref name="b"/>.
    /// A total, deterministic order — so two offline peers holding the same published set resolve
    /// the identical "latest" regardless of the order records synced in (monotonically convergent).
    /// </summary>
    public static int Compare(string a, string b)
    {
        var parsedA = Parse(a);
        var parsedB = Parse(b);
        var coreA = parsedA.Core;
        var coreB = parsedB.Core;
        var preA = parsedA.PreRelease;
        var preB = parsedB.PreRelease;

        var max = System.Math.Max(coreA.Length, coreB.Length);
        for (var i = 0; i < max; i++)
        {
            var ai = i < coreA.Length ? coreA[i] : 0;
            var bi = i < coreB.Length ? coreB[i] : 0;
            if (ai != bi)
            {
                return ai.CompareTo(bi);
            }
        }

        // Equal core: a pre-release precedes the stable release of the same core (SemVer §11).
        var hasPreA = preA.Length > 0;
        var hasPreB = preB.Length > 0;
        if (hasPreA == hasPreB)
        {
            return string.CompareOrdinal(preA, preB);
        }

        return hasPreA ? -1 : 1;
    }

    /// <summary>True iff <paramref name="candidate"/> is strictly below <paramref name="watermark"/>
    /// (a downgrade, refused by default under S-8 — the reject-stale half of the watermark).</summary>
    public static bool IsDowngrade(string watermark, string candidate)
        => Compare(candidate, watermark) < 0;

    /// <summary>Refuses a malformed rule version.</summary>
    public static void Validate(string version) => _ = Parse(version);

    /// <summary>Returns the next patch version for a strict major.minor.patch head.</summary>
    public static string NextPatch(string version)
    {
        var parsed = Parse(version);
        if (parsed.Core.Length != 3 || parsed.PreRelease.Length > 0)
        {
            throw new FormatException($"rule version '{version}' cannot be patch-incremented; expected major.minor.patch");
        }
        int patch = checked(parsed.Core[2] + 1);
        return FormattableString.Invariant($"{parsed.Core[0]}.{parsed.Core[1]}.{patch}");
    }

    private static ParsedVersion Parse(string version)
    {
        if (string.IsNullOrWhiteSpace(version) || !string.Equals(version, version.Trim(), StringComparison.Ordinal))
            throw Malformed(version);

        int firstPlus = version.IndexOf('+', StringComparison.Ordinal);
        if (firstPlus >= 0 && (firstPlus == version.Length - 1 || version.IndexOf('+', firstPlus + 1) >= 0))
            throw Malformed(version);
        string build = firstPlus >= 0 ? version[(firstPlus + 1)..] : string.Empty;
        string withoutBuild = firstPlus >= 0 ? version[..firstPlus] : version;

        int dash = withoutBuild.IndexOf('-', StringComparison.Ordinal);
        if (dash >= 0 && dash == withoutBuild.Length - 1) throw Malformed(version);
        string core = dash >= 0 ? withoutBuild[..dash] : withoutBuild;
        string pre = dash >= 0 ? withoutBuild[(dash + 1)..] : string.Empty;

        var segments = core.Split('.');
        if (segments.Length == 0 || segments.Any(segment => segment.Length == 0)) throw Malformed(version);
        var parsed = new int[segments.Length];
        for (var i = 0; i < segments.Length; i++)
        {
            if (!int.TryParse(segments[i], NumberStyles.None, CultureInfo.InvariantCulture, out var n))
                throw Malformed(version);
            parsed[i] = n;
        }

        return new ParsedVersion(parsed, pre, build);
    }

    private static FormatException Malformed(string? version)
        => new($"malformed rule version '{version ?? "<null>"}'");
}

