/// <summary>
/// The atom both in-assembly consumers share (SPINE-1 design §5.2): evaluate one
/// compiled rule against a resolved context into a <see cref="RuleOutcome"/>.
/// Internal plumbing — external consumers use <see cref="IFormRuleGraph"/> /
/// <see cref="IGuardEvaluator"/> (which expose only public shapes).
/// </summary>
internal interface IRuleEvaluator
{
    /// <summary>Evaluates one compiled rule for one target cell against a resolver.</summary>
    RuleOutcome Evaluate(CompiledRule rule, CellAddress target, string ruleKey,
        Evaluation.IValueResolver resolver, DateTimeOffset now, RuleEngineLimits limits, CancellationToken ct);
}

/// <summary>
/// The form orchestrator (SPINE-1 design §5.2, §5.3): compile a definition's rules
/// into a graph, evaluate a whole instance, and reactively re-evaluate transitive
/// dependents on a single-cell change or a child-table row add/remove.
/// </summary>
/// <remarks>
/// Stateful: <see cref="EvaluateInstance"/> binds the current instance; subsequent
/// reactive edits / <see cref="AddRow"/> / <see cref="RemoveRow"/> mutate it
/// and recompute only the affected front (the reactive as-you-type path).
/// </remarks>
public interface IFormRuleGraph
{
    /// <summary>The compiled (publish-time-validated) rule graph.</summary>
    CompiledGraph Compiled { get; }

    /// <summary>Binds <paramref name="instance"/> and evaluates the whole graph (the integrity-tier path).</summary>
    RuleEvaluationResult EvaluateInstance(RuleInstance instance, CancellationToken ct = default);

    /// <summary>Applies a single top-level field change and re-evaluates the transitive dependents only.</summary>
    RuleEvaluationResult Reevaluate(string fieldName, RuleInputValue newValue, CancellationToken ct = default);

    /// <summary>Rejects an unowned JSON node; callers must explicitly capture JSON text into <see cref="RuleInputValue"/>.</summary>
    RuleEvaluationResult Reevaluate(string fieldName, JsonNode? unownedValue, CancellationToken ct = default);

    /// <summary>Adds a child-table row (incremental graph edit) and re-evaluates the affected aggregates + dependents.</summary>
    RuleEvaluationResult AddRow(string section, RuleRow row, CancellationToken ct = default);

    /// <summary>Removes a child-table row by id (incremental graph edit); returns the re-evaluated result.</summary>
    RuleEvaluationResult RemoveRow(string section, string rowId, CancellationToken ct = default);
}

/// <summary>
/// The workflow orchestrator (SPINE-1 design §5.2, §5.4): evaluate a single
/// boolean/value expression (a transition guard / action condition) against a flat
/// context bag — a one-node graph.
/// </summary>
public interface IGuardEvaluator
{
    /// <summary>Evaluates a guard rule only over an explicitly host-captured inert context.</summary>
    Validity EvaluateGuard(RuleDefinition rule, RuleContextSnapshot context, RuleEvalScope scope,
        EvaluationAdmission? admission, CancellationToken ct = default);

    /// <summary>Evaluates a value expression only over an explicitly host-captured inert context.</summary>
    ComputedValue EvaluateValue(RuleDefinition rule, RuleContextSnapshot context, RuleEvalScope scope,
        EvaluationAdmission? admission, CancellationToken ct = default);
}

using System.Text.Json;
using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Compilation;


namespace Harborline.Foundation.RuleEngine.Skins;

// ─────────────────────────────────────────────────────────────────────────────
//  ADR 0146 D2 — the DECISION-TABLE authoring skin (compile layer).
//
//  "One expression language" (binding constraint #3): the decision table is an
//  authoring SKIN over the ratified D1 core, never a parallel evaluator. A skin
//  lowers to a plain `RuleDefinition` whose `Expression` is ordinary
//  `harborline-jsonlogic/v1` — a single multi-branch `if` the existing engine
//  evaluates. No new operator, no new OutputType, no new eval path (the
//  5-switches-per-tier rule does NOT apply — the skin is a compile-layer
//  representation over the existing AST).
//
//  Board F1 (BINDING) — a table is MORE than a bag of independent per-row cells:
//    • the skin carries a declared HIT POLICY (priority | first-match), resolved
//      INSIDE the compiled rule (the row ORDER of the emitted `if`), never as
//      independent cells whose overlap is unresolved;
//    • the skin carries an EXPLICIT no-match default (a declared default value OR a
//      mandatory catch-all row) — a silent null on no-match is a compile rejection,
//      not a runtime surprise;
//    • interval cells REIFY their upper bound (`and(>=lo, <hi)`) — the migration of
//      the floor-only `ThresholdDecisionTable` makes the implicit tops explicit.
//
//  The produced `RuleDefinition` flows through `RuleCompiler.Compile` exactly as a
//  hand-authored rule does, so the `RuleCompileAdmission` publish fence (D7) still
//  gates it — a skin never compiles+publishes around admission.
// ─────────────────────────────────────────────────────────────────────────────

/// <summary>The conflict-resolution policy a decision table declares (ADR 0146 D2 / board F1).</summary>
public enum HitPolicy
{
    /// <summary>The highest-<see cref="DecisionRow.Priority"/> matching row wins (ties broken by
    /// declared order, deterministically). Compiles to an <c>if</c> whose branches are ordered by
    /// descending priority — this is the <c>ThresholdDecisionTable</c> "highest-floor-wins" semantics.</summary>
    Priority = 0,

    /// <summary>The first matching row in DECLARED order wins. Compiles to an <c>if</c> whose branches
    /// keep declared order.</summary>
    FirstMatch = 1,
}

/// <summary>Which shape a <see cref="DecisionCell"/> takes (one condition per input column, per row).</summary>
public enum CellKind
{
    /// <summary>Wildcard — matches anything (contributes no condition). A row of all-<see cref="Any"/>
    /// cells is a catch-all.</summary>
    Any = 0,

    /// <summary>A single comparison against a literal: <c>{op:[{var:input}, value]}</c>.</summary>
    Compare = 1,

    /// <summary>A reified half-open interval <c>[lo, hi)</c> → <c>and(&gt;=lo, &lt;hi)</c>. Either bound
    /// may be null (open on that side) — an open-high interval is <c>&gt;=lo</c>, the top row of a
    /// floor-ordered table.</summary>
    Range = 2,
}

/// <summary>
/// One condition cell of a decision-table row — the test applied to ONE input column. Use the factory
/// members (<see cref="Wildcard"/> / <see cref="Compare"/> / <see cref="Range"/>) rather than the raw ctor.
/// </summary>
public sealed record DecisionCell(
    CellKind Kind,
    string? Op = null,
    JsonNode? Value = null,
    JsonNode? RangeLoInclusive = null,
    JsonNode? RangeHiExclusive = null)
{
    /// <summary>The set of comparison operators a <see cref="CellKind.Compare"/> cell may use — the
    /// closed operator set's relational/equality ops (no regex, no membership here).</summary>
    public static readonly IReadOnlySet<string> CompareOps =
        new HashSet<string> { "==", "!=", "<", "<=", ">", ">=" };

    /// <summary>A wildcard cell — always matches.</summary>
    public static DecisionCell Wildcard { get; } = new(CellKind.Any);

    /// <summary>A comparison cell: <c>{op:[{var:input}, value]}</c>.</summary>
    public static DecisionCell Compare(string op, JsonNode? value) => new(CellKind.Compare, Op: op, Value: value);

    /// <summary>A reified half-open interval <c>[lo, hi)</c>. Either bound may be null (open on that side).</summary>
    public static DecisionCell Range(JsonNode? loInclusive, JsonNode? hiExclusive)
        => new(CellKind.Range, RangeLoInclusive: loInclusive, RangeHiExclusive: hiExclusive);
}

/// <summary>
/// One row of a decision table: a condition per input column + the output value the row yields + a priority
/// (used only under <see cref="HitPolicy.Priority"/>). <see cref="Output"/> is a raw JSON value the compiled
/// rule returns as its outcome (interpreted per the table's <see cref="DecisionTableSkin.Action"/>).
/// </summary>
public sealed record DecisionRow(
    IReadOnlyList<DecisionCell> When,
    JsonNode? Output,
    int Priority = 0);

/// <summary>
/// The explicit no-match posture (board F1 — a silent null is forbidden). EXACTLY ONE of a declared
/// <see cref="Default"/> value or <see cref="RequireCatchAll"/> is active. Under <see cref="RequireCatchAll"/>
/// the compiler verifies a genuine catch-all row (all-<see cref="CellKind.Any"/> cells) exists and uses it as
/// the terminal else; if none exists the table is REJECTED at compile.
/// </summary>
public sealed record NoMatch(bool HasDefault, JsonNode? Default = null, bool RequireCatchAll = false)
{
    /// <summary>A declared default outcome for the no-match case (the terminal <c>else</c> branch).</summary>
    public static NoMatch WithDefault(JsonNode? value) => new(HasDefault: true, Default: value);

    /// <summary>Require a catch-all row to exist (its output is the terminal else). No silent null.</summary>
    public static NoMatch CatchAll { get; } = new(HasDefault: false, RequireCatchAll: true);
}

/// <summary>
/// The decision-table authoring skin (ADR 0146 D2). Compile it with <see cref="DecisionTableCompiler.Compile"/>
/// to a <see cref="RuleDefinition"/> the D1 core evaluates.
/// </summary>
/// <param name="RuleId">The stable rule id the produced <see cref="RuleDefinition"/> carries.</param>
/// <param name="Scope">The rule scope (where the outcome applies).</param>
/// <param name="ScopeTarget">The scope target (field/section path); empty for Schema.</param>
/// <param name="Action">The output action the outcome is interpreted as (Compute/Options/Validate/…).</param>
/// <param name="HitPolicy">The conflict-resolution policy (board F1).</param>
/// <param name="Inputs">The input columns — one var ref per column (e.g. <c>amount</c> / <c>field.amount</c>),
/// aligned positionally with each row's <see cref="DecisionRow.When"/> cells.</param>
/// <param name="Rows">The rows.</param>
/// <param name="NoMatch">The explicit no-match posture.</param>
public sealed record DecisionTableSkin(
    string RuleId,
    RuleScope Scope,
    string ScopeTarget,
    RuleActionKind Action,
    HitPolicy HitPolicy,
    IReadOnlyList<string> Inputs,
    IReadOnlyList<DecisionRow> Rows,
    NoMatch NoMatch);

/// <summary>
/// Lowers a <see cref="DecisionTableSkin"/> to a <see cref="RuleDefinition"/> whose <c>Expression</c> is a
/// single multi-branch <c>if</c> resolving the hit policy inside the compiled rule (board F1). Pure +
/// deterministic — both tiers produce the byte-identical expression (proven by the shared conformance corpus).
/// </summary>
public static class DecisionTableCompiler
{
    /// <summary>Compiles the skin; throws <see cref="RuleCompilationException"/> (a <c>rule.skin.*</c> code)
    /// on any structural rejection (no rows, no inputs, ragged row, bad cell, unresolved no-match).</summary>
    public static RuleDefinition Compile(DecisionTableSkin skin)
    {
        ArgumentNullException.ThrowIfNull(skin);
        string id = skin.RuleId;

        if (skin.Inputs.Count == 0)
            throw Reject(SkinCodes.DecisionTableNoInputs, id, "a decision table must declare at least one input column");
        if (skin.Rows.Count == 0)
            throw Reject(SkinCodes.DecisionTableEmpty, id, "a decision table must declare at least one row");

        // Validate every row is well-formed against the input arity + the closed cell ops.
        for (int r = 0; r < skin.Rows.Count; r++)
        {
            var row = skin.Rows[r];
            if (row.When.Count != skin.Inputs.Count)
                throw Reject(SkinCodes.DecisionTableBadRow, id,
                    $"row {r} has {row.When.Count} cell(s) but the table declares {skin.Inputs.Count} input column(s)");
            for (int c = 0; c < row.When.Count; c++)
            {
                var cell = row.When[c];
                string input = skin.Inputs[c];
                if (!Enum.IsDefined(cell.Kind))
                    throw Reject(SkinCodes.DecisionTableBadCell, id,
                        $"row {r} input '{input}' has unknown cell kind '{cell.Kind}'");
                if (cell.Kind == CellKind.Compare && (cell.Op is null || !DecisionCell.CompareOps.Contains(cell.Op)))
                    throw Reject(SkinCodes.DecisionTableBadCell, id,
                        $"row {r} input '{input}' has a compare cell with an unsupported operator '{cell.Op}' (allowed: {string.Join(", ", DecisionCell.CompareOps)})");
                if (cell.Kind == CellKind.Range)
                {
                    if (!IsNumericBound(cell.RangeLoInclusive))
                        throw Reject(SkinCodes.DecisionTableBadCell, id,
                            $"row {r} input '{input}' has a malformed lower range bound");
                    if (!IsNumericBound(cell.RangeHiExclusive))
                        throw Reject(SkinCodes.DecisionTableBadCell, id,
                            $"row {r} input '{input}' has a malformed upper range bound");
                }
            }
        }

        // Order rows per the hit policy — this IS the "resolve overlap inside the compiled rule" step.
        // Priority: descending Priority, ties by declared order (OrderBy is a stable sort, so a plain
        // OrderByDescending on Priority preserves declared order within a priority band).
        var ordered = skin.HitPolicy switch
        {
            HitPolicy.Priority => skin.Rows.OrderByDescending(r => r.Priority).ToList(),
            HitPolicy.FirstMatch => skin.Rows.ToList(),
            _ => throw Reject(SkinCodes.DecisionTableInvalidHitPolicy, id, $"unknown hit policy '{skin.HitPolicy}'"),
        };

        // Resolve the explicit no-match terminal (board F1 — never a silent null).
        JsonNode? terminalElse;
        IReadOnlyList<DecisionRow> cascadeRows;
        if (skin.NoMatch.HasDefault)
        {
            terminalElse = skin.NoMatch.Default?.DeepClone();
            cascadeRows = ordered;
        }
        else if (skin.NoMatch.RequireCatchAll)
        {
            // The FIRST catch-all in evaluation order is the terminal else. Rows after it can never
            // win, while rows before it retain their declared hit-policy precedence. Extracting a
            // later catch-all would move an earlier wildcard behind conditional rows and change the
            // winning row.
            int catchAllIdx = -1;
            for (int i = 0; i < ordered.Count; i++)
            {
                if (IsCatchAll(ordered[i])) { catchAllIdx = i; break; }
            }
            if (catchAllIdx < 0)
                throw Reject(SkinCodes.NoMatchUnresolved, id,
                    "hit policy requires a catch-all row (all-Any cells) but none is present — a silent null on no-match is forbidden (ADR 0146 D2, board F1)");
            terminalElse = ordered[catchAllIdx].Output?.DeepClone();
            cascadeRows = ordered.Take(catchAllIdx).ToList();
        }
        else
        {
            throw Reject(SkinCodes.NoMatchUnresolved, id,
                "no explicit no-match default (declared default or catch-all) — a silent null on no-match is forbidden (ADR 0146 D2, board F1)");
        }

        // Emit the single multi-branch if: [cond0, out0, cond1, out1, …, terminalElse].
        var ifArgs = new JsonArray();
        foreach (var row in cascadeRows)
        {
            ifArgs.Add(RowCondition(row, skin.Inputs));
            ifArgs.Add(row.Output?.DeepClone());
        }
        ifArgs.Add(terminalElse);
        var expression = new JsonObject { ["if"] = ifArgs };

        return RuleDefinitionFactory.Create(
            Id: id,
            Tier: RuleTier.JsonLogic,
            Scope: skin.Scope,
            ScopeTarget: skin.ScopeTarget,
            Expression: expression.ToJsonString(),
            Action: skin.Action);
    }

    private static bool IsCatchAll(DecisionRow row) => row.When.All(c => c.Kind == CellKind.Any);

    private static bool IsNumericBound(JsonNode? bound)
        => bound is null || bound is JsonValue value && value.GetValueKind() == JsonValueKind.Number;

    /// <summary>The AND of every non-wildcard cell in the row. An all-wildcard row's condition is the
    /// boolean literal <c>true</c> (it always fires) — only reached when a declared default coexists.</summary>
    private static JsonNode RowCondition(DecisionRow row, IReadOnlyList<string> inputs)
    {
        var terms = new List<JsonNode>();
        for (int c = 0; c < row.When.Count; c++)
        {
            var term = CellCondition(row.When[c], inputs[c]);
            if (term is not null) terms.Add(term);
        }
        if (terms.Count == 0) return JsonValue.Create(true);
        if (terms.Count == 1) return terms[0];
        var andArgs = new JsonArray();
        foreach (var t in terms) andArgs.Add(t);
        return new JsonObject { ["and"] = andArgs };
    }

    /// <summary>One cell → a JsonLogic condition node (or null for a wildcard / empty range).</summary>
    private static JsonNode? CellCondition(DecisionCell cell, string input)
    {
        switch (cell.Kind)
        {
            case CellKind.Any:
                return null;
            case CellKind.Compare:
                return new JsonObject { [cell.Op!] = new JsonArray(Var(input), cell.Value?.DeepClone()) };
            case CellKind.Range:
            {
                JsonNode? lo = cell.RangeLoInclusive is null
                    ? null
                    : new JsonObject { [">="] = new JsonArray(Var(input), cell.RangeLoInclusive.DeepClone()) };
                JsonNode? hi = cell.RangeHiExclusive is null
                    ? null
                    : new JsonObject { ["<"] = new JsonArray(Var(input), cell.RangeHiExclusive.DeepClone()) };
                if (lo is not null && hi is not null) return new JsonObject { ["and"] = new JsonArray(lo, hi) };
                return lo ?? hi; // an open-ended range with neither bound is a wildcard (null)
            }
            default:
                throw new InvalidOperationException($"unvalidated decision-table cell kind '{cell.Kind}'");
        }
    }

    private static JsonObject Var(string path) => new() { ["var"] = JsonValue.Create(path) };

    private static RuleCompilationException Reject(string code, string ruleId, string message)
        => new(code, $"decision-table skin '{ruleId}': {message}", ruleId);
}

using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Compilation;


namespace Harborline.Foundation.RuleEngine.Skins;

// ─────────────────────────────────────────────────────────────────────────────
//  ADR 0146 D2 — the FORMULA authoring skin (compile layer).
//
//  A formula is a named, typed-input expression compiling to the SAME AST as a
//  hand-authored rule (binding constraint #3 — one expression language). The skin
//  adds one thing over a bare `RuleDefinition`: a declared input manifest. The
//  compiler enforces that every `var` the expression reads is a DECLARED input — an
//  undeclared reference is a publish rejection, not a silent free variable. This is
//  what "named typed inputs" buys: a formula's data dependencies are explicit and
//  checkable at authoring time.
//
//  The declared type is part of admission: it constrains the closed operator
//  contracts before lowering produces the ordinary RuleDefinition consumed by D1.
// ─────────────────────────────────────────────────────────────────────────────

/// <summary>One declared input of a <see cref="FormulaSkin"/> — a var ref + its declared type.</summary>
/// <param name="Ref">The var path the expression references (e.g. <c>amount</c>, <c>field.qty</c>,
/// <c>self</c>). Must match the <c>var</c> path used in <see cref="FormulaSkin.Expression"/> exactly
/// (pre-lowering).</param>
/// <param name="Type">The declared type (<c>number</c> / <c>string</c> / <c>boolean</c> / <c>any</c>) —
/// checked by the shared core type derivation.</param>
public sealed record FormulaInput(string Ref, string Type = "any");

/// <summary>
/// The formula authoring skin (ADR 0146 D2). Compile it with <see cref="FormulaCompiler.Compile"/> to a
/// <see cref="RuleDefinition"/> the D1 core evaluates.
/// </summary>
/// <param name="RuleId">The stable rule id the produced <see cref="RuleDefinition"/> carries.</param>
/// <param name="Scope">The rule scope (where the outcome applies).</param>
/// <param name="ScopeTarget">The scope target (field/section path); empty for Schema.</param>
/// <param name="Action">The output action the outcome is interpreted as (typically Compute).</param>
/// <param name="Inputs">The declared named inputs — every var the expression reads must appear here.</param>
/// <param name="Expression">The harborline-jsonlogic/v1 expression (raw, pre-lowering).</param>
public sealed record FormulaSkin(
    string RuleId,
    RuleScope Scope,
    string ScopeTarget,
    RuleActionKind Action,
    IReadOnlyList<FormulaInput> Inputs,
    JsonNode? Expression);

/// <summary>
/// Lowers a <see cref="FormulaSkin"/> to a <see cref="RuleDefinition"/>, enforcing that every referenced var
/// is a declared input. Pure + deterministic — both tiers produce the byte-identical expression.
/// </summary>
public static class FormulaCompiler
{
    /// <summary>Compiles the skin; throws <see cref="RuleCompilationException"/> (a <c>rule.skin.*</c> code)
    /// on an empty expression or an undeclared reference.</summary>
    public static RuleDefinition Compile(FormulaSkin skin)
    {
        ArgumentNullException.ThrowIfNull(skin);
        string id = skin.RuleId;

        if (skin.Expression is null)
            throw Reject(SkinCodes.FormulaEmpty, id, "a formula must declare a non-empty expression");

        var declared = new HashSet<string>(skin.Inputs.Select(i => i.Ref), StringComparer.Ordinal);
        // Formula input declarations remain authoring metadata in the persisted RuleDefinition.
        // A returned RuleDefinition has no runtime type guard, so using these narrower types to
        // certify it would be unsound. Validate the declaration spelling, then use the same
        // conservative dynamic contract as ordinary compilation.
        foreach (var input in skin.Inputs)
            _ = CoreTypeDerivation.ParseDeclaredType(input.Type, id,
                message => Reject(SkinCodes.FormulaTypeMismatch, id, message));
        foreach (var referenced in CollectVarPaths(skin.Expression))
        {
            if (!declared.Contains(referenced))
                throw Reject(SkinCodes.FormulaUndeclaredRef, id,
                    $"expression references '{referenced}', which is not a declared input (declared: {string.Join(", ", declared.OrderBy(x => x, StringComparer.Ordinal))})");
        }

        _ = CoreTypeDerivation.Derive(skin.Expression, id,
            refusal: message => Reject(SkinCodes.FormulaTypeMismatch, id, message));

        var definition = RuleDefinitionFactory.Create(
            Id: id,
            Tier: RuleTier.JsonLogic,
            Scope: skin.Scope,
            ScopeTarget: skin.ScopeTarget,
            Expression: skin.Expression.ToJsonString(),
            Action: skin.Action);
        // Authoring callers receive only a rule that has crossed the exact same deterministic
        // parser/grammar/arity/bound admission fence as a published bare rule.
        _ = RuleCompiler.Compile(new[] { definition });
        return definition;
    }

    /// <summary>Every distinct <c>var</c> path in the expression (pre-lowering), in first-seen order.</summary>
    private static IEnumerable<string> CollectVarPaths(JsonNode? node)
    {
        var seen = new List<string>();
        var set = new HashSet<string>(StringComparer.Ordinal);
        Walk(node, seen, set);
        return seen;
    }

    private static void Walk(JsonNode? node, List<string> seen, HashSet<string> set)
    {
        switch (node)
        {
            case JsonObject obj when obj.Count == 1 && (obj.ContainsKey("missing") || obj.ContainsKey("missing_some")):
            {
                var raw = obj.First().Value;
                var args = raw is JsonArray array ? array.ToList() : new List<JsonNode?> { raw };
                if (obj.ContainsKey("missing_some") && args.Count > 0) Walk(args[0], seen, set);
                foreach (var keySource in obj.ContainsKey("missing_some") ? args.Skip(1) : args)
                    CollectMissingPaths(keySource, seen, set);
                break;
            }
            case JsonObject obj when obj.Count == 1 && obj.ContainsKey("var"):
            {
                string path = VarPathOf(obj["var"]);
                if (path.Length > 0 && set.Add(path)) seen.Add(path);
                // a {"var":[path, default]} may carry a nested default that references more vars
                if (obj["var"] is JsonArray a && a.Count > 1) Walk(a[1], seen, set);
                break;
            }
            case JsonObject obj when obj.Count == 1:
            {
                var argument = obj.First().Value;
                if (argument is JsonArray arguments) foreach (var item in arguments) Walk(item, seen, set);
                else Walk(argument, seen, set);
                break;
            }
        }
    }

    private static void CollectMissingPaths(JsonNode? node, List<string> seen, HashSet<string> set)
    {
        if (node is JsonArray array) { foreach (var item in array) CollectMissingPaths(item, seen, set); return; }
        if (node is JsonValue value && value.TryGetValue<string>(out var path) && path.Length > 0)
        {
            if (set.Add(path)) seen.Add(path);
            return;
        }
        if (node is JsonObject expression && expression.Count == 1) Walk(expression, seen, set);
    }

    private static string VarPathOf(JsonNode? varNode)
        => varNode is JsonArray a
            ? (a.Count > 0 ? a[0]?.GetValue<string>() ?? "" : "")
            : varNode?.GetValue<string>() ?? "";

    private static RuleCompilationException Reject(string code, string ruleId, string message)
        => new(code, $"formula skin '{ruleId}': {message}", ruleId);
}

namespace Harborline.Foundation.RuleEngine.Skins;

/// <summary>
/// Stable, locale-independent rejection codes emitted by the authoring skins (ADR 0146 D2). Byte-identical
/// to the TS <c>SkinCodes</c> (<c>rule-engine/src/skins/codes.ts</c>) — clients localize off these, never off
/// prose. A skin rejection is a publish-time <see cref="Compilation.RuleCompilationException"/> (fail-closed:
/// a rejected skin never produces a rule that reaches an instance).
/// </summary>
public static class SkinCodes
{
    // ── decision-table skin ──────────────────────────────────────────────────

    /// <summary>The table declared no input columns.</summary>
    public const string DecisionTableNoInputs = "rule.skin.decision_table_no_inputs";

    /// <summary>The table declared no rows.</summary>
    public const string DecisionTableEmpty = "rule.skin.decision_table_empty";

    /// <summary>A row's cell count does not match the declared input arity.</summary>
    public const string DecisionTableBadRow = "rule.skin.decision_table_bad_row";

    /// <summary>A compare cell used an operator outside the closed comparison set.</summary>
    public const string DecisionTableBadCell = "rule.skin.decision_table_bad_cell";

    /// <summary>An unknown hit policy was declared.</summary>
    public const string DecisionTableInvalidHitPolicy = "rule.skin.decision_table_invalid_hit_policy";

    /// <summary>No explicit no-match posture (no declared default and no catch-all row) — a silent null on
    /// no-match is forbidden (board F1).</summary>
    public const string NoMatchUnresolved = "rule.skin.no_match_unresolved";

    // ── formula skin ─────────────────────────────────────────────────────────

    /// <summary>The formula declared an empty / missing expression.</summary>
    public const string FormulaEmpty = "rule.skin.formula_empty";

    /// <summary>The formula's expression references a var that is not a declared input (named-input
    /// discipline — an undeclared reference is a compile rejection, not a silent free variable).</summary>
    public const string FormulaUndeclaredRef = "rule.skin.formula_undeclared_ref";

    /// <summary>A declared formula input cannot be consumed by the closed operator's type contract.</summary>
    public const string FormulaTypeMismatch = "rule.skin.formula_type_mismatch";
}

