namespace Harborline.Foundation.RuleEngine.Standings;

/// <summary>A record-shaped candidate for standing evaluation.</summary>
public sealed record StandingRecord(string RecordId, string RecordType, IReadOnlyDictionary<string, JsonNode?> FieldValues);

/// <summary>
/// One rule's verdict on one record: the deciding rule identity, the standing and a refusal code. It carries no
/// input value (the no-raw-input trace property); values are a separately authorized evidence read.
/// </summary>
public sealed record StandingDecision(string RuleId, string RuleVersion, StandingReference Standing, bool Carries, string? RefusalCode);

/// <summary>The standings one visible record carries, with every applicable rule's decision.</summary>
public sealed record StandingRowOutcome(string RecordId, IReadOnlyList<StandingReference> Standings, IReadOnlyList<StandingDecision> Decisions);

/// <summary>Whether a standing evidence read returned evidence, was refused, or does not apply.</summary>
public enum StandingEvidenceAvailability
{
    /// <summary>The evidence is returned.</summary>
    Available,
    /// <summary>The rule is not declared on the record's type, so no evidence exists.</summary>
    NotApplicable,
    /// <summary>The read was refused; even existence is hidden.</summary>
    Refused,
}

/// <summary>One rule's evidence for one record: the deciding rule, its verdict and the input values it read.</summary>
public sealed record StandingEvidence(
    string RuleId,
    string RuleVersion,
    StandingReference Standing,
    bool Carries,
    IReadOnlyDictionary<string, JsonNode?> Inputs,
    DateTimeOffset Instant,
    string? RefusalCode);

/// <summary>The outcome of a standing evidence read.</summary>
public sealed record StandingEvidenceRead(StandingEvidenceAvailability Availability, StandingEvidence? Evidence);

/// <summary>
/// An authorized standing evaluation over a result set: the visible row count, per-standing counts over every
/// visible row, one page of outcomes, and the number of predicate evaluations it took.
/// </summary>
public sealed record StandingSetResult(
    int VisibleCount,
    IReadOnlyDictionary<StandingReference, int> Counts,
    IReadOnlyList<StandingRowOutcome> Page,
    int PredicateEvaluations);

/// <summary>
/// Evaluates standings over a result set (DES-0018 <c>rules-eng-20</c>). Authorization applies first: each candidate
/// passes the host's Access check before any predicate reads it, and counts and pages are taken over the
/// visible rows only. A predicate is evaluated once per distinct tuple of the fields it declares, so rows that
/// share those values share one evaluation, and rows that differ never share a verdict. Evaluation requires the
/// borrower's admission (<c>rules-eng-26</c>). The evaluator takes no principal, role or grant: Rules narrows, it
/// never decides access.
/// </summary>
public sealed class StandingEvaluator(RuleEngineLimits? limits = null)
{
    private readonly RuleEngineLimits _limits = limits ?? RuleEngineLimits.Default;

    /// <summary>Evaluates <paramref name="definitions"/> over the candidates <paramref name="authorize"/> admits.</summary>
    /// <param name="capabilities">The host's Access verdicts; evaluation needs rules:evaluate-explain and records:read.</param>
    /// <param name="candidates">The complete tenant-bound candidate set, before any count or page.</param>
    /// <param name="authorize">The host's Access row check, bound to the reading principal and instant.</param>
    /// <param name="definitions">The installed standing rules.</param>
    /// <param name="admission">The borrower's admission evidence for this evaluation.</param>
    /// <param name="instant">The act instant every predicate evaluates at.</param>
    /// <param name="skip">Visible rows to skip before the page.</param>
    /// <param name="take">The page size.</param>
    /// <param name="cancellationToken">Cancels evaluation.</param>
    public async ValueTask<StandingSetResult> EvaluateSetAsync(
        RulesCapabilityCheck capabilities,
        IEnumerable<StandingRecord> candidates,
        Func<StandingRecord, CancellationToken, ValueTask<bool>> authorize,
        IReadOnlyList<StandingRuleDefinition> definitions,
        EvaluationAdmission? admission,
        DateTimeOffset instant,
        int skip,
        int take,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(candidates);
        ArgumentNullException.ThrowIfNull(authorize);
        ArgumentNullException.ThrowIfNull(definitions);
        ArgumentOutOfRangeException.ThrowIfNegative(skip);
        ArgumentOutOfRangeException.ThrowIfNegative(take);
        // The operation boundary: rules:evaluate-explain and records:read, before any row is checked or read.
        if (!await RulesPermissions.AllowsEvaluateExplainAsync(capabilities, cancellationToken).ConfigureAwait(false))
            throw new RulesPermissionException(RulesPermissions.EvaluateExplain);

        var ordered = definitions.OrderBy(rule => rule.RuleId, StringComparer.Ordinal)
            .ThenBy(rule => rule.RuleVersion, StringComparer.Ordinal).ToArray();
        var guard = new GuardEvaluator(new PinnedClock(instant), _limits);
        var verdicts = new Dictionary<string, Validity>(StringComparer.Ordinal);
        var counts = new Dictionary<StandingReference, int>();
        var page = new List<StandingRowOutcome>();
        int visible = 0;

        foreach (var record in candidates)
        {
            cancellationToken.ThrowIfCancellationRequested();
            ArgumentNullException.ThrowIfNull(record);
            if (!await authorize(record, cancellationToken).ConfigureAwait(false)) continue;

            var decisions = new List<StandingDecision>();
            var carried = new SortedSet<string>(StringComparer.Ordinal);
            foreach (var rule in ordered.Where(rule => string.Equals(rule.RecordType, record.RecordType, StringComparison.Ordinal)))
            {
                var inputs = new Dictionary<string, JsonNode?>(StringComparer.Ordinal);
                foreach (var field in rule.InputFields)
                    inputs[field] = record.FieldValues.TryGetValue(field, out var value) ? value : null;
                string key = new JsonArray(rule.RuleId, rule.RuleVersion,
                    new JsonArray([.. rule.InputFields.Select(field => inputs[field]?.DeepClone())])).ToJsonString();
                if (!verdicts.TryGetValue(key, out var verdict))
                {
                    verdict = guard.EvaluateGuard(rule.Predicate, RuleContextSnapshot.Capture(inputs), RuleEvalScope.Root, admission, cancellationToken);
                    verdicts.Add(key, verdict);
                }
                if (verdict.Ok) carried.Add(rule.Standing.Name);
                decisions.Add(new(rule.RuleId, rule.RuleVersion, rule.Standing, verdict.Ok, RefusalOf(rule, verdict)));
            }

            foreach (var name in carried) counts[new StandingReference(name)] = counts.GetValueOrDefault(new StandingReference(name)) + 1;
            if (visible >= skip && page.Count < take)
                page.Add(new(record.RecordId, [.. carried.Select(name => new StandingReference(name))], decisions));
            visible++;
        }

        return new(visible, counts, page, verdicts.Count);
    }

    /// <summary>
    /// The separately authorized read of one rule's standing evidence, which, unlike a decision, carries the
    /// predicate's input values. <paramref name="authorizeEvidenceRead"/> runs first, so a refusal reveals nothing
    /// about whether evidence exists; a rule declared on another record type is not applicable.
    /// </summary>
    public async ValueTask<StandingEvidenceRead> ReadEvidenceAsync(
        RulesCapabilityCheck capabilities,
        StandingRecord record,
        StandingRuleDefinition rule,
        Func<StandingRecord, CancellationToken, ValueTask<bool>> authorizeEvidenceRead,
        EvaluationAdmission? admission,
        DateTimeOffset instant,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(record);
        ArgumentNullException.ThrowIfNull(rule);
        ArgumentNullException.ThrowIfNull(authorizeEvidenceRead);
        if (!await RulesPermissions.AllowsEvaluateExplainAsync(capabilities, cancellationToken).ConfigureAwait(false)
            || !await authorizeEvidenceRead(record, cancellationToken).ConfigureAwait(false))
            return new(StandingEvidenceAvailability.Refused, null);
        if (!string.Equals(rule.RecordType, record.RecordType, StringComparison.Ordinal))
            return new(StandingEvidenceAvailability.NotApplicable, null);

        var inputs = rule.InputFields.ToDictionary(field => field,
            field => record.FieldValues.TryGetValue(field, out var value) ? value?.DeepClone() : null, StringComparer.Ordinal);
        var verdict = new GuardEvaluator(new PinnedClock(instant), _limits)
            .EvaluateGuard(rule.Predicate, RuleContextSnapshot.Capture(inputs), RuleEvalScope.Root, admission, cancellationToken);
        return new(StandingEvidenceAvailability.Available,
            new(rule.RuleId, rule.RuleVersion, rule.Standing, verdict.Ok, inputs, instant, RefusalOf(rule, verdict)));
    }

    // A predicate that is simply false reports its own rule id; only an engine refusal is a refusal code.
    private static string? RefusalOf(StandingRuleDefinition rule, Validity verdict)
        => verdict.Ok || verdict.Error is not { } error || error.Code == rule.RuleId ? null : error.Code;

    private sealed class PinnedClock(DateTimeOffset instant) : TimeProvider
    {
        public override DateTimeOffset GetUtcNow() => instant;
    }
}

using Harborline.Foundation.RuleEngine.Compilation;

namespace Harborline.Foundation.RuleEngine.Standings;

/// <summary>A domain-declared position computed from one record type's own fields. A fact, never a role.</summary>
public readonly record struct StandingReference
{
    /// <summary>Creates a standing name.</summary>
    public StandingReference(string name)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(name);
        Name = name;
    }

    /// <summary>The domain-declared standing name.</summary>
    public string Name { get; }

    /// <inheritdoc />
    public override string ToString() => Name;
}

/// <summary>
/// The set-facing Rules shape (DES-0018 <c>rules-ck-21</c>): an ordinary versioned definition that computes a
/// standing from declared fields of one record type. Its predicate is a schema-scoped
/// <c>harborline-jsonlogic/v1</c> validation rule, admitted by the compiler when the definition is made, and
/// its declared inputs are exactly the fields that predicate reads.
/// </summary>
public sealed record StandingRuleDefinition
{
    /// <summary>Creates and validates a standing rule; refuses by <see cref="ArgumentException"/>.</summary>
    public StandingRuleDefinition(string ruleId, string ruleVersion, StandingReference standing, string recordType,
        IReadOnlyList<string> inputFields, RuleDefinition predicate)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(ruleId);
        ArgumentException.ThrowIfNullOrWhiteSpace(ruleVersion);
        ArgumentException.ThrowIfNullOrWhiteSpace(recordType);
        ArgumentNullException.ThrowIfNull(inputFields);
        ArgumentNullException.ThrowIfNull(predicate);
        if (standing == default) throw new ArgumentException("A standing name is required.", nameof(standing));
        if (inputFields.Count == 0 || inputFields.Any(string.IsNullOrWhiteSpace)
            || inputFields.Distinct(StringComparer.Ordinal).Count() != inputFields.Count)
            throw new ArgumentException("Input fields must be one or more unique, non-empty names.", nameof(inputFields));
        RequireValidationShape(predicate);
        if (!string.Equals(predicate.Id, ruleId, StringComparison.Ordinal))
            throw new ArgumentException("The predicate id must equal the standing rule id.", nameof(predicate));
        if (!FieldsRead(predicate).SetEquals(inputFields))
            throw new ArgumentException("Input fields must name exactly the record fields the predicate reads.", nameof(inputFields));

        (RuleId, RuleVersion, Standing, RecordType, InputFields, Predicate) =
            (ruleId, ruleVersion, standing, recordType, inputFields.ToArray(), predicate);
    }

    /// <summary>The stable rule identity evidence and traces name.</summary>
    public string RuleId { get; }

    /// <summary>The installed rule version evidence and traces name.</summary>
    public string RuleVersion { get; }

    /// <summary>The standing carried when the predicate passes.</summary>
    public StandingReference Standing { get; }

    /// <summary>The record type this rule is declared on.</summary>
    public string RecordType { get; }

    /// <summary>The complete set of record fields the predicate reads.</summary>
    public IReadOnlyList<string> InputFields { get; }

    /// <summary>The closed-grammar predicate.</summary>
    public RuleDefinition Predicate { get; }

    // The schema-scoped rule shape, shared with the record-write rules that reuse it (T-978 ruling).
    internal static void RequireValidationShape(RuleDefinition predicate)
    {
        if (predicate.Tier != RuleTier.JsonLogic || predicate.Action != RuleActionKind.Validate || predicate.Scope != RuleScope.Schema)
            throw new ArgumentException("The predicate must be a schema-scoped harborline-jsonlogic/v1 validation rule.", nameof(predicate));
    }

    // Compiles the predicate and returns the top-level record fields it reads; any other reference refuses.
    internal static HashSet<string> FieldsRead(RuleDefinition predicate)
    {
        var references = RuleCompiler.Compile([predicate]).Rules.Single().References;
        if (references.Any(reference => reference is not FieldRef))
            throw new ArgumentException("The predicate may read only top-level record fields.", nameof(predicate));
        return references.OfType<FieldRef>().Select(reference => reference.Name).ToHashSet(StringComparer.Ordinal);
    }
}

