/// <summary>A fixed clock for deterministic <c>date.*</c> evaluation in the corpus.</summary>
internal sealed class FixedClock : TimeProvider
{
    private readonly DateTimeOffset _now;
    public FixedClock(DateTimeOffset now) => _now = now;
    public override DateTimeOffset GetUtcNow() => _now;
}

/// <summary>Loads + runs the shared conformance corpus (SPINE-1 §6.1).</summary>
internal static class CorpusLoader
{
    private static string CorpusDir => Path.Combine(AppContext.BaseDirectory, "corpus");

    public static IEnumerable<(string File, JsonObject Case)> AllCases()
    {
        foreach (var path in Directory.EnumerateFiles(CorpusDir, "*.json").OrderBy(p => p, StringComparer.Ordinal))
        {
            var root = (JsonObject)JsonNode.Parse(File.ReadAllText(path))!;
            string file = Path.GetFileName(path);
            foreach (var caseNode in (JsonArray)root["cases"]!)
            {
                yield return (file, (JsonObject)caseNode!);
            }
        }
    }

    /// <summary>Ticket 162: the stable code a publish-time-refusal case expects compile to raise.</summary>
    public static string CompileRefusalCode(JsonObject caseObj) => CompileRefusal(caseObj).Code;

    /// <summary>The refusal a publish-time-refusal case expects compile to raise (T-818: with its params).</summary>
    public static RuleCompilationException CompileRefusal(JsonObject caseObj)
    {
        var rules = ((JsonArray)caseObj["definitionRules"]!).Select(n => ParseRule((JsonObject)n!)).ToList();
        try
        {
            RuleCompiler.Compile(rules, ParseLimits(caseObj));
        }
        catch (RuleCompilationException ex)
        {
            return ex;
        }
        throw new InvalidOperationException($"case '{caseObj["name"]}' expected a compile refusal and none was raised");
    }

    /// <summary>Ticket 162: evaluate one rule through the guard tier over the instance as a flat context bag.</summary>
    public static string GuardValueOutcome(JsonObject caseObj)
    {
        string ruleId = caseObj["guardValue"]!.GetValue<string>();
        var rule = ((JsonArray)caseObj["definitionRules"]!)
            .Select(n => ParseRule((JsonObject)n!))
            .Single(r => r.Id == ruleId);
        var clock = new FixedClock(DateTimeOffset.Parse(
            caseObj["clock"]?.GetValue<string>() ?? "2026-06-30T00:00:00Z",
            CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal));
        var bag = ((JsonObject)caseObj["instance"]!).ToDictionary(kv => kv.Key, kv => kv.Value?.DeepClone());
        var value = new GuardEvaluator(clock, ParseLimits(caseObj)).EvaluateValue(rule, RuleContextSnapshot.Capture(bag), RuleEvalScope.Root, TestAdmission.Any);
        return CanonicalJson.SerializeComputedValue(value);
    }

    /// <summary>
    /// The rules the case DECLARES — the exact list handed to the compiler. Ticket 193 review: the
    /// runner needs this separately from <see cref="RunCase"/> so it can assert the compiled graph
    /// introduced no rule the case never declared.
    /// </summary>
    public static List<RuleDefinition> DeclaredRules(JsonObject caseObj)
        => caseObj.TryGetPropertyValue("skin", out var skinNode) && skinNode is JsonObject skinObj
            ? new List<RuleDefinition> { CompileSkin(skinObj) }
            : ((JsonArray)caseObj["definitionRules"]!).Select(n => ParseRule((JsonObject)n!)).ToList();

    public static (CompiledGraph Compiled, RuleEvaluationResult Result) RunCase(JsonObject caseObj)
    {
        // ADR 0146 D2 — a case may carry a `skin` (decision-table / formula) authoring representation
        // instead of raw `definitionRules`. The skin compiles to the RuleDefinition(s) the normal flow
        // then compiles + evaluates — so a skin case exercises the identical downstream path (byte-identical
        // AST + outcomes prove both tiers' skin compilers agree).
        var rules = DeclaredRules(caseObj);
        var limits = ParseLimits(caseObj);
        var compiled = RuleCompiler.Compile(rules, limits);

        var clock = new FixedClock(DateTimeOffset.Parse(
            caseObj["clock"]?.GetValue<string>() ?? "2026-06-30T00:00:00Z",
            CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.AssumeUniversal | System.Globalization.DateTimeStyles.AdjustToUniversal));

        var graph = new FormRuleGraph(compiled, clock, TestAdmission.Any, limits);
        var instance = RuleInstance.FromJson((JsonObject)caseObj["instance"]!);
        var result = graph.EvaluateInstance(instance);
        return (compiled, result);
    }

    private static RuleDefinition ParseRule(JsonObject r)
    {
        var presentation = r.TryGetPropertyValue("presentation", out var p) && p is JsonObject po
            ? ParseHint(po)
            : null;
        return RuleDefinitionFactory.Create(
            Id: r["id"]!.GetValue<string>(),
            Tier: Enum.Parse<RuleTier>(r["tier"]!.GetValue<string>()),
            Scope: Enum.Parse<RuleScope>(r["scope"]!.GetValue<string>()),
            ScopeTarget: r["scopeTarget"]?.GetValue<string>() ?? "",
            Expression: r["expression"]!.ToJsonString(),
            Action: Enum.Parse<RuleActionKind>(r["action"]!.GetValue<string>()),
            ErrorMessage: null,
            Presentation: presentation);
    }

    // ── ADR 0146 D2 skin parsing (corpus authoring JSON → the typed skin model → RuleDefinition) ──

    private static RuleDefinition CompileSkin(JsonObject skin)
    {
        string kind = skin["kind"]!.GetValue<string>();
        return kind switch
        {
            "decision-table" => DecisionTableCompiler.Compile(ParseDecisionTableSkin(skin)),
            "formula" => FormulaCompiler.Compile(ParseFormulaSkin(skin)),
            _ => throw new ArgumentException($"unknown skin kind '{kind}'"),
        };
    }

    private static DecisionTableSkin ParseDecisionTableSkin(JsonObject s) => new(
        RuleId: s["ruleId"]!.GetValue<string>(),
        Scope: Enum.Parse<RuleScope>(s["scope"]!.GetValue<string>()),
        ScopeTarget: s["scopeTarget"]?.GetValue<string>() ?? "",
        Action: Enum.Parse<RuleActionKind>(s["action"]!.GetValue<string>()),
        HitPolicy: s["hitPolicy"]!.GetValue<string>() switch
        {
            "priority" => HitPolicy.Priority,
            "first-match" => HitPolicy.FirstMatch,
            var p => throw new ArgumentException($"unknown hit policy '{p}'"),
        },
        Inputs: ((JsonArray)s["inputs"]!).Select(n => n!.GetValue<string>()).ToList(),
        Rows: ((JsonArray)s["rows"]!).Select(n => ParseRow((JsonObject)n!)).ToList(),
        NoMatch: ParseNoMatch((JsonObject)s["noMatch"]!));

    private static DecisionRow ParseRow(JsonObject r) => new(
        When: ((JsonArray)r["when"]!).Select(n => ParseCell((JsonObject)n!)).ToList(),
        Output: r["output"]?.DeepClone(),
        Priority: r["priority"]?.GetValue<int>() ?? 0);

    private static DecisionCell ParseCell(JsonObject c)
    {
        if (c.ContainsKey("any")) return DecisionCell.Wildcard;
        if (c.ContainsKey("op")) return DecisionCell.Compare(c["op"]!.GetValue<string>(), c["value"]?.DeepClone());
        if (c.TryGetPropertyValue("range", out var range) && range is JsonObject ro)
            return DecisionCell.Range(ro["lo"]?.DeepClone(), ro["hi"]?.DeepClone());
        throw new ArgumentException("a decision-table cell must be one of { any | op/value | range }");
    }

    private static NoMatch ParseNoMatch(JsonObject nm)
    {
        if (nm.ContainsKey("catchAll")) return NoMatch.CatchAll;
        if (nm.ContainsKey("default")) return NoMatch.WithDefault(nm["default"]?.DeepClone());
        throw new ArgumentException("noMatch must declare a `default` value or `catchAll: true` (board F1 — no silent null)");
    }

    private static FormulaSkin ParseFormulaSkin(JsonObject s) => new(
        RuleId: s["ruleId"]!.GetValue<string>(),
        Scope: Enum.Parse<RuleScope>(s["scope"]!.GetValue<string>()),
        ScopeTarget: s["scopeTarget"]?.GetValue<string>() ?? "",
        Action: Enum.Parse<RuleActionKind>(s["action"]!.GetValue<string>()),
        Inputs: ((JsonArray)s["inputs"]!).Select(n =>
        {
            var io = (JsonObject)n!;
            return new FormulaInput(io["ref"]!.GetValue<string>(), io["type"]?.GetValue<string>() ?? "any");
        }).ToList(),
        Expression: s["expression"]?.DeepClone());

    private static PresentationHint ParseHint(JsonObject po)
    {
        InternationalizedText? badge = null;
        if (po.TryGetPropertyValue("badge", out var b) && b is JsonObject bo)
        {
            var values = new Dictionary<string, string>();
            foreach (var (k, v) in (JsonObject)bo["values"]!) values[k] = v!.GetValue<string>();
            badge = RuleDefinitionFactory.Text(bo["defaultLocale"]!.GetValue<string>(), values);
        }
        return RuleDefinitionFactory.Hint(
            po["severity"]?.GetValue<string>(),
            badge,
            po["styleToken"]?.GetValue<string>());
    }

    private static RuleEngineLimits ParseLimits(JsonObject caseObj)
    {
        if (!caseObj.TryGetPropertyValue("limits", out var l) || l is not JsonObject lo) return RuleEngineLimits.Default;
        var d = RuleEngineLimits.Default;
        return d with
        {
            MaxGraphNodes = lo["maxGraphNodes"]?.GetValue<int>() ?? d.MaxGraphNodes,
            MaxDependencyDepth = lo["maxDependencyDepth"]?.GetValue<int>() ?? d.MaxDependencyDepth,
            MaxReferencesPerRule = lo["maxReferencesPerRule"]?.GetValue<int>() ?? d.MaxReferencesPerRule,
            MaxAstNodes = lo["maxAstNodes"]?.GetValue<int>() ?? d.MaxAstNodes,
            StepBudget = lo["stepBudget"]?.GetValue<int>() ?? d.StepBudget,
            // T-818: a decimal string, because the default exceeds int and JavaScript's safe integers.
            MaxStaticWork = lo["maxStaticWork"] is { } work
                ? System.Numerics.BigInteger.Parse(work.GetValue<string>(), CultureInfo.InvariantCulture) : d.MaxStaticWork,
        };
    }

    public static void WriteArtifact(string name, JsonNode content)
    {
        try
        {
            var dir = Path.Combine(RepoRoot(), "artifacts", "rule-runtime");
            Directory.CreateDirectory(dir);
            File.WriteAllText(Path.Combine(dir, name), content.ToJsonString(new System.Text.Json.JsonSerializerOptions { WriteIndented = true }));
        }
        catch
        {
            // Artifact emission is best-effort (cross-tier diff convenience); never fail the suite on IO.
        }
    }

    private static string RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "repository.yaml"))) dir = dir.Parent;
        return dir?.FullName ?? AppContext.BaseDirectory;
    }
}

using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Compilation;
using Harborline.Foundation.RuleEngine.Explain;
using Harborline.Foundation.RuleEngine.Graph;
using Harborline.Foundation.RuleEngine.Skins;
using Harborline.Foundation.RuleEngine.Standings;

using Xunit;

namespace Harborline.Foundation.RuleEngine.Tests;

/// <summary>T-591: the decision trace and the separately authorized standing evidence read.</summary>
public sealed class DecisionTraceTests
{
    private static readonly DateTimeOffset At = new(2026, 9, 25, 0, 0, 0, TimeSpan.Zero);

    private static DecisionTableSkin Tiering(HitPolicy policy) => new(
        "tier.table", RuleScope.Field, "tier", RuleActionKind.Compute, policy, ["amount"],
        [
            new([DecisionCell.Compare(">=", 1000)], "gold", Priority: 1),
            new([DecisionCell.Compare(">=", 100)], "silver", Priority: 5),
        ],
        NoMatch.WithDefault("bronze"));

    private static readonly string[] Leaks = ["1500", "gold", "silver", "bronze"];

    private static RuleDefinition Formula() => RuleDefinitionFactory.Create(
        "limit.check", RuleTier.JsonLogic, RuleScope.Field, "limit", """{"<=":[{"var":"amount"},{"var":"limit"}]}""", RuleActionKind.Validate);

    [Theory(DisplayName = "rules-run-2: a decision-table outcome's trace names the deciding rule, what it read and the table's declared hit policy, and never a value")]
    [InlineData(HitPolicy.Priority, "priority")]
    [InlineData(HitPolicy.FirstMatch, "first-match")]
    public void Decision_table_trace_carries_the_declared_hit_policy(HitPolicy policy, string wire)
    {
        var table = Tiering(policy);
        var compiled = RuleCompiler.Compile([DecisionTableCompiler.Compile(table), Formula()]);
        var result = new FormRuleGraph(compiled, new FixedClock(At), TestAdmission.Any, RuleEngineLimits.Default)
            .EvaluateInstance(RuleInstance.FromJson(new JsonObject { ["amount"] = 1500, ["limit"] = 10 }));

        var trace = RuleTraceBuilder.BuildForm(compiled, result, PassThroughTraceFilter.Instance, [table]);

        var decided = trace.Single(entry => entry.RuleId == "tier.table");
        Assert.Equal(RuleTraceCodes.ValueComputed, decided.Code);
        Assert.Equal("tier.table", decided.Params["rule"]);
        Assert.Equal("amount", decided.Params["reads"]);
        Assert.Equal(wire, decided.Params["hitPolicy"]);
        // A rule no table supplied carries no hit policy; no entry carries a value or an output literal.
        Assert.False(trace.Single(entry => entry.RuleId == "limit.check").Params.ContainsKey("hitPolicy"));
        Assert.All(trace.SelectMany(entry => entry.Params.Values), value =>
        {
            foreach (var leaked in Leaks) Assert.DoesNotContain(leaked, value, StringComparison.Ordinal);
        });
    }

    [Fact(DisplayName = "rules-eng-19: the trace explains which rule decided and why: the failing rule, its reads and its cause code, with no value")]
    public void Trace_explains_the_deciding_rule_and_why()
    {
        var compiled = RuleCompiler.Compile([Formula()]);
        var result = new FormRuleGraph(compiled, new FixedClock(At), TestAdmission.Any, RuleEngineLimits.Default)
            .EvaluateInstance(RuleInstance.FromJson(new JsonObject { ["amount"] = 1500, ["limit"] = 10 }));

        var entry = Assert.Single(RuleTraceBuilder.BuildForm(compiled, result));
        Assert.Equal(("limit.check", RuleTraceCodes.ValidationFailed), (entry.RuleId, entry.Code));
        Assert.Equal("amount,limit", entry.Params["reads"]);
        Assert.Equal("limit.check", entry.Params["cause"]);
        Assert.DoesNotContain(entry.Params.Values, value => value.Contains("1500", StringComparison.Ordinal));
    }

    [Fact(DisplayName = "rules-eng-19: standing evidence with values is its own authorized read: refused before existence is revealed, not-applicable when the rule does not cover the record, and only the declared inputs when available")]
    public async Task Standing_evidence_needs_its_own_authorized_read()
    {
        var rule = StandingTests.Rule("large", "large", """{">":[{"var":"amount"},500]}""", "amount");
        var record = new StandingRecord("a1", "asset", new Dictionary<string, JsonNode?> { ["amount"] = 900, ["owner"] = "secret" });
        var other = record with { RecordType = "invoice" };
        var evaluator = new StandingEvaluator();
        static ValueTask<bool> Deny(StandingRecord row, CancellationToken ct) => ValueTask.FromResult(false);
        static ValueTask<bool> Allow(StandingRecord row, CancellationToken ct) => ValueTask.FromResult(true);

        var refused = await evaluator.ReadEvidenceAsync(Grants.All, record, rule, Deny, TestAdmission.Any, At);
        Assert.Equal((StandingEvidenceAvailability.Refused, null), (refused.Availability, refused.Evidence));
        // Refusal hides whether evidence would exist.
        Assert.Equal(StandingEvidenceAvailability.Refused, (await evaluator.ReadEvidenceAsync(Grants.All, other, rule, Deny, TestAdmission.Any, At)).Availability);

        var absent = await evaluator.ReadEvidenceAsync(Grants.All, other, rule, Allow, TestAdmission.Any, At);
        Assert.Equal((StandingEvidenceAvailability.NotApplicable, null), (absent.Availability, absent.Evidence));

        var read = await evaluator.ReadEvidenceAsync(Grants.All, record, rule, Allow, TestAdmission.Any, At);
        Assert.Equal(StandingEvidenceAvailability.Available, read.Availability);
        var evidence = read.Evidence!;
        Assert.Equal(("large", "1.0.0", true, At), (evidence.RuleId, evidence.RuleVersion, evidence.Carries, evidence.Instant));
        Assert.Equal(["amount"], evidence.Inputs.Keys);
        Assert.Equal(900, evidence.Inputs["amount"]!.GetValue<int>());
    }
}

using System.Reflection;
using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Compilation;
using Harborline.Foundation.RuleEngine.Evaluation;
using Harborline.Foundation.RuleEngine.Functions;
using Harborline.Foundation.RuleEngine.Model;

using Xunit;

namespace Harborline.Foundation.RuleEngine.Tests;

/// <summary>T-590 slice 1: the discriminated function reference and the R1 built-in register.</summary>
public sealed class FunctionRegisterTests
{
    [Fact(DisplayName = "rules-ck-29, rules-bound-3: a package payload cannot construct the built-in discriminant")]
    public void Package_payload_cannot_construct_a_built_in()
    {
        // The type offers no public way in: only the register hands out BuiltInFunction.
        Assert.Empty(typeof(BuiltInFunction).GetConstructors(BindingFlags.Public | BindingFlags.Instance));

        var forged = JsonNode.Parse("""{"kind":"builtin","key":"cat"}""");
        var refusal = Assert.Throws<FunctionReferenceException>(() => FunctionReferenceCodec.ReadPackagePayload(forged));
        Assert.Equal(FunctionReferenceCodec.BuiltInFromPackage, refusal.Code);

        // A package exporting a key that collides with a built-in is still the package arm: no shadowing.
        var package = FunctionReferenceCodec.ReadPackagePayload(JsonNode.Parse("""{"kind":"package","packageId":"finance","functionKey":"cat"}"""));
        var builtIn = BuiltInFunctionRegister.Resolve("cat");
        Assert.IsType<PackageFunction>(package);
        Assert.NotEqual<FunctionReference>(builtIn, package);
        Assert.NotEqual(builtIn.Digest, package.Digest);
    }

    [Fact(DisplayName = "rules-ck-29: canonical form and digest carry the discriminant and structured fields; the display form is never parsed")]
    public void Canonical_form_and_digest_carry_the_discriminant()
    {
        var builtIn = BuiltInFunctionRegister.Resolve("money.add");
        var package = new PackageFunction("finance", "money.add");
        Assert.Equal("""{"key":"money.add","kind":"builtin"}""", builtIn.CanonicalJson);
        Assert.Equal("""{"functionKey":"money.add","kind":"package","packageId":"finance"}""", package.CanonicalJson);
        Assert.Equal(64, builtIn.Digest.Length);
        Assert.NotEqual(builtIn.Digest, package.Digest);
        Assert.Equal("finance::money.add", package.Display);

        // ':' is forbidden in both structured fields, so the display form cannot be ambiguous.
        Assert.Equal(FunctionReferenceCodec.ColonForbidden, Assert.Throws<FunctionReferenceException>(() => new PackageFunction("fin:ance", "x")).Code);
        Assert.Equal(FunctionReferenceCodec.ColonForbidden, Assert.Throws<FunctionReferenceException>(() => new PackageFunction("finance", "a:b")).Code);

        // The display form is not a wire form: the codec refuses it instead of splitting it.
        Assert.Equal(FunctionReferenceCodec.MalformedReference,
            Assert.Throws<FunctionReferenceException>(() => FunctionReferenceCodec.Read(JsonValue.Create("finance::money.add"))).Code);

        // Round trip through the structured form keeps the arm.
        Assert.Same(builtIn, FunctionReferenceCodec.Read(JsonNode.Parse(builtIn.CanonicalJson)));
        Assert.Equal(package, FunctionReferenceCodec.Read(JsonNode.Parse(package.CanonicalJson)));
    }

    [Fact(DisplayName = "rules-eng-27: each built-in resolves exactly once from the register and every registered key executes")]
    public void Every_registered_built_in_executes()
    {
        var keys = BuiltInFunctionRegister.Functions.Select(function => function.Key).ToList();
        Assert.Equal(keys.Count, keys.Distinct(StringComparer.Ordinal).Count());
        // The register carries exactly the executable v1 built-ins: a deleted entry is a lost built-in.
        Assert.Equal(
            ["var", "missing", "missing_some", "==", "!=", "===", "!==", "!", "!!", "and", "or", "if", ">", ">=", "<", "<=",
             "+", "-", "*", "/", "%", "min", "max", "in", "cat", "agg", "money.add", "money.sub", "money.mul",
             "date.add", "date.diff", "date.today", "coding.is"],
            keys);
        Assert.All(BuiltInFunctionRegister.Functions, function => Assert.Same(function.Reference, BuiltInFunctionRegister.Resolve(function.Key)));

        foreach (var function in BuiltInFunctionRegister.Functions)
        {
            var args = new JsonArray(Enumerable.Range(0, function.MinArity).Select(_ => (JsonNode?)JsonValue.Create("1")).ToArray());
            var ctx = new EvalContext(new NullResolver(), DateTimeOffset.UnixEpoch, new EvalBudget(RuleEngineLimits.Default, CancellationToken.None));
            try
            {
                HarborlineJsonLogic.Evaluate(new JsonObject { [function.Key] = args }, ctx);
            }
            catch (RuleEvalException ex)
            {
                Assert.NotEqual(RuleEngineCodes.UnknownOperator, ex.Error.Code);
            }
        }
        Assert.False(BuiltInFunctionRegister.TryResolve("regex.match", out _));
    }

    [Fact(DisplayName = "rules-eng-27: the evaluator and the compiler read the register rather than a closed switch")]
    public void Evaluator_and_compiler_read_the_register()
    {
        var root = RepositoryRoot();
        var evaluator = File.ReadAllText(Path.Combine(root, "projections", "dotnet", "foundation", "hlp.foundation.rule-runtime", "Evaluation", "HarborlineJsonLogic.cs"));
        var compiler = File.ReadAllText(Path.Combine(root, "projections", "dotnet", "foundation", "hlp.foundation.rule-runtime", "Compilation", "RuleCompiler.cs"));
        Assert.DoesNotContain("return op switch", evaluator, StringComparison.Ordinal);
        Assert.DoesNotContain("\"cat\" =>", evaluator, StringComparison.Ordinal);
        Assert.DoesNotContain("\"coding.is\"", compiler, StringComparison.Ordinal);

        // A key outside the register refuses at publish with the compiler's code.
        var unknown = new RuleDefinition { Id = "r", Tier = RuleTier.JsonLogic, Scope = RuleScope.Field, ScopeTarget = "a", Action = RuleActionKind.Compute, Expression = """{"shadow":[1]}""" };
        Assert.Equal(RuleEngineCodes.CompileInvalidExpression, Assert.Throws<RuleCompilationException>(() => RuleCompiler.Compile([unknown])).Code);
    }

    internal static string RepositoryRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "repository.yaml"))) dir = dir.Parent;
        return dir?.FullName ?? throw new InvalidOperationException("repository root not found");
    }

    private sealed class NullResolver : IValueResolver
    {
        public RefValue ResolveVar(string path) => RefValue.Resolved(null);

        public RefValue ResolveAgg(string fn, string section, string col) => RefValue.Resolved(JsonValue.Create(0));
    }
}

using System.Reflection;
using System.Text.Json.Nodes;

using Harborline.Foundation.RuleEngine.Compilation;
using Harborline.Foundation.RuleEngine.Context;
using Harborline.Foundation.RuleEngine.Functions;
using Harborline.Foundation.RuleEngine.Graph;
using Harborline.Foundation.RuleEngine.References;
using Harborline.Foundation.RuleEngine.Skins;

using Xunit;

namespace Harborline.Foundation.RuleEngine.Tests;

/// <summary>T-590 slice 3: named predicates, exact calculation pins, legality citations and the bounded fold.</summary>
public sealed class NamedReferenceTests
{
    private static readonly GuardEvaluator Guard = new(new FixedClock(new DateTimeOffset(2026, 9, 24, 0, 0, 0, TimeSpan.Zero)));

    private static RuleContextSnapshot Facts(string json)
        => RuleContextSnapshot.Capture(JsonNode.Parse(json)!.AsObject().ToDictionary(p => p.Key, p => p.Value?.DeepClone()));

    [Fact(DisplayName = "rules-ck-22, rules-auth-9: one immutable named predicate is authored once and reused by a view filter, a rule condition, an automation condition, a report population and a Layout guard through its exact pin")]
    public void Named_predicate_is_authored_once_and_reused_by_every_consumer_kind()
    {
        var v1 = new NamedPredicate("overdue", "1.0.0", """{">":[{"var":"days_late"},30]}""");
        var v2 = new NamedPredicate("overdue", "2.0.0", """{">":[{"var":"days_late"},60]}""");
        var closure = new PinnedClosure([v1, v2], []);

        foreach (var consumer in Enum.GetValues<PredicateConsumer>())
        {
            var rule = NamedReferences.Bind(consumer, v1.Pin, closure);
            Assert.Equal(v1.Expression, rule.Expression);
            Assert.True(Guard.EvaluateGuard(rule, Facts("""{"days_late":45}"""), RuleEvalScope.Root, TestAdmission.Any).Ok, consumer.ToString());
        }
        // A new version does not move a consumer that pinned the old one.
        Assert.False(Guard.EvaluateGuard(NamedReferences.Bind(PredicateConsumer.ViewFilter, v2.Pin, closure), Facts("""{"days_late":45}"""), RuleEvalScope.Root, TestAdmission.Any).Ok);
        Assert.NotEqual(v1.Pin.Digest, v2.Pin.Digest);

        // Resolution is from the pinned closure only: absent, tampered or floating pins refuse.
        Assert.Equal(NamedReferences.Unresolved, Assert.Throws<NamedReferenceException>(() => NamedReferences.Bind(PredicateConsumer.RuleCondition, v1.Pin, new PinnedClosure([v2], []))).Code);
        Assert.Equal(NamedReferences.DigestMismatch, Assert.Throws<NamedReferenceException>(() => NamedReferences.Bind(PredicateConsumer.RuleCondition, v1.Pin with { Digest = v2.Pin.Digest }, closure)).Code);
        Assert.Equal(NamedReferences.Floating, Assert.Throws<NamedReferenceException>(() => NamedReferences.Bind(PredicateConsumer.RuleCondition, v1.Pin with { Version = "latest" }, closure)).Code);
        Assert.Equal(NamedReferences.Floating, Assert.Throws<NamedReferenceException>(() => new NamedPredicate("overdue", "^1.0", "true")).Code);
        // The element is immutable: no settable member.
        Assert.DoesNotContain(typeof(NamedPredicate).GetProperties(), p => p.SetMethod is { IsPublic: true });
    }

    [Fact(DisplayName = "rules-ck-23, rules-auth-14: Compute is a pure call through an exact named calculation pin that returns a typed value and writes nothing")]
    public void Compute_is_a_pure_call_through_an_exact_pin()
    {
        var calculation = new NamedCalculation("line-total", "1.0.0", """{"money.mul":[{"var":"price"},{"var":"qty"}]}""");
        var closure = new PinnedClosure([], [calculation]);
        var facts = new Dictionary<string, JsonNode?> { ["price"] = "2.50", ["qty"] = 4 };
        var snapshot = RuleContextSnapshot.Capture(facts);

        var first = NamedReferences.Compute(calculation.Pin, closure, Guard, snapshot, TestAdmission.Any);
        var second = NamedReferences.Compute(calculation.Pin, closure, Guard, snapshot, TestAdmission.Any);
        Assert.Equal("10", first.Value!.GetValue<string>());
        Assert.Equal(first.Value!.ToJsonString(), second.Value!.ToJsonString());
        Assert.Equal(2, facts.Count); // the caller's data is untouched

        Assert.Equal(NamedReferences.Floating, Assert.Throws<NamedReferenceException>(() => NamedReferences.Compute(calculation.Pin with { Version = "*" }, closure, Guard, snapshot, TestAdmission.Any)).Code);
        Assert.Equal(NamedReferences.DigestMismatch, Assert.Throws<NamedReferenceException>(() => NamedReferences.Compute(calculation.Pin with { Digest = new string('0', 64) }, closure, Guard, snapshot, TestAdmission.Any)).Code);
        // There is no inline form: the only way in is a pin.
        Assert.All(typeof(NamedReferences).GetMethods(BindingFlags.Public | BindingFlags.Static).Where(m => m.Name == "Compute"),
            method => Assert.DoesNotContain(method.GetParameters(), p => p.ParameterType == typeof(string)));
    }

    [Fact(DisplayName = "rules-ck-24, rules-auth-15: a legality rule set is cited by exact pin with provenance, jurisdiction and dates preserved, and never interpreted")]
    public void Legality_rule_set_is_cited_never_interpreted()
    {
        var digest = new string('a', 64);
        var citation = new LegalityRuleSetCitation("pack.payroll-uk", "minimum-wage", "2026.1.0", digest, "GB", new DateOnly(2026, 4, 1), new DateOnly(2027, 3, 31));
        Assert.Equal("""{"digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","effectiveFrom":"2026-04-01","effectiveTo":"2027-03-31","jurisdiction":"GB","name":"minimum-wage","packageId":"pack.payroll-uk","version":"2026.1.0"}""", citation.CanonicalJson);

        // No body, no expression, no evaluate: Rules cannot interpret what it only cites.
        Assert.DoesNotContain(typeof(LegalityRuleSetCitation).GetMembers(BindingFlags.Public | BindingFlags.Instance),
            m => m.Name.Contains("Expression", StringComparison.Ordinal) || m.Name.Contains("Evaluate", StringComparison.Ordinal) || m.Name.Contains("Body", StringComparison.Ordinal));
        Assert.Throws<NamedReferenceException>(() => new LegalityRuleSetCitation("pack", "minimum-wage", "latest", digest, "GB", new DateOnly(2026, 4, 1), null));
        Assert.Throws<NamedReferenceException>(() => new LegalityRuleSetCitation("pack", "minimum-wage", "1.0.0", digest, " ", new DateOnly(2026, 4, 1), null));
        Assert.Throws<NamedReferenceException>(() => new LegalityRuleSetCitation("pack", "minimum-wage", "1.0.0", digest, "GB", new DateOnly(2026, 4, 1), new DateOnly(2026, 3, 1)));
    }

    [Fact(DisplayName = "rules-eng-16, rules-bound-4: agg folds only a named bounded child collection with a registered fold, and every registered fold executes")]
    public void Agg_is_a_bounded_fold_over_a_named_child_collection()
    {
        var instance = RuleInstance.FromJson(JsonNode.Parse("""{"items":[{"id":"a","amount":2,"ok":true},{"id":"b","amount":5,"ok":false}]}""")!.AsObject());
        foreach (var fold in BuiltInFunctionRegister.AggregateFolds)
        {
            var column = fold is "any" or "all" ? "ok" : "amount";
            var compiled = RuleCompiler.Compile([RuleDefinitionFactory.Create("f", RuleTier.JsonLogic, RuleScope.Field, "out", $$"""{"var":"table.{{fold}}(items.{{column}})"}""", RuleActionKind.Compute)]);
            var value = new FormRuleGraph(compiled, new FixedClock(DateTimeOffset.UnixEpoch), TestAdmission.Any).EvaluateInstance(instance).Values["field:out"];
            Assert.Equal(Model.ValueState.Resolved, value.State);
        }
        // An unregistered fold, a dynamic collection or a non-literal fold is not a bounded fold.
        foreach (var expression in new[] { """{"agg":["median","items","amount"]}""", """{"agg":["search","items","amount"]}""", """{"agg":["sum",{"var":"field.section"},"amount"]}""", """{"var":"table.lookup(items.amount)"}""" })
            Assert.Equal(RuleEngineCodes.CompileBadGrammar, Assert.Throws<RuleCompilationException>(() => RuleCompiler.Compile(
                [RuleDefinitionFactory.Create("f", RuleTier.JsonLogic, RuleScope.Field, "out", expression, RuleActionKind.Compute)])).Code);
    }

    [Fact(DisplayName = "rules-auth-27, rules-auth-28: search, query, interval overlap, taxonomy traversal, catalogue-measure calculation and unbounded folds refuse at publish")]
    public void Search_query_taxonomy_and_measure_calculation_refuse()
    {
        string[] refused =
        [
            """{"search":["assets","pump"]}""", """{"query":["assets",{"==":[{"var":"kind"},"pump"]}]}""",
            """{"interval.overlaps":[{"var":"a"},{"var":"b"}]}""", """{"taxonomy.subsumes":["asset-class","rotating","pump"]}""",
            """{"taxonomy.succeeds":["status","open","closed"]}""", """{"coding.descendant":[{"var":"c"},"sys","parent"]}""",
            """{"measure":["asset.condition-score"]}""", """{"reduce":[{"var":"items"},{"+":[1,1]},0]}""",
            """{"filter":[{"var":"items"},true]}""", """{"map":[{"var":"items"},1]}""",
        ];
        foreach (var expression in refused)
            Assert.Equal(RuleEngineCodes.CompileInvalidExpression, Assert.Throws<RuleCompilationException>(() => RuleCompiler.Compile(
                [RuleDefinitionFactory.Create("r", RuleTier.JsonLogic, RuleScope.Field, "out", expression, RuleActionKind.Compute)])).Code);

        // coding.is is exact membership: it never matches a descendant, so no subsumption hides in it.
        var coded = RuleDefinitionFactory.Create("c", RuleTier.JsonLogic, RuleScope.Schema, "", """{"coding.is":[{"var":"c"},"asset-class","rotating"]}""", RuleActionKind.Validate);
        Assert.True(Guard.EvaluateGuard(coded, Facts("""{"c":{"system":"asset-class","code":"rotating"}}"""), RuleEvalScope.Root, TestAdmission.Any).Ok);
        Assert.False(Guard.EvaluateGuard(coded, Facts("""{"c":{"system":"asset-class","code":"pump"}}"""), RuleEvalScope.Root, TestAdmission.Any).Ok);

        // The engine assembly cannot reach a catalogue or a search: it references only contracts and schema validation.
        Assert.Equal(["Harborline.Contracts", "Harborline.Kernel.SchemaValidation", "System.Runtime"], typeof(GuardEvaluator).Assembly.GetReferencedAssemblies()
            .Select(a => a.Name!).Where(n => n.StartsWith("Harborline", StringComparison.Ordinal) || n == "System.Runtime").Order(StringComparer.Ordinal));
    }

    [Fact(DisplayName = "rules-eng-16: the asset-scoring decision table (ADR 0096 ruling 5c) folds supplied measure results already in scope and never calls the catalogue")]
    public void Asset_scoring_decision_table_reads_supplied_measure_values()
    {
        var table = new DecisionTableSkin("asset.score", RuleScope.Field, "score", RuleActionKind.Compute, HitPolicy.Priority,
            ["field.measure_condition_score", "field.measure_criticality"],
            [
                new DecisionRow([DecisionCell.Range(JsonValue.Create(0), JsonValue.Create(40)), DecisionCell.Compare(">=", JsonValue.Create(3))], JsonValue.Create("replace"), 10),
                new DecisionRow([DecisionCell.Range(JsonValue.Create(0), JsonValue.Create(70)), DecisionCell.Wildcard], JsonValue.Create("inspect"), 5),
            ],
            NoMatch.WithDefault(JsonValue.Create("monitor")));
        var rule = DecisionTableCompiler.Compile(table);
        var graph = new FormRuleGraph(RuleCompiler.Compile([rule]), new FixedClock(DateTimeOffset.UnixEpoch), TestAdmission.Any);
        string Score(string json) => graph.EvaluateInstance(RuleInstance.FromJson(JsonNode.Parse(json)!.AsObject())).Values["field:score"].Value!.GetValue<string>();

        Assert.Equal("replace", Score("""{"measure_condition_score":35,"measure_criticality":4}"""));
        Assert.Equal("inspect", Score("""{"measure_condition_score":35,"measure_criticality":1}"""));
        Assert.Equal("monitor", Score("""{"measure_condition_score":90,"measure_criticality":5}"""));
    }
}

using Xunit;

namespace Harborline.Foundation.RuleEngine.Tests;

/// <summary>
/// D1 ratification fix 3 (2026-07-01): the <b>operator-catalog erosion guard</b>. A STANDING
/// arch-test that pins the CLOSED <c>harborline-jsonlogic/v1</c> operator set + the regex-exclusion
/// invariant, so a new operator (or a regex/pattern construct) cannot slip into the evaluator at a
/// version bump without tripping this test — the "one convenience operator erodes A into B, one PR
/// at a time" (Form.io) trajectory the D1 council named. Adding/removing/renaming an operator
/// REQUIRES a deliberate edit to <see cref="FrozenV1Operators"/> below — which is exactly the review
/// checkpoint the guard exists to force. It source-scans the evaluator so it is author-independent
/// (it cannot be defeated by forgetting to update a parallel catalog constant).
/// </summary>
public sealed class OperatorCatalogArchTests
{
    /// <summary>
    /// The frozen, closed <c>harborline-jsonlogic/v1</c> operator set (design §1.4 / README). DELIBERATELY
    /// EXCLUDED: any regex/pattern operator (ReDoS structurally absent — Decision DG); and
    /// <c>map</c>/<c>filter</c>/<c>reduce</c>/<c>merge</c> (deferred — child-table folds use <c>agg</c>).
    /// The TS tier pins the IDENTICAL set in <c>operator-catalog.test.ts</c>.
    /// </summary>
    private static readonly IReadOnlySet<string> FrozenV1Operators = new HashSet<string>(StringComparer.Ordinal)
    {
        "var", "missing", "missing_some",
        "==", "!=", "===", "!==", "!", "!!", "and", "or", "if",
        ">", ">=", "<", "<=",
        "+", "-", "*", "/", "%", "min", "max",
        "in", "cat",
        "agg", "money.add", "money.sub", "money.mul",
        "date.add", "date.diff", "date.today", "coding.is",
    };

    [Fact]
    public void Evaluator_implements_EXACTLY_the_frozen_v1_operator_set()
    {
        // Since T-590 the R1 register is the evaluator's only dispatch table (rules-eng-27), so the
        // guard pins the register instead of scanning a switch that no longer exists.
        var implemented = Functions.BuiltInFunctionRegister.Functions.Select(f => f.Key).ToHashSet(StringComparer.Ordinal);

        var added = implemented.Except(FrozenV1Operators).OrderBy(s => s, StringComparer.Ordinal).ToList();
        var removed = FrozenV1Operators.Except(implemented).OrderBy(s => s, StringComparer.Ordinal).ToList();

        Assert.True(added.Count == 0,
            $"NEW operator(s) added to the register without deliberate review: [{string.Join(", ", added)}]. "
            + "The harborline-jsonlogic/v1 set is CLOSED (D1). If intended, amend FrozenV1Operators + the TS "
            + "operator-catalog test + the README operator table + design §1.4 — never silently.");
        Assert.True(removed.Count == 0,
            $"operator(s) removed from the register: [{string.Join(", ", removed)}]. Removing an operator "
            + "breaks the closed v1 set — amend FrozenV1Operators deliberately if this is intended.");
    }

    [Fact]
    public void Evaluator_uses_NO_regex_construct_so_ReDoS_is_structurally_absent()
    {
        string source = ReadEvaluatorSource();
        foreach (var banned in new[] { "Regex", "RegularExpressions", "GeneratedRegex" })
        {
            Assert.False(source.Contains(banned, StringComparison.Ordinal),
                $"the Tier-2 evaluator must not use '{banned}': regex/pattern is excluded from v1 (Decision DG) "
                + "so the ReDoS class is structurally absent. Pattern validation stays in Tier-1 JSON-Schema.");
        }
    }

    [Fact]
    public void No_frozen_operator_names_a_regex_or_pattern_construct()
    {
        foreach (var op in FrozenV1Operators)
        {
            foreach (var banned in new[] { "regex", "pattern", "match", "search" })
            {
                Assert.False(op.Contains(banned, StringComparison.OrdinalIgnoreCase),
                    $"operator '{op}' names a regex/pattern construct — excluded from v1 (Decision DG).");
            }
        }
    }

    private static string ReadEvaluatorSource()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "repository.yaml"))) dir = dir.Parent;
        Assert.True(dir is not null, "could not locate the Harborline Platform repository root to read the evaluator source");
        string path = Path.Combine(dir!.FullName, "projections", "dotnet", "foundation", "hlp.foundation.rule-runtime", "Evaluation", "HarborlineJsonLogic.cs");
        Assert.True(File.Exists(path), $"evaluator source not found at {path}");
        return File.ReadAllText(path);
    }
}

